local _, ns = ...
local E = ns.DB.entries
E["item:alien-egg"] = {t="item",n="Alien Egg",z="thousandneedles",s="The Alien Egg is an unusual and mysterious clutch found guarded by local wind serpents across the canyons of Thousand Needles. Despite its unfamiliar appearance, the native serpents protect the egg fiercely as if it were their own. Its presence has aroused the curiosity and concern of the tauren scouts stationed atop Freewind Post.",h="The Alien Egg is an unusual and mysterious clutch found guarded by local wind serpents across the canyons of...",sec={{t="A Serpent's Brood",b="Discovered resting at the base of the towering spires south and northeast of Freewind Post, the Alien Egg stands out dramatically from the typical fauna of the canyon floor. Rather than abandoning or destroying the odd clutch, the native serpents of the needles fiercely guard it alongside their own nests. Hagar Lightninghoof, a tauren brave keeping watch from the heights of Freewind Post, sought to retrieve the specimen to determine whether it represented a threat to the mesa settlements or merely an unusual variation of local reptilian life.",sp=0},{t="The Spawn of Arikara",b="When brought to Freewind Post and subjected to closer inspection, the mysterious shell immediately breaks open. It does not contain an extraterrestrial invader: out of it emerges Arikara, the red wind serpent of tauren legend, believed to be a spirit of vengeance. The young serpent swiftly takes flight, and a shaken Hagar declares that vengeance itself has come to Thousand Needles, setting off a chain of events that leads the local defenders to confront her.",sp=1}},faq={{q="Why is the egg called 'alien'?",a="The term 'alien' is used in the traditional sense of being completely foreign and unfamiliar to the local tauren scouts, rather than implying it came from outer space. Its coloration and markings were entirely unlike ordinary wind serpent clutches found in Thousand Needles.",al={"alien egg name","why alien","is it from space"},it="name"},{q="Where can the Alien Egg be found?",a="The egg rests on the canyon floor near the base of the mesa walls both to the south and northeast of Freewind Post in Thousand Needles. It is invariably surrounded and guarded by hostile wind serpents.",al={"egg location","where is alien egg","find alien egg"},it="place",gp=true},{q="Why do the local serpents guard the egg?",a="No one knows for certain. The serpents guard the egg as if it were one of their own, and those who report seeing it have failed to even get close enough to examine it.",al={"why do serpents protect it","serpents guarding egg"},sp=1,it="ties"},{q="What happens when you bring the egg to Hagar Lightninghoof?",a="Upon delivery to Hagar Lightninghoof at Freewind Post, the egg hatches before his eyes. What flies out of it shakes Hagar so badly that he sends for the counsel of Motega Firemane at once.",al={"hagar egg turn in","what hatches"},sp=1,it="next_step"},{q="What is the Alien Egg?",a="The Alien Egg is an unusual, mysterious clutch found resting among the wild wind serpents of Thousand Needles. Unlike typical serpent eggs of the region, its strange appearance caught the attention of scouts and shamans at Freewind Post. Despite its foreign nature, the local serpents protect it fiercely as if it were their own brood.",al={"what is alien egg","alien egg info","about alien egg"},it="identity",add=true},{q="Why does Hagar Lightninghoof want the Alien Egg?",a="Hagar Lightninghoof at Freewind Post heard rumors of a bizarre egg guarded by local serpents that none of his scouts could get close enough to study. Driven by curiosity and caution, he asks brave adventurers to recover the egg so he can inspect it directly and uncover what kind of creature might hatch from it.",al={"why want alien egg","why does hagar want the egg","alien egg purpose"},it="why_wanted",add=true}},ang={["race:Tauren"]="The tauren of Freewind Post keep constant vigil over the canyon below, viewing the appearance of unknown creatures as an omen or a direct threat to their precarious cliffside settlement.",["class:Hunter"]="Wind serpents are among the most revered beasts of the Kalimdor barrens, and tracking down one of their rarest and most guarded clutches tests every instinct of the hunt."},kw={"alien egg","freewind post","hagar lightninghoof","thousand needles","wind serpent"},rel={"quest:4821","quest:5088","npc:hagar-lightninghoof","subzone:freewind-post","zone:thousandneedles"},src={"Alien Egg","Alien Egg (quest)"}}
E["item:arnak-s-hoof"] = {t="item",n="Arnak's Hoof",z="thousandneedles",s="Arnak's Hoof is the macabre proof of death taken from the criminal Arnak Grimtotem. Hunted down on the bluffs of Darkcloud Pinnacle, Arnak was marked for execution by the defenders of Freewind Post after murdering a fellow tauren and kidnapping his sister.",h="Arnak's Hoof is the macabre proof of death taken from the criminal Arnak Grimtotem.",sec={{t="Bounty on an Outcast",b="Arnak Grimtotem earned notoriety throughout Thousand Needles as an outlaw whose brutality crossed even the contentious lines of tauren clan politics. After murdering another tauren and abducting the victim's sister, Lakota Windsong, a formal bounty was posted for his death. Arnak holed up on the heights of Darkcloud Pinnacle, surrounded by Grimtotem guards. Slaying him and claiming his severed hoof serves as undeniable confirmation for Cliffwatcher Longhorn at Freewind Post that the murderer has finally answered for his crimes.",sp=0}},faq={{q="What is Arnak's Hoof used for?",a="Arnak's Hoof serves as physical proof of the death of the outlaw Arnak Grimtotem. It is turned in to Cliffwatcher Longhorn at Freewind Post to complete the wanted bounty and claim the promised reward.",al={"arnak hoof turn in","what do i do with arnak's hoof","who wants arnak's hoof"},it="purpose",gp=true},{q="Who was Arnak Grimtotem?",a="Arnak was a Grimtotem renegade wanted for murder and kidnapping. He slew a tauren tribesman and held the victim's sister, Lakota Windsong, captive on the bluffs of Darkcloud Pinnacle.",al={"who is arnak","arnak grimtotem lore","why is arnak wanted"},it="people"},{q="Where is Arnak Grimtotem found?",a="Arnak is located on the cliffs of Darkcloud Pinnacle in northern Thousand Needles, accessible via rope bridges near the crags approaching Razorfen Downs. He keeps his captive, Lakota Windsong, on the same bluff.",al={"arnak grimtotem location","where is arnak","how to find arnak"},it="place",gp=true},{q="What is Arnak's Hoof?",a="This severed hoof serves as undeniable proof that the outlaw tauren Arnak Grimtotem has been slain. Taken directly from his body atop the windswept mesas of Thousand Needles, it is carried back to Freewind Post to confirm that justice has finally caught up with the outcast rogue.",al={"arnak hoof","what is this hoof","arnaks hoof"},it="identity",add=true},{q="Where does Arnak's Hoof come from?",a="It is taken from Arnak Grimtotem, a renegade tauren lurking on the cliffs near Darkcloud Pinnacle. Rather than being forged or crafted, it is a physical trophy claimed after confronting and slaying him at his hideout overlooking the canyons.",al={"where do you get arnaks hoof","who made arnaks hoof","arnak hoof origin"},it="origin",add=true},{q="Why does anyone want Arnak's Hoof?",a="Cliffwatcher Longhorn in Freewind Post posted a bounty demanding proof of Arnak's demise. Arnak committed heinous crimes—slaying an innocent tauren and kidnapping his sister, Lakota Windsong. Delivering his hoof fulfills the bounty and earns the gratitude and coin of Freewind Post's protectors.",al={"who wants arnaks hoof","why turn in arnak hoof","why want arnak hoof"},it="why_wanted",add=true}},ang={["race:Tauren"]="For the tauren of the plains, taking Arnak's hoof is an act of tribal justice against a renegade whose murderous conduct brought dishonor and bloodshed to Thousand Needles.",["faction:Horde"]="Eliminating Arnak secures Freewind Post's authority in Thousand Needles and weakens the treacherous Grimtotem influence threatening Horde supply routes."},kw={"arnak","arnak grimtotem","arnak's hoof","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","thousand needles"},rel={"quest:5147","npc:cliffwatcher-longhorn","npc:lakota-windsong","subzone:darkcloud-pinnacle","subzone:freewind-post","quest:4904","quest:5064","zone:thousandneedles"},src={"Arnak's Hoof","Wanted - Arnak Grimtotem"}}
E["item:crate-of-crash-helmets"] = {t="item",n="Crate of Crash Helmets",z="thousandneedles",s="A heavy supply shipment of dwarven Siege Engine headgear destined for the Shimmering Flats in Thousand Needles. The sturdy helmets are urgently required by the Brassbolts brothers to protect test drivers from concussions caused by their experimental rocket cars.",h="A heavy supply shipment of dwarven Siege Engine headgear destined for the Shimmering Flats in Thousand...",sec={{t="Safety at High Speeds",b="Out across the blinding white expanse of the Shimmering Flats, gnome engineers test the absolute limits of mechanical propulsion. Unfortunately for the test pilots, the experimental rocket cars designed by the Brassbolts brothers move far faster than their steering can reliably handle. With drivers routinely suffering violent crashes and head trauma, ordinary leather caps no longer suffice. To prevent their roster of willing daredevils from vanishing entirely, heavy-duty dwarven Siege Engine helmets are packed and dispatched across the sea to keep drivers conscious—and alive.",sp=0}},faq={{q="What is inside the Crate of Crash Helmets?",a="The crate contains heavy Siege Engine helmets acquired from dwarven military stocks. Built to withstand concussive explosions and violent vehicle impacts, they offer the thickest head protection available for high-speed trials.",al={"crate contents","what helmets are these","crash helmets type"},it="identity"},{q="Who needs these helmets?",a="They are sent to Wizzle Brassbolts and his brother out at the Mirage Raceway in the Shimmering Flats. Their reckless vehicle designs repeatedly knock out test pilots, creating an acute need for serious head protection.",al={"who gets the helmets","who is the crate for","helmet destination"},it="why_wanted"},{q="Why are the Brassbolts brothers crashing so much?",a="Gnomish vehicle design prioritizes raw speed and technological boundary-pushing over stable handling. The brothers built an exceptionally fast rocket car, but its sheer velocity makes collisions on the salt flats almost unavoidable.",al={"why do they crash","rocket car problems","gnome racing crashes"},it="motive"},{q="Where are the helmets being delivered?",a="The shipment must be brought down to the Shimmering Flats, the vast salt plain resting in the southeastern reaches of Thousand Needles in Kalimdor.",al={"delivery location","where is wizzle","where do these go"},it="purpose"},{q="Where does the Crate of Crash Helmets come from, and who made it?",a="The crate is packed and provided by the dwarven engineer Pilot Longbeard in Dun Morogh. Longbeard gathered a supply of sturdy dwarven Siege Engine helmets to help his old friends, the Brassbolts brothers, who are desperately in need of head protection for their test pilots out in the Shimmering Flats.",al={"who made crate of crash helmets","where did crate of crash helmets come from","crash helmets origin"},it="origin",add=true}},ang={["profession:Engineering"]="Any engineer understands the delicate balance between maximum propulsion and catastrophic failure—and the absolute necessity of heavy armor when safety features are an afterthought.",["race:Gnome"]="For gnomes at the Mirage Raceway, pilot concussions are simply the cost of doing business when out-innovating goblin rivals on the salt flats."},kw={"crate of crash helmets","mirage raceway","rocket car","shimmering flats","siege engine","thousand needles","wizzle brassbolts"},rel={"quest:1179","npc:wizzle-brassbolts","subzone:shimmering-flats","zone:thousandneedles","topic:gnome"},src={"Crate of Crash Helmets","The Brassbolts Brothers"}}
E["item:fragments-of-rok-alim"] = {t="item",n="Fragments of Rok'Alim",z="thousandneedles",s="Fragments of Rok'Alim are the shattered stone remains of a primeval earth elemental roaming the canyons of Thousand Needles. Brought to Dorn Plainstalker at the Weathered Nook, they serve as undeniable physical proof that a warrior has bested an ancient terror in single combat.",h="Fragments of Rok'Alim are the shattered stone remains of a primeval earth elemental roaming the canyons of...",sec={{t="Remnants of an Ancient Power",b="While most elementals faded from Azeroth following the banishment of the Old Gods, a handful possessed enough raw power to endure on the surface without being summoned by mortal magic. Rok'Alim the Pounder is one such survivor, wandering the canyon flats south of the main thoroughfare. Local centaur know him by the thunderous crashes of his stony fists pulverizing anything foolish enough to wander into his path. Striking down this living remnant of the primordial world yields jagged pieces of dense, animated rock—a trophy fit to prove unmatched physical prowess.",sp=0},{t="The Trial of Might",b="For the tauren hermit Dorn Plainstalker, recovering the fragments is the decisive component of the Test of Strength. As part of a series of spiritual and martial rites conducted high within the Weathered Nook, the trial demands that an initiate face an entity of unyielding brute force. Delivering the battered rubble of Rok'Alim proves that an adventurer possesses the bravery and physical might required to survive the harshest perils of Kalimdor.",sp=0}},faq={{q="What are the Fragments of Rok'Alim?",a="They are the broken stone remains of Rok'Alim the Pounder, an ancient earth elemental who prowls the north-western canyons of Thousand Needles. They act as proof of the elemental's defeat.",al={"fragments of rokalim","what are rokalim fragments","rokalims stone"},it="identity"},{q="Who wants these stone fragments?",a="Dorn Plainstalker, a tauren questgiver residing at the Weathered Nook high along the canyon cliffs of Thousand Needles, asks for the fragments to conclude the Test of Strength.",al={"who takes rokalim fragments","turn in fragments of rokalim","dorn plainstalker quest"},it="why_wanted"},{q="Why is Rok'Alim significant?",a="Unlike most modern elementals that must be conjured by mortal mages, Rok'Alim has lingered in the world since the era of the Old Gods. Centaur tribes in the canyons gave him the name 'the Pounder' due to the booming noise of his fists crushing his prey.",al={"why is rokalim special","rokalim lore","who is rokalim the pounder"},it="power"},{q="Where is Rok'Alim found?",a="Rok'Alim roams the north-western basin of Thousand Needles, wandering south of the region's main road between the sandstone spires.",al={"rokalim location","find rokalim the pounder","where does rokalim spawn"},it="place",gp=true},{q="Where do the Fragments of Rok'Alim come from?",a="These fragments are shattered pieces of Rok'Alim the Pounder, a massive rock elemental wandering the north-western canyon floor of Thousand Needles. Unlike elementals conjured by mortal spellcasters, Rok'Alim is an ancient survivor from the era of the Old Gods, possessing enough innate power to remain tethered to the world even after his masters fell. They were not crafted by mortal hands, but broken directly from his living stone form.",al={"fragments of rokalim origin","where do rokalim fragments come from","who made rokalim fragments"},it="origin",add=true}},ang={["race:Tauren"]="Overcoming enduring remnants of Azeroth's primordial past aligns closely with tauren traditions of testing harmony, fortitude, and personal strength against the land's most formidable hazards.",["class:Shaman"]="Rok'Alim represents an ancient earth spirit bound to the world long before modern shamanic pacts, making his unyielding nature an intriguing study in raw elemental tenacity."},kw={"dorn plainstalker","elemental","fragments","pounder","rok'alim","test of strength","thousand needles","weathered nook"},rel={"quest:1151","npc:dorn-plainstalker","subzone:weathered-nook","zone:thousandneedles","quest:1149","topic:old-god","topic:centaur","topic:horde"},src={"Fragments of Rok'Alim","Test of Strength"}}
E["item:grenka-s-claw"] = {t="item",n="Grenka's Claw",z="thousandneedles",s="Grenka's Claw is a physical trophy taken from the formidable harpy Grenka Bloodscreech in the depths of Roguefeather Den. Presented to Dorn Plainstalker at the Weathered Nook, it serves as undeniable proof that an aspiring adventurer has endured a grueling physical trial in the canyon heights.",h="Grenka's Claw is a physical trophy taken from the formidable harpy Grenka Bloodscreech in the depths of...",sec={{t="A Trophy of Endurance",b="Within the winding caverns of Roguefeather Den, west of Freewind Post, harpies cache food and violently defend their territory against outsiders. To test the physical resilience of young champions, Dorn Plainstalker tasks them with invading the deep roosts and destroying the flock's food reserves. Such brazen provocation inevitably draws the fury of Grenka Bloodscreech. Severing and returning her wicked talon proves that a warrior can withstand wave after wave of enraged harpies and survive the vicious onslaught of their matriarch.",sp=0}},faq={{q="What is Grenka's Claw used for?",a="The claw serves as proof of victory for Dorn Plainstalker, a tauren elder residing at the Weathered Nook in Thousand Needles. Handing it to him completes the Test of Endurance, demonstrating that you possess the physical grit required to survive prolonged combat.",al={"use of grenka claw","why do i need grenkas claw","grenkas claw quest"},it="why_wanted",gp=true},{q="Who is Grenka Bloodscreech?",a="Grenka Bloodscreech is a powerful harpy who roosts within the Roguefeather Den, located in the Screeching Canyon along the southern cliffs of Thousand Needles. She emerges only when intruders threaten the flock by destroying their stored foodstuffs.",al={"who is grenka","grenka bloodscreech lore","what is grenka"},it="origin"},{q="Where do I take the claw once I obtain it?",a="Bring the claw back to Dorn Plainstalker at the Weathered Nook, nestled in the bluffs of Thousand Needles. He accepts the trophy to verify that your trial of physical endurance has succeeded.",al={"where to turn in grenka claw","who wants grenkas claw"},it="next_step",gp=true},{q="Why does Dorn Plainstalker demand this specific trophy?",a="Dorn Plainstalker guides young travelers through rigorous trials to ensure they are mentally, spiritually, and physically equipped for greater perils. Slaying Grenka and claiming her claw proves that a warrior can endure both the ambush of a swarm and the direct assault of a deadly leader.",al={"why dorn wants claw","purpose of the claw"},it="why_wanted"},{q="What is Grenka's Claw?",a="Grenka's Claw is a physical trophy taken from Grenka Bloodscreech, a formidable harpy dwelling deep within the Roguefeather Den in Screeching Canyon. Severed from the vicious creature after provoking and surviving the wrath of her flock, the claw serves as undeniable proof that an aspiring adventurer possessed the stamina and martial prowess to withstand a brutal trial of combat.",al={"grenkas claw","what is grenka claw","about grenkas claw"},it="identity",add=true}},ang={["race:Tauren"]="Elder Dorn Plainstalker sees it as his sacred duty to steel young Horde champions through the wisdom and grit of tauren rites before they face the wider, harsher world.",["faction:Horde"]="Clearing the deep reaches of Roguefeather Den and putting down Grenka Bloodscreech blunts the harpy threat that constantly harasses travelers around Freewind Post."},kw={"dorn plainstalker","grenka bloodscreech","grenka's claw","harpy","roguefeather den","screeching canyon","test of endurance","thousand needles","weathered nook"},rel={"quest:1150","quest:1149","npc:dorn-plainstalker","subzone:roguefeather-den","subzone:weathered-nook","zone:thousandneedles","subzone:freewind-post","topic:harpy"},src={"Grenka's Claw","Test of Endurance"}}
E["item:hardened-tortoise-shell"] = {t="item",n="Hardened Tortoise Shell",z="thousandneedles",s="Hardened Tortoise Shells are remarkably durable carapaces harvested from the sparkleshell tortoises wandering the Shimmering Flats. Coveted by gnomish racers at the Mirage Raceway, these rugged organic plates offer unmatched resistance against volatile and corrosive experimental fuels.",h="Hardened Tortoise Shells are remarkably durable carapaces harvested from the sparkleshell tortoises wandering...",sec={{t="Natural Armor for High-Speed Hazards",b="The sun-scorched expanse of the Shimmering Flats is home to various breeds of sparkleshell tortoises, including snappers and borers, whose carapaces have evolved into exceptionally tough defenses against the harsh desert salt and wandering predators. Out on the salt flats, standard metal alloy fuel tanks frequently corrode or rupture under the strain of gnomish experimental chemistry. Mechanics like Wizzle Brassbolts prize these shells not for armor or shields, but as organic raw material tough enough to be retrofitted into makeshift, acid-resistant fuel tanks capable of containing volatile rocket propellants.",sp=0}},faq={{q="Where do you find Hardened Tortoise Shells?",a="They are gathered from sparkleshell tortoises—specifically Sparkleshell Snappers, Borers, and common Sparkleshell Tortoises—wandering across the open salt expanses of the Shimmering Flats in Thousand Needles.",al={"where to get tortoise shells","hardened shell location","sparkleshell location"},it="place",gp=true},{q="Why does Wizzle Brassbolts want these shells?",a="Wizzle's brother is designing an extremely powerful, corrosive rocket fuel that threatens to melt straight through their race car's chassis. Wizzle intends to hollow out and reinforce the tortoises' exceptionally durable carapaces to use as chemically resistant fuel tanks.",al={"why need shells","wizzle shells use","what are shells for"},it="why_wanted"},{q="Can standard workshop tools easily shape them?",a="No. The carapaces are so unnaturally hard that gnomish mechanics expect to bend and ruin an entire toolbox worth of metal implements just trying to carve, drill, and shape them into tanks.",al={"are shells hard to craft","bending tools shell"}},{q="What is a Hardened Tortoise Shell?",a="It is the exceptionally durable, natural outer carapace harvested from the large sparkleshell tortoises roaming the salt flats. These shells are known to be far tougher than ordinary beast hides or standard plating, resisting friction, salt, and intense chemical erosion.",al={"what is hardened tortoise shell","hardened tortoise shell item","hardened shell"},it="identity",add=true},{q="Where does a Hardened Tortoise Shell come from?",a="These shells are completely natural rather than manufactured. They are harvested directly from the sparkleshell tortoises, snappers, and borers that thrive in the harsh, sun-baked salt wilderness of the Shimmering Flats in Thousand Needles.",al={"origin of hardened tortoise shell","who made hardened tortoise shell","where do hardened shells come from"},it="origin",add=true}},ang={["profession:Engineering"]="Using organic carapaces as high-pressure fuel tanks is unconventional, but when gnome-brewed fuel melts standard alloy piping, high-durability natural materials often step in.",["race:Gnome"]="Only gnomish ingenuity would see a desert tortoise and immediately think of a lightweight, highly resilient container for dangerous rocket fuel."},kw={"hardened tortoise shell","mirage raceway","rocket car","shimmering flats","sparkleshell","wizzle brassbolts"},rel={"quest:1105","npc:wizzle-brassbolts","subzone:shimmering-flats","subzone:mirage-raceway","zone:thousandneedles","topic:gnome"},src={"Hardened Tortoise Shell","Hardened Shells"}}
E["item:highperch-wyvern-egg"] = {t="item",n="Highperch Wyvern Egg",z="thousandneedles",s="Highperch Wyvern Eggs are clutch eggs gathered from the nesting grounds atop the high mesas of Thousand Needles. They are sought after by aspiring Horde wind riders to raise and train new aerial mounts.",h="Highperch Wyvern Eggs are clutch eggs gathered from the nesting grounds atop the high mesas of Thousand...",sec={{t="Nests on the Mesa",b="The high plateau of Highperch in Thousand Needles provides a natural sanctuary for native wyverns to roost and raise their young. Accessible only via steep winding paths up the canyon walls, these nesting grounds are fiercely guarded by adult beasts. The eggs laid among these roosts are sturdy and warm, holding developing hatchlings capable of adapting to the harsh skies of Kalimdor.",sp=0},{t="Raising New Wind Riders",b="Across Kalimdor, the demand for trained wyverns continually outstrips supply as the Horde expands its courier and scouting networks. At Freewind Post, trainees like the tauren Elu seek out intact eggs directly from wild aeries. By raising the hatchlings from their shells, handlers hope to forge the deep bonds required to train trustworthy winged mounts for the Horde's wind riders.",sp=0}},faq={{q="Where are these eggs found?",a="They lie scattered within nests across Highperch, an elevated mesa located along the southern rock walls of Thousand Needles, accessible via a pathway leading up from the canyon floor.",al={"egg locations","where to find wyvern eggs","highperch eggs location"},it="place",gp=true},{q="Why does the Horde collect wild wyvern eggs?",a="The Horde's wind rider ranks are growing, and handlers struggle to train enough adult wyverns to meet demand. Trainees like Elu gather eggs so they can rear hatchlings from birth, preparing both beast and rider for aerial duty.",al={"why steal wyvern eggs","what are the eggs used for","elu egg quest purpose"},it="why_wanted"},{q="Are the parent wyverns hostile to egg gatherers?",a="Yes. Wild wyverns are fiercely protective of their nests and will violently assault any intruders who trespass onto Highperch to tamper with their clutches.",al={"do wyverns attack","are wyverns protective"},it="threat",gp=true},{q="Who accepts these eggs in Freewind Post?",a="Elu, an aspiring wind rider stationed atop Freewind Post, collects the eggs in hopes of beginning his own formal mount training.",al={"who takes wyvern eggs","elu freewind post"},it="target",gp=true},{q="What is a Highperch Wyvern Egg?",a="These are the viable eggs of wild wyverns nesting high atop the canyon mesas of Thousand Needles. Within their sturdy shells rest the unhatched young of Kalimdor's winged predators, highly sought after by those wishing to raise loyal aerial mounts from infancy.",al={"what is highperch wyvern egg","wyvern egg info","what are these eggs"},it="identity",add=true},{q="Where do Highperch Wyvern Eggs come from?",a="They are laid by wild wyverns in their clifftop nests at Highperch, an elevated plateau rising above the canyons of Thousand Needles. The adult wyverns guard their aeries fiercely against predators and daring scavengers alike.",al={"where do highperch wyvern eggs come from","who laid the eggs","wyvern egg origin"},it="origin",add=true}},ang={["faction:Horde"]="Reliable aerial travel is vital for maintaining communication and military readiness across the vast territories of Kalimdor, making the procurement of fresh wyvern stock a matter of strategic importance.",["class:Hunter"]="Navigating the perilous heights of Highperch demands an understanding of fierce predator behavior, as adult wyverns defend their nesting grounds with razor claws and venomous stingers."},kw={"elu","freewind post","highperch","highperch wyvern egg","thousand needles","wind rider","wyvern"},rel={"quest:4767","subzone:highperch","subzone:freewind-post","subzone:whitereach-post","zone:thousandneedles","topic:horde"},src={"Highperch Wyvern Egg","Wind Rider (quest)"}}
E["item:hollow-vulture-bone"] = {t="item",n="Hollow Vulture Bone",z="thousandneedles",s="Hollow Vulture Bones are lightweight, durable skeletal remains harvested from the scavengers of the Shimmering Flats. At the Mirage Raceway, goblin mechanics prize them as specialized building materials to lighten their rocket cars without sacrificing structural integrity.",h="Hollow Vulture Bones are lightweight, durable skeletal remains harvested from the scavengers of the...",sec={{t="Racing Materials on the Flats",b="Speed is everything out on the salt, and weight is the enemy of speed. While standard engineering leans heavily on iron and copper, the goblin pit crews at the Mirage Raceway turn to whatever the desert provides to gain an edge. Vulture bones are naturally hollow yet remarkably sturdy, providing the perfect strength-to-weight ratio for internal brackets, steering rigs, and minor structural supports. For chief tinkerers like Pozzik, harvesting bones from local scavengers is a practical and cheap shortcut to shaved seconds on the track.",sp=0}},faq={{q="Why do the goblins want vulture bones?",a="Goblin engineers like Pozzik use hollow vulture bones to shave excess weight off their rocket cars. Because bird bones are naturally light and surprisingly strong, they make ideal material for steering rigs and minor structural framing.",al={"why bones","goblin bones use","pozzik bone use"},it="why_wanted"},{q="Where do these bones come from?",a="They are harvested from Salt Flats Scavengers and Salt Flats Vultures circling the Shimmering Flats in Thousand Needles, particularly around the giant skeletal remains scattered across the salt desert.",al={"where to find hollow vulture bone","vulture bone location","how to get vulture bones"},it="origin"},{q="Who is Pozzik?",a="Pozzik is a goblin engineer and lead mechanic stationed at the Mirage Raceway. He continually tunes and modifies rocket cars to compete against the gnomish team led by Fizzle Brassbolts.",al={"who is pozzik","pozzik raceway","who takes the bones"}},{q="What is a Hollow Vulture Bone?",a="These are lightweight, sturdy bones scavenged from the carrion birds wheeling over the Shimmering Flats. Avian skeletons are naturally hollow to aid in flight, making them uniquely suited for mechanical engineering where shaving every extra pound matters. At the Mirage Raceway, goblin mechanics use them to craft resilient structural parts and steering components for their rocket cars.",al={"what is hollow vulture bone","hollow vulture bones"},it="identity",add=true}},ang={["profession:Engineering"]="While typical schematics rely on heavy iron and bronze, the use of hollow avian bone demonstrates the scrappy, weight-shaving pragmatism central to goblin racing innovation.",["class:Hunter"]="The vultures of the Shimmering Flats are hardy carrion feeders, making them natural targets for tracking across the blinding salt bed."},kw={"hollow vulture bone","load lightening","mirage raceway","pozzik","scavenger","shimmering flats","thousand needles"},rel={"quest:1176","npc:pozzik","subzone:mirage-raceway","subzone:shimmering-flats","zone:thousandneedles","topic:goblin"},src={"Hollow Vulture Bone","Load Lightening"}}
E["item:hypercapacitor-gizmo"] = {t="item",n="Hypercapacitor Gizmo",z="thousandneedles",s="The Hypercapacitor Gizmo is an eccentric piece of engineering recovered from the canyon floor of Thousand Needles. Once dangling from the neck of a caged beast in a ruined caravan, its true purpose remains a mystery even to the tinkerer who claims to own it.",h="The Hypercapacitor Gizmo is an eccentric piece of engineering recovered from the canyon floor of Thousand...",sec={{t="A Caravan's Strange Relic",b="When centaur marauders ambushed a goblin caravan traveling through Thousand Needles, they plundered nearly everything in sight. The sole survivor, Wizlo Bearingshiner, managed to crawl his way to safety at Whitereach Post, leaving behind his most prized invention: the Hypercapacitor Gizmo. Strangely, the gadget wound up secured around the neck of a ferocious, enraged panther locked inside a transport cage. The raiding centaur feared the beast enough to leave the cage entirely alone amidst the burning wreckage, unwittingly preserving Wizlo's odd machine.",sp=0},{t="Tinkering in the Dark",b="While Wizlo proudly boasts of the device as his finest creation, he admits upon its recovery that he has no real idea what it actually does. Like many goblin contraptions, the Hypercapacitor Gizmo is a tangled mass of ambition and volatile parts, destined to keep its creator occupied with endless tinkering rather than serving any practical, understood function.",sp=0}},faq={{q="What is the Hypercapacitor Gizmo?",a="It is an engineering device built by the goblin Wizlo Bearingshiner. Despite its grand name, even Wizlo does not actually know what function it performs, intending to spend his time studying it to figure out its purpose.",al={"what is gizmo","hypercapacitor","what does the gizmo do"},it="identity"},{q="How did the device end up around a panther's neck?",a="Wizlo's caravan was attacked and ransacked by centaur in northern Thousand Needles. During the chaos, the device ended up fastened around the neck of an enraged panther locked in a traveling cage, which kept the superstitious centaur from looting it.",al={"why panther has gizmo","how did panther get it"},it="history"},{q="Who wants the Hypercapacitor Gizmo back?",a="Wizlo Bearingshiner, the sole survivor of the raided caravan, seeks its return. He has taken refuge at Whitereach Post, a Tauren encampment in northwestern Thousand Needles.",al={"who needs gizmo","wizlo gizmo"},it="why_wanted"},{q="Why didn't the centaur steal it?",a="The centaur ransacked the entire caravan but were terrified of the ferocious panther inside the cage. They left the beast and its metal collar entirely untouched amidst the ruins.",al={"why didn't centaur take it","centaur and panther"}},{q="Where does the Hypercapacitor Gizmo come from, and who made it?",a="The device was in the possession of the goblin tinkerer Wizlo Bearingshiner, traveling with a caravan through Thousand Needles before centaur ambushed them. While Wizlo claims it as his prized gizmo, its precise inventor remains a mystery—even Wizlo admits he does not fully understand what the curious machine actually does.",al={"who made hypercapacitor gizmo","hypercapacitor gizmo origin","where did wizlo get hypercapacitor"},it="origin",add=true}},ang={["profession:Engineering"]="The gizmo represents classic goblin engineering: an intricate, dangerously named device built with great enthusiasm before anyone bothered to decide what it was supposed to do.",["faction:Horde"]="Travelers aiding Whitereach Post help clear out the aggressive centaur and retrieve lost oddities from ruined caravans across the canyon floor."},kw={"centaur","enraged panther","gizmo","hypercapacitor","thousand needles","whitereach post","wizlo bearingshiner"},rel={"quest:5151","npc:wizlo-bearingshiner","item:panther-cage-key","subzone:whitereach-post","zone:thousandneedles","topic:centaur","topic:horde"},src={"Hypercapacitor Gizmo","Hypercapacitor Gizmo (quest)"}}
E["item:kravel-s-crate"] = {t="item",n="Kravel's Crate",z="thousandneedles",s="Kravel's Crate is a heavy package dispatched by Kravel Koalbeard from the Mirage Raceway in the Shimmering Flats. Destined for the Nesingwary expedition in Stranglethorn Vale, it contains specialized hunting ammunition designed to bring down the jungle's deadliest game.",h="Kravel's Crate is a heavy package dispatched by Kravel Koalbeard from the Mirage Raceway in the Shimmering...",sec={{t="A Delivery to the Jungle",b="Handed out by the shrewd entrepreneur Kravel Koalbeard at the Mirage Raceway, Kravel's Crate represents an unfinished business transaction across continents. Ordered weeks prior by a wealthy dwarven patron, the shipment was delayed long enough for its buyer to depart Kalimdor entirely. Rather than lose out on the favor of a wealthy customer who already paid for forwarding, Kravel entrusts passing adventurers to haul the crate all the way to northern Stranglethorn Vale.",sp=0},{t="Special-Gauge Ammunition",b="Despite its nondescript appearance and the crust of salt dust it gathers in the Shimmering Flats, the crate carries lethal cargo: heavy, special-gauge ammunition tailored specifically for hunting rifles. When received at the expedition camp north of Grom'gol, the recipient notes that the potent rounds are prized by big-game hunters and vital for survival against the predators roaming the jungle canopy.",sp=0}},faq={{q="What is inside Kravel's Crate?",a="The crate is packed with special-gauge hunting ammunition. The heavy-caliber shot is specifically intended for big-game rifles used to take down dangerous beasts in the wild.",al={"what's in the crate","crate contents","what is in kravels crate"},it="item"},{q="Who sent Kravel's Crate?",a="It is sent by Kravel Koalbeard, a dwarven merchant operating amidst the racing and gambling at the Mirage Raceway in the Shimmering Flats of Thousand Needles.",al={"who gives the crate","who owns kravels crate"},it="origin"},{q="Where does this crate need to go?",a="The crate must be hauled to the Nesingwary hunting expedition camp in northern Stranglethorn Vale, situated along the river north of Grom'gol Base Camp.",al={"where to deliver crate","crate destination","who gets kravels crate"},it="target"},{q="Why was the delivery delayed?",a="The parcel took weeks to arrive out in the Thousand Needles salt flats, during which time the customer had already packed up and departed for the jungles of Stranglethorn Vale.",al={"why did kravel take so long","why delayed"},it="motive"},{q="What is Kravel's Crate?",a="It is a heavy delivery package held by Kravel Koalbeard at the Mirage Raceway in the Shimmering Flats. Packed securely for long-distance transport across Kalimdor and the Great Sea, the crate holds specialized hunting supplies intended for an expedition out in the wilds of Stranglethorn Vale.",al={"what is kravel's crate","kravels crate info","kravel crate item"},it="identity",add=true},{q="Why is Kravel's Crate wanted?",a="The crate contains special-gauge ammunition ordered specifically for big game hunting. The Nesingwary hunting expedition in Stranglethorn Vale relies on heavy, reliable munitions to bring down the jungle's fiercest beasts, making this delayed shipment an essential resupply for their camp.",al={"why does nesingwary want the crate","why is kravels crate important","kravel crate purpose"},it="why_wanted",add=true}},ang={["class:Hunter"]="The crate contains specialized heavy ammunition designed specifically for high-end dwarven hunting rifles, tailored for big-game expeditions.",["race:Dwarf"]="The delivery is an affair entirely between dwarves, connecting Kravel Koalbeard's business dealings in the salt flats with the renowned Nesingwary hunting party in the Eastern Kingdoms."},kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale"},rel={"npc:kravel-koalbeard","quest:5762","subzone:shimmering-flats","subzone:mirage-raceway","zone:stranglethorn","zone:thousandneedles","topic:hunter"},src={"Kravel's Crate","Hemet Nesingwary (quest)","Hemet Nesingwary Jr. (quest)"}}
E["item:legacy-of-the-aspects"] = {t="item",n="Legacy of the Aspects",z="thousandneedles",s="Legacy of the Aspects is an ancient tome hidden deep within the Dor'Danil Barrow Den in southern Ashenvale. Retrieved during a Horde trial of the intellect, the volume contains essential lore concerning the Great Aspects that shaped ancient Azeroth.",h="Legacy of the Aspects is an ancient tome hidden deep within the Dor'Danil Barrow Den in southern Ashenvale.",sec={{t="A Test of the Mind",b="While earlier trials set forth by tauren elders test physical endurance and resolve, the pursuit of Legacy of the Aspects is designed to challenge the mind. Tasked by Braug Dimspirit at the entrance to the Talondeep Path in the Stonetalon Mountains, an aspirant must delve into the haunted barrow dens of Dor'Danil. Guarded by the restless spirits of fallen druids and the vicious creatures that slew them, the ancient text rests upon a stone pedestal. Claiming the volume is only the first step; the seeker must commit its contents to memory before relinquishing the book, as they are tested on its historical lessons.",sp=0}},faq={{q="Where is the book located?",a="The book rests on a stone pedestal within the lower chambers of the Dor'Danil Barrow Den, located in southern Ashenvale, south of Splintertree Post.",al={"find legacy of the aspects","book location","where is book"},it="place",gp=true},{q="Why does Braug Dimspirit want this book?",a="Braug Dimspirit uses the tome to conduct the Test of Lore. Unlike physical challenges, this trial is meant to determine whether an adventurer possesses the intelligence and attentiveness to study and recall vital historical knowledge.",al={"why braug wants book","test of lore purpose"},it="why_wanted"},{q="What happens if you fail to study the text before speaking to Braug?",a="Braug questions seekers on the lore within the pages immediately after collecting the volume. Answering incorrectly results in swift magical banishment, teleporting the unprepared petitioner far away to Camp Taurajo in the Barrens.",al={"wrong answer consequence","failing the test"},gp=true},{q="What is Legacy of the Aspects?",a="The Legacy of the Aspects is an ancient and valuable tome resting deep within the Dor'Danil Barrow Den in southern Ashenvale. Guarded by the restless spirits of fallen druids and the vile creatures that slew them, the book contains historical lore concerning the Dragon Aspects, serving as an exacting test of wisdom and memory for those who dare retrieve it.",al={"what is legacy of the aspects","legacy of the aspects book","what is this book"},it="identity",add=true}},ang={["faction:Horde"]="The tome is central to a traditional rite of passage that tests whether Horde adventurers possess the wisdom and knowledge to match their physical might.",["class:Druid"]="The text resides deep in Dor'Danil Barrow Den, surrounded by the tragic, tormented spirits of fallen night elf druids."},kw={"ashenvale","barrow den","braug dimspirit","dor'danil","legacy of the aspects","talondeep path","test of lore"},rel={"quest:1152","quest:1149","subzone:dor-danil-barrow-den","subzone:talondeep-path","zone:stonetalon","zone:ashenvale","subzone:camp-taurajo","topic:horde"},src={"Legacy of the Aspects","Test of Lore (2)"}}
E["item:lonebrow-s-journal"] = {t="item",n="Lonebrow's Journal",z="thousandneedles",s="Lonebrow's Journal is a weathered diary found clutched in the skeletal remains of the dwarven explorer Henrig Lonebrow at the base of the Great Lift. Its pages detail the final grim journey of Lonebrow through Thousand Needles and point toward dangers lurking within Razorfen Kraul.",h="Lonebrow's Journal is a weathered diary found clutched in the skeletal remains of the dwarven explorer Henrig...",sec={{t="A Dying Wish at the Great Lift",b="Henrig Lonebrow met an unfortunate end near the base of the Great Lift connecting the Barrens to Thousand Needles. Lying abandoned on a rocky ledge, his skeletal remains still grip this weathered journal. The diary serves as a testament to his final travels and directs whoever discovers it to bring word to the night elf druid Falfindel Waywarder at Thalanaar, the border outpost leading into Feralas. Lonebrow's notes shed critical light on the quillboar menace brewing in the southern barrens.",sp=0},{t="Ties to the Razorfen",b="When delivered to Falfindel Waywarder, Lonebrow's records confirm growing Alliance concerns regarding the quillboar of Razorfen Kraul. The journal's contents lead directly to a call for heroes to strike at the heart of the thorny warren and defeat Charlga Razorflank, the Crone of the Kraul who orchestrates the quillboar threat.",sp=1}},faq={{q="Who was Henrig Lonebrow?",a="Henrig Lonebrow was a dwarven traveler who perished at the foot of the Great Lift in Thousand Needles. He died with his journal clutched in hand, intending for its contents to reach the night elves stationed at Thalanaar.",al={"henrig lonebrow","who is lonebrow","dead dwarf lift"},it="people"},{q="Where is the journal found?",a="The journal rests beside Henrig Lonebrow's skeleton just off the ramp at the base of the Great Lift, on a low rocky ledge in northern Thousand Needles.",al={"where is lonebrow journal","find lonebrow journal","skeleton at great lift"},it="place",gp=true},{q="Who should receive Lonebrow's Journal?",a="The journal should be taken west across Thousand Needles to Falfindel Waywarder, a night elf druid stationed at Thalanaar along the border of Feralas.",al={"who do i bring journal to","falfindel waywarder","where to turn in journal"},it="next_step",gp=true},{q="What does the journal lead to?",a="Reading the journal and reporting to Falfindel Waywarder reveals intelligence on the quillboar, leading to a mission into Razorfen Kraul to defeat the crone Charlga Razorflank.",al={"crone of the kraul quest","lonebrow journal follow up"},sp=1},{q="What is Lonebrow's Journal?",a="Lonebrow's Journal is a weathered personal log found clutched in the skeletal hands of the dwarf Henrig Lonebrow. Discovered at the foot of the Great Lift in Thousand Needles, it documents his travels and final wishes before he met his end in the canyon.",al={"lonebrow journal what is","what is this book","henrig lonebrows journal"},it="identity",add=true,nx={6}},{q="Where does Lonebrow's Journal come from, and who made it?",a="The journal was penned by Henrig Lonebrow, a dwarven traveler who journeyed through the treacherous canyons of Thousand Needles. He carried it with him until his death near the base of the Great Lift, where his remains and the volume were ultimately discovered.",al={"who wrote lonebrows journal","lonebrow journal author","where did the journal come from"},it="origin",add=true},{q="Why does anyone want Lonebrow's Journal?",a="Delivering the journal fulfills the fallen dwarf's final wishes. Falfindel Waywarder, a night elf druid stationed at Thalanaar on the border of Feralas, seeks to read its contents to understand Henrig's fate and uncover the dangers stirring in Razorfen Kraul.",al={"why deliver lonebrow journal","who needs lonebrows journal","why want lonebrows journal"},it="why_wanted",add=true}},ang={["race:Dwarf"]="Discovering a fallen kin in such remote, hostile lands is a somber reminder of the perils dwarven explorers face while scouting far beyond Khaz Modan.",["faction:Alliance"]="Henrig Lonebrow's final writings forge a crucial link between Alliance scouts and the druids guarding the border to Feralas, rallying aid against the quillboar menace."},kw={"crone of the kraul","falfindel waywarder","great lift","henrig lonebrow","razorfen kraul","thalanaar","thousand needles"},rel={"quest:1100","quest:1101","subzone:great-lift","subzone:thalanaar","npc:falfindel-waywarder","zone:thousandneedles","zone:razorfenkraul","topic:dwarf"},src={"Lonebrow's Journal","Lonebrow's Journal (quest)"}}
E["item:panther-cage-key"] = {t="item",n="Panther Cage Key",z="thousandneedles",s="The Panther Cage Key is a small metal key held by Wizlo Bearingshiner at Whitereach Post. It unlocks a reinforced cage holding an enraged, captive predator within the wreckage of an ambushed caravan in Thousand Needles.",h="The Panther Cage Key is a small metal key held by Wizlo Bearingshiner at Whitereach Post.",sec={{t="A Precarious Lock",b="When a traveling caravan was attacked and ransacked by centaur raiders north of Whitereach Post, the goblin tinker Wizlo Bearingshiner barely escaped with his life. Amid the ruins of wagons and plundered cargo, the marauders left one thing entirely untouched: a sturdy cage housing a ferocious, rare panther. Around the predator's neck hung Wizlo's prized invention, a hypercapacitor gizmo. Unwilling to approach the snarling beast, the centaur gave the cage a wide berth, leaving Wizlo's key as the only way to open the door and retrieve the device.",sp=0}},faq={{q="Who provides the Panther Cage Key?",a="The key is handed to adventurers by Wizlo Bearingshiner, a goblin tinker resting at Whitereach Post in northwestern Thousand Needles.",al={"who gives panther key","where to get panther cage key","panther cage key source"},it="origin"},{q="What does the key unlock?",a="It unlocks an iron cage found among the broken wagons of a ruined caravan just north of Whitereach Post, which holds an enraged, dangerous panther.",al={"what does panther key open","panther cage location","where is the cage"},it="identity"},{q="Why didn't the centaur loot the cage?",a="The centaur ransacked the rest of the caravan, but the captive panther within was so ferocious and threatening that even the raiders refused to tamper with its cage.",al={"why did centaur leave panther","centaur afraid of panther"}},{q="What is inside the cage besides the beast?",a="Wizlo's prized hypercapacitor gizmo is fastened around the panther's neck, forcing anyone hoping to recover the invention to unlock the cage and confront the predator directly.",al={"why open the cage","what is on the panther"}},{q="Why does Wizlo Bearingshiner want the Panther Cage Key back?",a="Wizlo Bearingshiner entrusts you with the key solely so you can open the cage at his wrecked caravan to slay the fierce panther within. The beast wears his prized hypercapacitor gizmo around its neck. He wants the key returned alongside his invention once the deed is done, ensuring the caravan's remnants and his dangerous property are fully accounted for.",al={"why panther cage key","why does wizlo need the key","why want panther cage key"},it="why_wanted",add=true}},ang={["profession:Engineering"]="The key unlocks the cage holding a tinker's volatile prototype, proving that eccentric inventors will stash their most delicate mechanisms in the most hazardous places imaginable.",["faction:Horde"]="Assisting Wizlo helps secure the roads of Thousand Needles around Whitereach Post from the volatile aftermath of centaur raids."},kw={"centaur","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner"},rel={"npc:wizlo-bearingshiner","quest:5151","subzone:whitereach-post","zone:thousandneedles","topic:centaur","topic:horde"},src={"Panther Cage Key","Hypercapacitor Gizmo (quest)"}}
E["item:rocket-car-parts"] = {t="item",n="Rocket Car Parts",z="thousandneedles",s="Rocket Car Parts are the scattered, twisted metal remains of high-speed collisions across the Shimmering Flats in Thousand Needles. Constantly generated by reckless gnome and goblin racers pushing experimental speeders past their limits, these salvaged scraps are harvested by opportunists looking to turn racetrack accidents into quick coin.",h="Rocket Car Parts are the scattered, twisted metal remains of high-speed collisions across the Shimmering...",sec={{t="Speed, Wrecks, and Shrewd Commerce",b="The Mirage Raceway in the Shimmering Flats is the staging ground for an unending, combustible rivalry between goblin and gnome engineering. In their pursuit of unmatched land speed, racers regularly suffer catastrophic breakdowns, explosive misfires, and high-velocity crashes that scatter metal across the salt flats. These discarded remnants—ranging from bent cylinders and burnt gears to crushed sheet metal—do not stay abandoned for long. Scavengers and merchants, most notably the opportunistic dwarf Kravel Koalbeard, hire passing adventurers to comb the blinding white expanse and collect the debris. Because both racing teams are perpetually desperate for spare machinery to patch together their next prototype, scavenged wreckage can easily be resold directly back to the very teams that wrecked it.",sp=0}},faq={{q="Where do all these rocket car parts come from?",a="They are the aftermath of constant crashes, explosions, and mechanical failures at the Mirage Raceway. Gnome and goblin pilots routinely push volatile, experimental rocket-powered vehicles to destruction across the vast salt flats of Thousand Needles.",al={"why are there parts on the salt flats","rocket car scrap origin","where do the parts come from"},it="origin"},{q="Who buys these salvaged scraps?",a="Merchants like the dwarf Kravel Koalbeard collect the wreckage from wanderers and turn around to sell the salvaged gears, plating, and gizmos back to the gnomes and goblins, who always need spare materials to repair and enhance their racing cars.",al={"who wants rocket car parts","kravel koalbeard rocket parts","who buys the wreckage"},it="why_wanted"},{q="Are the parts dangerous to scavenge?",a="The debris itself is inert wreckage, though occasionally bearing grim signs of violent crashes like severed appendages pinched in the metal. The primary danger comes from the salt flats' hostile wildlife, including basilisks, scorched scorpids, and predatory salt vultures that prowl around the debris fields.",al={"is it safe to pick up parts","threats while gathering parts"},it="danger"},{q="Do the gnomes and goblins care that the parts are from crashed cars?",a="Not in the slightest. Neither gnome nor goblin competitors are squeamish about recycled materials. Their sole priority is securing workable contraptions, gears, and metal plating to assemble fast enough to outrun each other on the track.",al={"do racers care about wreckage","why do goblins reuse junk"}},{q="What are Rocket Car Parts?",a="They are the scattered debris of high-speed racing disasters across the Shimmering Flats. Made up of loose gears, cylinders, twisted metal plates, and salvaged gizmos, these scraps were once bolted to the roaring experimental contraptions built by goblin and gnome speedsters competing at the Mirage Raceway.",al={"what is rocket car parts","rocket car parts lore","what are these parts"},it="identity",add=true}},ang={["profession:Engineering"]="The litter of burnt gears and mangled exhaust assemblies across the salt flats serves as a testament to the chaotic extremes of gnome and goblin engineering philosophy.",["race:Dwarf"]="While gnomes and goblins care only for the race itself, enterprising dwarves like Kravel Koalbeard prove that the real profit lies in scavenging the wreckage left in their wake."},kw={"engineering","gnome","goblin","kravel koalbeard","mirage raceway","rocket car parts","salvage","shimmering flats","thousand needles"},rel={"quest:1110","npc:kravel-koalbeard","subzone:mirage-raceway","subzone:shimmering-flats","zone:thousandneedles","quest:1105","quest:1104","quest:1176"},src={"Rocket Car Parts","Rocket Car Parts (quest)"}}
E["item:salty-scorpid-venom"] = {t="item",n="Salty Scorpid Venom",z="thousandneedles",s="Salty Scorpid Venom is a caustic fluid harvested from the scorpids stalking the Shimmering Flats in Thousand Needles. Packed with natural salts from the desert floor, it is prized by gnomish rocket racers attempting to engineer volatile, ultra-hot fuel.",h="Salty Scorpid Venom is a caustic fluid harvested from the scorpids stalking the Shimmering Flats in Thousand...",sec={{t="A Volatile Combustion Agent",b="The scorpids crawling the arid expanse of the Shimmering Flats have adapted to an intensely mineral-rich environment. Over generations, the venom of beasts like the Scorpid Reavers and Scorpid Terrors has absorbed enormous quantities of local salt. Rather than brewing antidotes or standard poisons, gnomish tinkers like Fizzle Brassbolts prize this caustic compound as a prospective additive for high-combustion engine fuel.",sp=0},{t="Fueling the Raceway Rivalry",b="Out at the Mirage Raceway, the engineering competition between gnomes and goblins drives inventors to test increasingly dangerous materials in their rocket cars. Fizzle Brassbolts believes boiling down the salted venom, treating it with specialized catalysts, and mixing it into propellant tanks will deliver the blazing heat necessary to outrun goblin racers on the salt pans.",sp=0}},faq={{q="What creatures produce Salty Scorpid Venom?",a="It is gathered from the dangerous scorpids that roam the salt flats in Thousand Needles, particularly Scorpid Reavers and Scorpid Terrors.",al={"who drops salty scorpid venom","where to get scorpid venom","scorpid venom source"},it="origin"},{q="Why is the venom so salty?",a="The scorpids live entirely upon the mineral-crusted ground of the Shimmering Flats. Their physiology absorbs the dense salts of the dried lakebed, infusing their venom glands with a distinct saline concentration.",al={"why is it salty","salt flat venom explanation","scorpid salt lore"}},{q="Who wants this venom and why?",a="Fizzle Brassbolts, a gnome engineer stationed at the Mirage Raceway, seeks the venom to formulate an experimental fuel mixture that burns hot enough to propel his rocket car to victory.",al={"who needs scorpid venom","why does fizzle want venom","fizzle brassbolts quest item"},it="why_wanted"},{q="What is Salty Scorpid Venom?",a="It is a potent, mineral-heavy fluid harvested from the scorpids stalking the Shimmering Flats. The harsh, dried-up salt basin has caused the local scorpid terrors and reavers to develop an unusually salt-saturated venom. While deadly as a natural toxin, its reactive chemical properties make it far more interesting to tinkers as an volatile raw reagent than a simple poison.",al={"what is salty scorpid venom","salty scorpid venom","scorpid venom flat"},it="identity",add=true}},ang={["race:Gnome"]="Only gnomish ingenuity would consider taking lethal desert venom, combining it with nega-catalysts, and injecting it into a rocket engine just to shave a few seconds off a lap time.",["profession:Engineering"]="Inventors tinkering in the Shimmering Flats constantly look beyond conventional petroleum and coal, testing organic toxins as volatile combustion accelerants."},kw={"fizzle brassbolts","mirage raceway","salty scorpid venom","scorpid reaver","scorpid terror","scorpid venom","shimmering flats","thousand needles"},rel={"quest:1104","npc:fizzle-brassbolts","subzone:shimmering-flats","subzone:mirage-raceway","zone:thousandneedles","topic:gnome"},src={"Salty Scorpid Venom","Salt Flat Venom"}}
E["item:urgent-message"] = {t="item",n="Urgent Message",z="thousandneedles",s="The Urgent Message is a sealed dispatch penned by Brave Moonhorn warning Freewind Post of escalating centaur violence across Thousand Needles. Carried by travelers descending into the canyon, the letter alerts the tauren garrison that their supply lines and scouting parties are under immediate threat.",h="The Urgent Message is a sealed dispatch penned by Brave Moonhorn warning Freewind Post of escalating centaur...",sec={{t="A Warning from the Heights",b="Penned by Brave Moonhorn near the great lift that descends from the Barrens into Thousand Needles, the Urgent Message represents the first line of defense for travelers crossing the border. Moonhorn monitors the jagged canyons below, where aggressive centaur tribes have renewed their relentless raids against Horde travel. Addressed to Cliffwatcher Longhorn atop Freewind Post, the missive sounds the alarm about emboldened attackers striking dangerously close to crucial roadways, urging the local garrison to brace for sustained conflict and guard against secondary threats like the unpredictable Grimtotem clan.",sp=0},{t="Bloodshed on the Canyon Floor",b="When delivered to Cliffwatcher Longhorn atop the towering mesa of Freewind Post, the letter confirms the settlement's darkest fears. The centaur assault has surpassed mere border skirmishing; raiders have ambushed a vital supply caravan traversing the canyon floor, slaughtering the entire convoy. The dispatch forces the tauren leadership to shift immediately from defensive vigilance to aggressive retaliation, triggering organized counter-strikes to pacify the marauding tribes before Freewind Post is entirely cut off from the rest of Kalimdor.",sp=1}},faq={{q="What is written in the Urgent Message?",a="The message details a sharp surge in centaur raids across Thousand Needles, warning that traveling parties and roadways are in immediate peril and urging Freewind Post to prepare for war.",al={"what does the letter say","urgent message contents","what is the message about"},it="item"},{q="Who wrote this message and who receives it?",a="It was drafted by Brave Moonhorn, stationed at the Great Lift from the Barrens, and addressed directly to Cliffwatcher Longhorn, the commander of Freewind Post.",al={"who wrote urgent message","sender of urgent message","who gets the urgent message"},it="origin"},{q="Why are the centaur attacking supply caravans?",a="The centaur tribes have long contested the arid lands of central Kalimdor against the tauren. They raid caravans in the canyon floor to plunder vital provisions and deny the Horde safe passage through Thousand Needles.",al={"why centaur attacks","centaur motive thousand needles","why do centaurs raid"},it="motive"},{q="What warning does the scout give regarding the Grimtotem?",a="Brave Moonhorn cautions any courier carrying the dispatch to steer clear of the nearby Grimtotem clan, noting that their warriors have been acting increasingly aloof and suspicious toward the rest of the tauren.",al={"grimtotem warning","why avoid grimtotem","grimtotem acting strange"},it="threat"},{q="What is the Urgent Message?",a="The Urgent Message is a sealed written dispatch penned by Brave Moonhorn near the border of Thousand Needles. It reports an alarming surge in centaur aggression across the canyon floor, alerting tauren authorities to the growing danger threatening travelers and supply lines in the region.",al={"what is urgent message","urgent message item","urgent dispatch"},it="identity",add=true},{q="Why is the Urgent Message needed at Freewind Post?",a="Cliffwatcher Longhorn oversees the defense of Freewind Post and requires immediate intelligence on enemy movements. The dispatch warns him that centaur marauders have escalated their raids, allowing him to take decisive action before more supply caravans and patrols are ambushed and slaughtered.",al={"why deliver urgent message","who needs urgent message","why cliffwatcher longhorn message"},it="why_wanted",add=true}},ang={["faction:Horde"]="The message highlights the tenuous nature of Horde supply lines across southern Kalimdor, where isolated outposts rely on runners and braves to survive hostile terrain.",["race:Tauren"]="For the tauren, the letter is a painful reminder of their ancient blood feud with the centaur, as well as the growing unease concerning their Grimtotem kin."},kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","great lift","grimtotem","thousand needles","urgent message"},rel={"quest:4542","npc:brave-moonhorn","npc:cliffwatcher-longhorn","subzone:freewind-post","quest:4841","quest:5064","topic:centaur","zone:thousandneedles"},src={"Urgent Message","Message to Freewind Post"}}
E["npc:brave-moonhorn"] = {t="npc",n="Brave Moonhorn",z="thousandneedles",s="Brave Moonhorn is a tauren scout stationed at the top of the Great Lift on the southern border of the Barrens. From this precipice, he keeps watch over the entry to Thousand Needles and alerts travelers to the local dangers ahead.",h="Brave Moonhorn is a tauren scout stationed at the top of the Great Lift on the southern border of the Barrens.",sec={{t="Sentinel of the Lift",b="Perched above the sheer drops of Thousand Needles, Brave Moonhorn stands guard where the northern plains meet the canyonlands. His primary role is keeping watchful eyes on regional threats moving through the canyon floor below, particularly the hostile centaur clans. Anyone looking to descend into the needles often crosses paths with him first, receiving crucial warnings before they step onto the massive platforms of the Great Lift.",sp=0},{t="Uneasy Shadows",b="Beyond the constant threat of roving centaur, Moonhorn harbors deep misgivings about his fellow tauren from the Grimtotem tribe. He cautions traveling Horde allies to keep their distance from them, noting their increasingly erratic and suspicious behavior around Thousand Needles. To ensure the defense of the region, he dispatches couriers to Freewind Post to deliver warnings to Cliffwatcher Longhorn.",sp=0}},faq={{q="Who is Brave Moonhorn?",a="Brave Moonhorn is a tauren warrior and scout tasked with watching the approach to the Great Lift connecting the Barrens to Thousand Needles. He monitors enemy activity and warns passing travelers of nearby hazards.",al={"brave moonhorn role","who is moonhorn","lift tauren guard"},it="identity"},{q="Why does Moonhorn warn against the Grimtotem?",a="Moonhorn has noticed the Grimtotem clan acting strange and unpredictable in the surrounding canyon. While nominally part of the tauren community, their aggressive insularity makes them untrustworthy to guards keeping order along the trail.",al={"grimtotem warning","why avoid grimtotem","moonhorn grimtotem"}},{q="What message does he want delivered to Freewind Post?",a="He carries urgent warnings regarding escalating centaur activity in Thousand Needles and asks dependable Horde runners to relay this intelligence to Cliffwatcher Longhorn at Freewind Post.",al={"freewind post message","what is moonhorn's message","message to freewind post lore"},it="wants"},{q="Where is Brave Moonhorn located?",a="He stands near the edge of the plateau at the top of the Great Lift, right along the boundary separating the Barrens from Thousand Needles.",al={"where is moonhorn","brave moonhorn location","great lift guard"},it="place",gp=true},{q="Whose side is Brave Moonhorn on?",a="Brave Moonhorn serves Thunder Bluff and the Horde. Stationed atop the Great Lift between the Barrens and Thousand Needles, he keeps watch over the border and directs traveling Horde adventurers safely into the canyon below.",al={"is brave moonhorn horde","brave moonhorn faction","who does moonhorn serve"},it="side",add=true},{q="Why is Brave Moonhorn stationed at the Great Lift?",a="Moonhorn is posted at the precipice of Thousand Needles to guard the descent and monitor nearby dangers. From this vantage, he keeps an eye on centaur aggression and the uneasy movements of the Grimtotem clan, making sure travelers descending into the canyon are properly warned.",al={"why is moonhorn here","what is moonhorn doing at the lift","why is brave moonhorn at the great lift"},it="why_here",add=true},{q="Who is Brave Moonhorn tied to?",a="Moonhorn answers to the tauren leadership of Thunder Bluff and works closely with Cliffwatcher Longhorn at Freewind Post. When danger stirs along the canyon routes, Longhorn is the commander he relies upon to receive his scouting reports.",al={"moonhorn allies","who does moonhorn report to","brave moonhorn connections"},it="ties",add=true}},ang={["faction:Horde"]="Moonhorn serves as an early sentry for the Horde, directing new arrivals in the canyon toward safety and the fortified heights of Freewind Post.",["race:Tauren"]="Moonhorn's deep wariness of the Grimtotem reflects the simmering friction and distrust between traditional tribes loyal to Cairne Bloodhoof and the secretive Grimtotem clan."},kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","great lift","grimtotem","thousand needles"},rel={"quest:4542","subzone:great-lift","subzone:freewind-post","npc:cliffwatcher-longhorn","zone:thousandneedles","topic:grimtotem-tribe","topic:centaur","topic:tauren"},src={"Brave Moonhorn"}}
E["npc:cliffwatcher-longhorn"] = {t="npc",n="Cliffwatcher Longhorn",z="thousandneedles",s="Cliffwatcher Longhorn is the stoic tauren leader stationed high atop Freewind Post in Thousand Needles. Tasked with safeguarding the isolated Horde outpost, he coordinates defenses against encroaching Galak centaur and monitors the suspicious machinations of the Grimtotem tribe.",h="Cliffwatcher Longhorn is the stoic tauren leader stationed high atop Freewind Post in Thousand Needles.",sec={{t="Guardian of the Mesas",b="Perched upon the soaring rock spires of Thousand Needles, Freewind Post relies on sharp eyes and steady leadership to survive. Cliffwatcher Longhorn oversees the day-to-day security of this precarious settlement. With hostile forces gathering on the canyon floor below and along neighboring ridges, Longhorn acts as the settlement's primary coordinator for scouting reports and defensive military efforts.",sp=0},{t="Centaur Hostility and Grimtotem Intrigue",b="Longhorn contends with threats on multiple fronts. Down in the canyon, the aggressive Galak centaur relentlessly probe the perimeter, prompting him to dispatch adventurers to push them back and curb their numbers. Even more troubling to him, however, are the Grimtotem tauren. Deeply distrustful of their secretive camp near the post, Longhorn arranges reconnaissance to seize their hidden notes, uncovering troubling evidence of internal treachery, including the violent crimes of Arnak Grimtotem.",sp=1}},faq={{q="Who is Cliffwatcher Longhorn?",a="Cliffwatcher Longhorn is the tauren authority figure in command of Freewind Post, the Horde's towering outpost in Thousand Needles. He organizes scouts, defense patrols, and responses to local threats.",al={"cliffwatcher longhorn info","who is longhorn","freewind post leader"},it="identity"},{q="Where can I find Cliffwatcher Longhorn?",a="He is located atop the main mesa of Freewind Post in Thousand Needles, accessible by taking the lift up from the canyon floor and crossing the wooden bridges.",al={"cliffwatcher longhorn location","where is longhorn"},gp=true},{q="Why is Longhorn concerned about the centaur?",a="Reports brought in by scouts like Brave Moonhorn show an alarming surge in Galak centaur hostility. Longhorn orders proactive strikes to pacify the clan and prevent them from overwhelming the outpost's approaches.",al={"why kill centaur","pacify the centaur lore","centaur threat thousand needles"},it="conflict"},{q="What is his interest in the Grimtotem tribe?",a="While technically living among the Horde, the Grimtotem clan behaves with open secrecy and malice. Longhorn suspects foul play and commissions adventurers to steal their hidden notes to discover what they are plotting.",al={"longhorn grimtotem","grimtotem spying reason"},it="threat"},{q="Who is Arnak Grimtotem and why does Longhorn want him?",a="Arnak Grimtotem carried out a violent attack against the post's inhabitants. Longhorn issues a bounty on his head to ensure Arnak faces justice for his treachery.",al={"wanted arnak grimtotem","arnak bounty lore"},it="target"},{q="Does Cliffwatcher Longhorn have any family?",a="Yes, his brother Nataka Longhorn is stationed far to the west at Ghost Walker Post in Desolace. Preoccupied with duty, Cliffwatcher rarely finds the opportunity to write him.",al={"longhorn brother","nataka longhorn brother"},it="ties"},{q="Whose side is Cliffwatcher Longhorn on?",a="Cliffwatcher Longhorn stands firmly with the Horde and the tauren tribes answering to Thunder Bluff. Stationed atop Freewind Post, he coordinates defense for the settlement, relying on Horde champions to safeguard the canyon roadways below from aggressive centaur clans and the subversive Grimtotem tribe.",al={"cliffwatcher longhorn faction","longhorn horde alliance","who does longhorn serve"},it="side",add=true},{q="What does Cliffwatcher Longhorn want?",a="Longhorn wants to maintain security and order throughout Thousand Needles. He seeks to retaliate against hostile Galak centaur bands harassing travelers, uncover whatever secretive plots the local Grimtotem are hatching, and bring rogue threats like Arnak Grimtotem to swift justice.",al={"what does longhorn want","longhorn goal","cliffwatcher longhorn motives"},it="wants",add=true},{q="Why is Cliffwatcher Longhorn here?",a="Longhorn is stationed at Freewind Post as one of its primary overseers and defenders. From this soaring mesa, he monitors reports across the canyon floor, directs Horde scouts, and organizes responses to the dangerous centaur tribes and deceitful Grimtotem who surround the outpost.",al={"why is longhorn in freewind post","why is cliffwatcher longhorn in thousand needles","longhorn freewind post role"},it="why_here",add=true}},ang={["race:Tauren"]="For tauren travelers, Longhorn represents the frontier spirit of the Shu'halo, keeping watch over contested sacred mesas while navigating the bitter, unresolved friction with the Grimtotem tribe.",["faction:Horde"]="Freewind Post is the vital link securing supply lines across southern Kalimdor, and Longhorn ensures the Horde retains its precarious foothold amidst hostile centaur territory."},kw={"arnak grimtotem","brave moonhorn","cliffwatcher longhorn","freewind post","galak","grimtotem","nataka longhorn","thousand needles"},rel={"subzone:freewind-post","zone:thousandneedles","npc:brave-moonhorn","quest:4542","quest:4841","quest:5064","quest:5147","zone:desolace"},src={"Cliffwatcher Longhorn"}}
E["npc:dorn-plainstalker"] = {t="npc",n="Dorn Plainstalker",z="thousandneedles",s="Dorn Plainstalker is a solitary tauren elder residing in the Weathered Nook overlooking the canyons of Thousand Needles. He serves as an overseer of traditional rite of passage trials, challenging Horde adventurers to prove their character and fortitude. Through trials of faith, endurance, strength, and lore, he tests whether travelers are worthy servants of the Earth Mother and their people.",h="Dorn Plainstalker is a solitary tauren elder residing in the Weathered Nook overlooking the canyons of...",sec={{t="Hermit of the High Cliffs",b="Secluded in a shallow cave high atop the canyon ridges of the Weathered Nook, Dorn Plainstalker lives apart from the bustle of Freewind Post. Reaching his mountain redoubt requires winding along the sheer northern cliffs overlooking the towering mesas below. From this quiet vantage point, Dorn maintains ancient customs and judges those who seek guidance in the harsh southern barrens.",sp=0},{t="The Four Trials",b="Dorn Plainstalker guides pilgrims through a demanding series of tests meant to measure the core virtues of a tauren champion: faith, endurance, strength, and lore. Rather than mere exercises in brute force, these trials force aspirants to confront fear, leap blindly into the unknown, outlast cunning wilderness predators, and ponder the sacred history of Kalimdor before claiming their final passage.",sp=0}},faq={{q="Who is Dorn Plainstalker?",a="Dorn Plainstalker is a tauren hermit and elder who dwells in the Weathered Nook, a secluded cliffside shelter high above Thousand Needles. He administers traditional trials of passage to aspiring Horde champions.",al={"who is dorn","dorn lore","dorn plainstalker"},it="identity"},{q="Where can I find Dorn Plainstalker?",a="He is located in a cave at the Weathered Nook. From Freewind Post, head north to the high cliff walls bordering the canyon, then follow the ridge east until you discover a ramp ascending into his mountain sanctuary.",al={"where is dorn","how to reach dorn plainstalker","weathered nook location"},it="place",gp=true},{q="What are the trials Dorn administers?",a="Dorn oversees four sacred tests: the Test of Faith, Test of Endurance, Test of Strength, and Test of Lore. Completing them proves a traveler's courage, physical resolve, combat skill, and respect for tradition.",al={"dorn plainstalker quests","test of faith","trials of passage thousand needles"},it="purpose"},{q="What is the Test of Faith?",a="The Test of Faith requires the pilgrim to step off a dizzying cliff plank into the chasm below, demonstrating absolute trust and overcoming primal fear.",al={"leap of faith thousand needles","test of faith dorn"}},{q="Why does Dorn live alone in a cave?",a="Dorn adheres to ascetic tauren spiritual traditions. By dwelling alone in the heights of the Weathered Nook, away from the daily trade and defense of Freewind Post, he maintains an untroubled place of contemplation and trial for seekers.",al={"why is dorn isolated","dorn plainstalker background"},it="why_here"},{q="Is Dorn affiliated with Freewind Post?",a="While he lives outside Freewind Post itself, Dorn is a loyal member of the Horde and the tauren tribes, assisting brave travelers who wander through the windswept canyons.",al={"freewind post elder","is dorn horde"},it="ties"},{q="Whose side is Dorn Plainstalker on?",a="Dorn Plainstalker is loyal to the Horde and his fellow tauren. He welcomes travelers of the Horde into his sanctuary at the Weathered Nook to prove their mettle, guiding them through traditional rites to ensure they possess the strength, faith, and wisdom required to serve the tribes and the broader Horde.",al={"is dorn horde","dorn plainstalker faction","who does dorn serve"},it="side",add=true},{q="What does Dorn Plainstalker want?",a="Dorn Plainstalker wants to test the character, endurance, and spirit of champions who journey through Thousand Needles. By overseeing the trials of faith, endurance, strength, and lore, he seeks to prepare worthy adventurers for the harsh challenges of the world and ensure they honor the traditions of the earth.",al={"dorn goals","what does dorn want","dorn plainstalker purpose"},it="wants",add=true}},ang={["race:Tauren"]="For tauren wandering through Thousand Needles, Dorn represents the continuation of nomadic ancestral traditions and spiritual rites that test one's balance with the Earth Mother.",["faction:Horde"]="Dorn welcomes all Horde champions willing to brave his trials, ensuring that warriors, hunters, and shamans of every race prove their mettle in Kalimdor's rugged wilds."},kw={"dorn plainstalker","freewind post","tauren trial","test of endurance","test of faith","test of lore","test of strength","thousand needles","weathered nook"},rel={"subzone:weathered-nook","quest:1149","quest:1150","quest:1151","quest:1152","subzone:freewind-post","zone:thousandneedles","topic:tauren"},src={"Dorn Plainstalker"}}
E["npc:elder-morningdew"] = {t="npc",n="Elder Morningdew",z="thousandneedles",s="Elder Morningdew is an ancient night elf spirit who appears during the Lunar Festival in Thousand Needles. She offers wisdom and ancestral blessings to travelers who seek her out amid the arid canyons and dried salt flats of the Shimmering Flats.",h="Elder Morningdew is an ancient night elf spirit who appears during the Lunar Festival in Thousand Needles.",sec={{t="An Honored Spirit of the Festival",b="Throughout the Lunar Festival, the spirits of revered night elf and tauren ancestors manifest across Kalimdor and the Eastern Kingdoms to celebrate wisdom, legacy, and peace. Elder Morningdew is one such apparition, visiting Thousand Needles to greet honoring pilgrims. Bound by neither faction nor mortal conflict, she bestows her coin of ancestry upon any adventurer respectful enough to seek her counsel and receive her blessing.",sp=0}},faq={{q="Who is Elder Morningdew?",a="Elder Morningdew is a night elf ancestral spirit who manifests during the annual Lunar Festival. She waits in Thousand Needles to be honored by travelers from both the Alliance and the Horde.",al={"elder morningdew lore","who is morningdew","morningdew identity"},it="identity"},{q="What is the purpose of seeking her out?",a="Adventurers seek her out during the Lunar Festival to pay their respects to the ancestors, receiving a Coin of Ancestry and a blessing of wisdom in exchange for honoring her spirit.",al={"why find elder morningdew","morningdew purpose","lunar festival elder"},it="purpose"},{q="Does she belong to the Alliance or Horde?",a="Like all Lunar Festival elders, Elder Morningdew stands neutral to mortal politics. Both Alliance and Horde adventurers can approach her peacefully to pay their respects.",al={"is morningdew hostile","elder morningdew faction","can horde talk to morningdew"},it="side"}},ang={["race:NightElf"]="For the kaldorei, seeking out ancient elders like Morningdew is a sacred duty of reverence, connecting modern night elves with the honored spirits who came before them.",["race:Tauren"]="Tauren honor ancestral spirits deeply, making encounters with elders across Kalimdor a natural extension of their cultural reverence for past wisdom."},kw={"ancestor","elder","elder morningdew","ghost","lunar festival","morningdew","night elf","thousand needles"},rel={"quest:8724","zone:thousandneedles","topic:night-elf"},src={"Elder Morningdew"}}
E["npc:elder-skyseer"] = {t="npc",n="Elder Skyseer",z="thousandneedles",s="Elder Skyseer is the spirit of an ancestral tauren residing atop the towering bluffs of Freewind Post in Thousand Needles. As an honoured elder returned from the spirit world, he observes the ongoing journeys of the Horde and remains deeply tied to the resting grounds of his people.",h="Elder Skyseer is the spirit of an ancestral tauren residing atop the towering bluffs of Freewind Post in...",sec={{t="A Spirit of Freewind Post",b="Perched high above the salt canyons of Thousand Needles, Elder Skyseer lingers at the windswept mesa settlement of Freewind Post. While the tauren of Freewind Post bustle around the outpost's perilous bridges and wooden platforms, Skyseer watches over the realm as an ancestor who has crossed beyond the mortal veil. He serves as an ancestral beacon for travelers seeking the wisdom of past generations, offering his blessings to those who honor old traditions.",sp=0},{t="Ties to the Ancestral Lands",b="Though his spirit commonly manifests among the wind-carved needles, Skyseer belongs to the long line of tauren ancestors whose people honor the sacred soil of Mulgore, where the ancestral spirits of Red Rocks watch over the tribes. Spirits like Skyseer reveal how thin the veil between the physical realm and the ancestral spirits remains for the tauren, guiding future generations through remembrance and ritual.",sp=0}},faq={{q="Who is Elder Skyseer?",a="Elder Skyseer is an ancestral tauren spirit who appears at Freewind Post in Thousand Needles. He is one of the revered elders whose spirits watch over modern travelers, offering ancestral guidance to those who seek him out.",al={"elder skyseer lore","who is skyseer","skyseer npc"},it="identity"},{q="Why is Elder Skyseer a ghost?",a="He is an ancient ancestor who has passed on from the mortal world. Tauren culture maintains a deep spiritual connection to their forebears, and certain prominent elders linger or return in spirit form to guide the living.",al={"why is skyseer dead","is elder skyseer dead","ghost tauren freewind"},it="history"},{q="What is his connection to Mulgore?",a="Like all tauren ancestors, Skyseer is honored by a people whose homeland is Mulgore, where the ancestral spirits of Red Rocks watch over the tribes. His own spirit, however, appears at Freewind Post in Thousand Needles.",al={"skyseer red rocks","skyseer mulgore connection"},it="ties"},{q="Where can I find Elder Skyseer?",a="Elder Skyseer is located at Freewind Post in Thousand Needles, lingering atop the fortified mesa settlement high above the canyon floor.",al={"elder skyseer location","find skyseer","where is skyseer"},it="place",gp=true},{q="Whose side is Elder Skyseer on?",a="Elder Skyseer stands with the Horde and the tauren tribes. Lingering as an ancestral spirit above the windswept mesas of Freewind Post, he watches over his living kin and travelers loyal to the Horde, offering ancestral guidance and wisdom from beyond the grave.",al={"skyseer faction","is elder skyseer horde","skyseer allegiances"},it="side",add=true}},ang={["race:Tauren"]="For the tauren, encountering Elder Skyseer is a direct communion with an ancestor, embodying the spiritual reverence taught at Red Rocks and across the plains of Mulgore.",["class:Shaman"]="As spiritual mediators who speak to the elements and spirits, shamans recognize in Elder Skyseer the enduring wisdom of ancestors who continue to watch over the living."},kw={"ancestor","elder skyseer","freewind post","red rocks","tauren ghost","thousand needles"},rel={"subzone:freewind-post","zone:thousandneedles","subzone:red-rocks","zone:mulgore","topic:tauren","quest:8682"},src={"Elder Skyseer"}}
E["npc:elu"] = {t="npc",n="Elu",z="thousandneedles",s="Elu is an apprentice wind rider stationed atop Freewind Post in Thousand Needles. Eager to begin his formal training and take to the skies, he tasks Horde travelers with retrieving wild wyvern eggs from nearby roosts.",h="Elu is an apprentice wind rider stationed atop Freewind Post in Thousand Needles.",sec={{t="An Eager Apprentice",b="Perched high above the salt flats and canyon floor at Freewind Post, Elu spends his days tending to the settlement's aerial mounts while dreaming of his own flight. As a young tauren apprentice, he longs to join the ranks of the master wind riders who patrol the towering mesas of Kalimdor. Before he can begin true flight training, however, he must prove his capability by supplying the roost with fresh wyvern stock, sending capable adventurers to harvest intact eggs from the fierce wild wyverns nesting at Highperch.",sp=0}},faq={{q="Who is Elu?",a="Elu is a tauren wind rider apprentice stationed at Freewind Post in Thousand Needles, responsible for helping secure and raise new mounts for the Horde's aerial network.",al={"elu freewind post","who is elu","tauren apprentice elu"},it="identity"},{q="Why does Elu need wyvern eggs?",a="Elu is tasked with replenishing the stable of wyverns for the master wind riders. Raising the beasts from freshly collected eggs ensures they can be properly trained and bonded as trusted mounts for the Horde.",al={"why wyvern eggs","elu wyvern quest","elu quest goal"},it="wants"},{q="Where does Elu send adventurers to find eggs?",a="He directs adventurers to Highperch, a dangerous mesa in western Thousand Needles where colonies of wild wyverns fiercely guard their nests.",al={"where are wyvern eggs","where is highperch","elu egg location"},it="place",gp=true},{q="Whose side is Elu on?",a="Elu is loyal to the Horde and his fellow tauren. Stationed high atop the bluffs of Freewind Post, he works alongside the master wind riders of the Horde to train and supply the aerial steeds vital for traveling across Kalimdor.",al={"elu faction","is elu horde","who does elu serve"},it="side",add=true},{q="Why is Elu at Freewind Post?",a="Elu serves as an apprentice wind rider at Freewind Post. He remains here to aid the flight masters and earn his place in the sky, tasked with securing fresh wyverns from the high perches of Thousand Needles so they can be trained for Horde riders.",al={"why is elu in thousand needles","elu freewind post","elu purpose"},it="why_here",add=true},{q="Who is Elu tied to?",a="Elu is an apprentice to the master wind riders of the Horde. He answers to the trainers and beast handlers who raise Kalimdor's winged wyverns, working under their guidance in hopes of beginning his own formal training as a wind rider.",al={"elu master","who does elu work for","elu wind riders"},it="ties",add=true}},ang={["race:Tauren"]="For tauren adventurers, assisting Elu supports a fellow tribesman striving to master the ancient and vital art of wyvern handling high above their ancestral canyon lands.",["faction:Horde"]="Gathering wyvern eggs for Elu directly strengthens the Horde's courier and transport network, keeping remote outposts across Kalimdor connected by air."},kw={"elu","freewind post","highperch","thousand needles","wind rider","wyvern","wyvern eggs"},rel={"subzone:freewind-post","quest:4767","subzone:highperch","zone:thousandneedles","topic:tauren","topic:horde"},src={"Elu"}}
E["npc:fizzle-brassbolts"] = {t="npc",n="Fizzle Brassbolts",z="thousandneedles",s="Fizzle Brassbolts is a prominent gnomish engineer stationed out on the baked salt flats of the Mirage Raceway in Thousand Needles. Alongside his rival, the goblin Pozzik, Fizzle co-founded the raceway to pit gnomish precision engineering against reckless goblin ingenuity in high-speed rocket car races. He constantly seeks parts, fuel, and strange desert reagents to keep his racing team running.",h="Fizzle Brassbolts is a prominent gnomish engineer stationed out on the baked salt flats of the Mirage Raceway...",sec={{t="A Matter of Principle and Pistons",b="Out in the shimmering heat of the Shimmering Flats, political alliances and ancient grudges yield to the roar of motorized engines. Fizzle Brassbolts arrived here with one goal in mind: proving once and for all that gnomish craftsmanship is vastly superior to crude goblin tinkering. Together with his goblin counterpart Pozzik, he helped lay out the Mirage Raceway, bringing race cars, pit crews, and spectators to an otherwise desolate basin.",sp=0},{t="Tinkering on the Flats",b="Racing across dry salt beds at breakneck speeds requires constant improvisation. As an avid member of the Mechanical Engineers' Guild of Azeroth (MEGA), Fizzle does not shy away from unorthodox experiments. Whether testing volatile mixtures concocted from local creature venom or contracting travelers to fetch replacement mechanical parts, Fizzle is determined to keep his driver's wheels turning faster than any explosive goblin contraption.",sp=0}},faq={{q="Who is Fizzle Brassbolts?",a="Fizzle Brassbolts is a master gnomish engineer and lead organizer for the gnomish racing crew stationed at the Mirage Raceway in Thousand Needles.",al={"who is fizzle","fizzle brassbolts lore","gnome at raceway"},it="identity"},{q="Why did Fizzle come to the Shimmering Flats?",a="He came to settle a technical debate with the goblin engineer Pozzik over whose race boasts superior engineering. Together, they established the Mirage Raceway to test their rocket cars head-to-head on the flat salt basin.",al={"why is fizzle here","raceway purpose","why raceway built"},it="why_here"},{q="What is MEGA?",a="MEGA stands for the Mechanical Engineers' Guild of Azeroth. Fizzle is a dedicated member, representing the guild's commitment to meticulous design and technical refinement.",al={"fizzle guild","mechanical engineers guild","what is mega"}},{q="Why does Fizzle need creature venom for race cars?",a="Fizzle experiments constantly with local reagents to formulate powerful engine fluids, additives, and accelerants capable of giving his rocket cars an edge over Pozzik's machines.",al={"salt flat venom quest","venom racing fuel","why does he need venom"},it="motive"},{q="Does Fizzle fight against the goblins?",a="Not with weapons. While deep professional jealousy exists between them, Fizzle and Pozzik maintain an uneasy, neutral truce at the raceway to focus purely on high-speed competition.",al={"is fizzle hostile to goblins","fizzle pozzik fight"},it="conflict"},{q="Who is Pilot Longbeard?",a="Pilot Longbeard is a dwarven aviator and personal friend of the Brassbolts family who shares a fondness for dangerous machinery and desert tracks.",al={"pilot longbeard connection","fizzle pilot friend"},it="ties"},{q="Whose side is Fizzle Brassbolts on?",a="Fizzle Brassbolts represents the gnomes and the Mechanical Engineers' Guild of Azeroth (MEGA). Neutral toward both Alliance and Horde travelers, here on the Shimmering Flats he maintains a functional working relationship with goblin engineers like Pozzik. While fiercely loyal to proving gnomish engineering superior to that of the goblins, their rivalry is focused on the Mirage Raceway rather than open warfare.",al={"is fizzle alliance","fizzle brassbolts faction","who does fizzle work for"},it="side",add=true},{q="What does Fizzle Brassbolts want?",a="Fizzle wants nothing more than to prove absolute gnomish engineering supremacy over goblin technology. To that end, he co-founded the Mirage Raceway alongside his goblin rival Pozzik. He focuses entirely on developing faster rocket cars, procuring exotic fuel ingredients like the salty venom of the Shimmering Flats scorpids, and beating the goblin team across the salt flats.",al={"what does fizzle want","fizzle brassbolts goal","why is fizzle racing"},it="wants",add=true}},ang={["race:Gnome"]="Fizzle carries the honor of all Gnomeregan into the desert, dead-set on proving gnomish precision outperforms goblin recklessness.",["profession:Engineering"]="Fellow engineers will appreciate Fizzle's dedication to optimizing rocket propulsion and drafting cutting-edge automotive designs under harsh desert conditions.",["faction:Alliance"]="Though operating in a neutral speed zone, Fizzle provides a friendly face and mechanical work for Alliance wanderers passing south toward Tanaris."},kw={"brassbolts","fizzle","mega","mirage raceway","pozzik","rocket car","shimmering flats","thousand needles"},rel={"subzone:mirage-raceway","npc:pozzik","quest:1104","zone:thousandneedles","npc:pilot-longbeard","topic:gnome","topic:goblin","zone:tanaris"},src={"Fizzle Brassbolts"}}
E["npc:hagar-lightninghoof"] = {t="npc",n="Hagar Lightninghoof",z="thousandneedles",s="Hagar Lightninghoof is a tauren scout stationed high atop Freewind Post in Thousand Needles. Driven by rumors of a strange clutch hidden in the canyon depths, he investigates reports of an alien egg guarded fiercely by local wind serpents.",h="Hagar Lightninghoof is a tauren scout stationed high atop Freewind Post in Thousand Needles.",sec={{t="The Strange Clutch",b="While stationed among the towering bluffs of Freewind Post, Hagar Lightninghoof caught wind of rumors regarding an unnatural egg nestled deep inside a cavern below. The local wind serpents guarded the nest with unusual ferocity, keeping curious scouts at bay. Seeking an adventurer bold enough to braze the serpents' den, Hagar hopes to study the specimen firsthand and discern what manner of beast could warrant such defensive instincts from the canyon's natural predators.",sp=0},{t="A Myth Hatched",b="When an adventurer finally recovers the egg and brings it to Freewind Post, it hatches directly in front of Hagar, revealing a young wind serpent resembling the legendary Arikara—a revered spirit known in tauren folklore as the embodiment of vengeance. Realizing the grave cultural and spiritual significance of the creature's return, Hagar wastes no time dispatching the traveler to consult with the elder Motega Firemane.",sp=1}},faq={{q="Who is Hagar Lightninghoof?",a="Hagar Lightninghoof is a tauren quest giver residing at Freewind Post in Thousand Needles. He investigates anomalous wildlife in the canyons, particularly an unusual wind serpent egg reported deep within a nearby cavern.",al={"who is hagar","hagar lightninghoof role","hagar lore"},it="identity"},{q="Where can Hagar Lightninghoof be found?",a="He is located atop Freewind Post, the central Horde outpost perched upon the massive rock needles of central Thousand Needles.",al={"where is hagar","hagar lightninghoof location","freewind post hagar"},it="place",gp=true},{q="What is the 'alien egg' Hagar is looking for?",a="The alien egg is an unusual egg guarded by wind serpents in a subterranean den. Hagar asks adventurers to retrieve it so he can investigate its nature.",al={"alien egg","what is the egg","wind serpent egg"},sp=1,it="wants"},{q="Who does Hagar consult about the egg?",a="Hagar sends the adventurer to speak with Motega Firemane, an elder at Freewind Post who possesses deeper wisdom regarding tauren traditions.",al={"who do i turn serpent wild into","hagar follow up quest","where to go after hagar"},sp=1,it="next_step"},{q="Whose side is Hagar Lightninghoof on?",a="Hagar Lightninghoof is loyal to the Horde and his fellow tauren. Stationed atop the towering spires of Freewind Post, he entrusts his tasks solely to Horde champions who prove capable of braving the dangerous canyons below.",al={"hagar lightninghoof faction","is hagar horde"},it="side",add=true},{q="Why is Hagar Lightninghoof here in Freewind Post?",a="Hagar traveled to Thousand Needles after hearing rumors of a peculiar, alien egg spotted in the wind serpent nests. Intrigued by the strange find, he made his camp at Freewind Post to find someone bold enough to retrieve it past the serpent guards.",al={"why is hagar here","why did hagar come to thousand needles"},it="why_here",add=true},{q="Who is Hagar Lightninghoof tied to?",a="Hagar works alongside the tauren defenders of Freewind Post and consults closely with Motega Firemane. When his investigations reveal matters steeped in ancient tauren legends and sacred omens, it is Motega he turns to for guidance.",al={"hagar ties","who does hagar work with"},it="ties",add=true}},ang={["race:Tauren"]="For tauren travelers, assisting Hagar leads to the stirring realization that ancient legends of Arikara, the winged manifestation of vengeance, are living reality in the canyons below.",["faction:Horde"]="Stationed high above the canyon floor at Freewind Post, Hagar relies on capable Horde warriors to brave perilous dens that normal scouts cannot safely breach."},kw={"alien egg","arikara","freewind post","hagar","lightninghoof","motega firemane","thousand needles","wind serpent"},rel={"subzone:freewind-post","quest:4821","quest:4865","npc:motega-firemane","quest:5088","zone:thousandneedles","topic:tauren","topic:horde"},src={"Hagar Lightninghoof"}}
E["npc:kanati-greycloud"] = {t="npc",n="Kanati Greycloud",z="thousandneedles",s="Kanati Greycloud is a tauren hunter stationed at Whitereach Post within Thousand Needles. Alongside his hunting companions, he musters what defense he can while enduring constant hostility from the local Galak centaur.",h="Kanati Greycloud is a tauren hunter stationed at Whitereach Post within Thousand Needles.",sec={{t="A Precarious Perch",b="Kanati Greycloud makes his camp at Whitereach Post, high atop the sandstone spires of western Thousand Needles. While the canyon offers abundant game and open vistas, it is hemmed in by the Galak centaur, whose warbands contest every inch of the arid flats below. Together with other tauren hunters, Kanati keeps watch over the canyon floor, striving to preserve the post against the brutal depredations of the surrounding marauders.",sp=0},{t="Centaur Ambush",b="The Galak centaur do not merely seek to isolate Whitereach Post; they intend to annihilate its defenders outright. Messengers sent between centaur camps carry explicit orders targeting Kanati and his companions for assassination. It falls to visiting travelers to intercept these marching orders and stand shoulder-to-shoulder with Kanati when the Galak raiding parties descend upon the mesa to cut down the outpost's hunters.",sp=1}},faq={{q="Who is Kanati Greycloud?",a="Kanati Greycloud is a tauren hunter based at Whitereach Post in western Thousand Needles, where he maintains a camp and defends against predatory local threats.",al={"who is kanati","kanati greycloud lore","whitereach post tauren"},it="identity"},{q="Where can I find Kanati Greycloud?",a="Kanati is located at Whitereach Post, an elevated tauren encampment situated along the northern bluffs in the western portion of Thousand Needles.",al={"kanati location","where is kanati","where is greycloud"},gp=true},{q="Why are the Galak centaur trying to kill him?",a="The Galak centaur seek total dominance over the canyons of Thousand Needles and actively target Horde outposts. Intercepted orders reveal a coordinated plot by the centaur to assassinate Kanati and break the post's defenses.",al={"why centaur attack kanati","galak assassination plot","protect kanati why"}},{q="Is Kanati related to other Greyclouds?",a="He shares his surname with Tor Greycloud and Kar Greycloud, two tauren found elsewhere in the Kalimdor wilderness, though the exact familial bond between them is not detailed.",al={"greycloud family","tor greycloud relative","kar greycloud"},it="ties"},{q="Whose side is Kanati Greycloud on?",a="Kanati Greycloud is a tauren hunter loyal to the Horde. He welcomes travelers of the Horde who visit Whitereach Post and relies on them to help defend his camp from hostile threats in the canyon.",al={"kanati faction","is kanati horde","kanati alliance or horde"},it="side",add=true},{q="What does Kanati Greycloud want?",a="Kanati simply wants to maintain his hunting camp in peace and ensure his companions survive. Because the local Galak centaur seek to drive out or slaughter all intruders, his primary concern is defending against their assassination attempts.",al={"what does kanati need","kanati greycloud goals","why help kanati"},it="wants",add=true},{q="Why is Kanati Greycloud here?",a="Kanati established a hunting camp at Whitereach Post alongside his companions to hunt the game of Thousand Needles. Unfortunately, setting up camp in the canyon placed him squarely in the territory contested by the hostile Galak centaur.",al={"why is kanati at whitereach post","what is kanati doing here","kanati greycloud purpose"},it="why_here",add=true}},ang={["race:Tauren"]="For tauren traversing Thousand Needles, aiding Kanati at Whitereach Post is a vital defense of tribal kin against their ancient, bitter enemies, the centaur.",["faction:Horde"]="Whitereach Post serves as a critical vantage point over the needle canyons; keeping Kanati alive ensures Horde scouts retain eyes on centaur troop movements."},kw={"assassination plot","centaur","galak","greycloud","kanati","thousand needles","whitereach post"},rel={"subzone:whitereach-post","zone:thousandneedles","quest:4881","quest:4966","topic:centaur","topic:tauren","topic:horde"},src={"Kanati Greycloud"}}
E["npc:kravel-koalbeard"] = {t="npc",n="Kravel Koalbeard",z="thousandneedles",s="Kravel Koalbeard is a scheming dwarven entrepreneur and con artist stationed out at the Mirage Raceway in the Shimmering Flats. Rather than cheering purely for the love of the sport, he views the fierce gnome and goblin racing rivalry as a golden opportunity to fill his pockets. From scavenging stray machine parts to fixing race results through blackmail and booze, Kravel is always hunting for his next profitable scheme.",h="Kravel Koalbeard is a scheming dwarven entrepreneur and con artist stationed out at the Mirage Raceway in the...",sec={{t="A Con Artist in the Flats",b="While most spectators and crew members at the Mirage Raceway are consumed by mechanical rivalries and the roar of rocket engines, Kravel Koalbeard has his eyes squarely on everyone's coin purses. He is an opportunist who operates in the dusty cracks of the raceway encampment, quick to offer contracts and favors that rarely have clean motives. Kravel sees the high-stakes friction between gnome and goblin engineers not as an inspiring competition, but as a fertile ground for extortion, sabotage, and theft.",sp=0},{t="Rigging the Track",b="Kravel's operations stretch far beyond picking up discarded salvage on the salt flats. To manipulate odds and ensure outcomes tip his way, Kravel is known to send willing adventurers on illicit errands—peddling rumors, running blackmail schemes, and even inebriating pit crews right before a showdown. Whether plying goblin mechanics with potent spirits or slipping strong drinks to gnomish pilots, Kravel will stoop to whatever underhanded trick is necessary to line his pockets on race day.",sp=1}},faq={{q="Who is Kravel Koalbeard?",a="Kravel Koalbeard is a dwarf schemer and opportunist stationed at the Mirage Raceway in the Shimmering Flats. He uses the rivalry between gnomes and goblins to line his pockets through salvage, race-fixing, and extortion.",al={"who is kravel","kravel koalbeard identity","mirage raceway dwarf"},it="identity"},{q="What does Kravel Koalbeard do at the Mirage Raceway?",a="Kravel hires travelers to run underhanded errands around the track. His schemes include collecting scavenged rocket car parts, digging up blackmail material, and sabotaging racing teams by getting their mechanics and pilots drunk to sway race outcomes.",al={"kravel purpose","what does kravel want","kravel schemes"},it="purpose"},{q="Why is Kravel trying to get race crews drunk?",a="Kravel wagers heavily on the outcome of the rocket car races. By getting either the gnomes or the goblins intoxicated before race time, he rigs the contest to favor whatever outcome makes him the most profit.",al={"get the gnomes drunk quest","get the goblins drunk","kravel sabotage"},it="motive"},{q="Where can Kravel Koalbeard be found?",a="He is located in the Shimmering Flats of Thousand Needles, lingering right around the bustling pit camps of the Mirage Raceway.",al={"kravel location","where is kravel","kravel thousand needles"},it="place",gp=true},{q="Does Kravel have ties outside Thousand Needles?",a="Yes. His shady dealings involve contacts in the goblin ports of Ratchet and Booty Bay, including dealings tied to Ratchet's Wharfmaster Dizzywig, rumormongers, and exotic brews from Stranglethorn Vale.",al={"kravel booty bay","kravel connections"},it="ties"},{q="Will Kravel work with both Alliance and Horde?",a="Like many figures operating in neutral venues like the Mirage Raceway, Kravel is interested in gold rather than faction loyalties. He will happily employ both Alliance and Horde adventurers to carry out his schemes.",al={"is kravel alliance only","can horde talk to kravel"},it="side"},{q="What does Kravel Koalbeard want?",a="Kravel is entirely driven by profit and self-interest. He seeks to line his pockets through any scheme available out on the Shimmering Flats, from running parts and peddling favors to orchestrating blackmail. His most audacious ambition is manipulating the outcome of the Mirage Raceway itself, plotting to sabotage and rig the contests by keeping the pit crews and drivers thoroughly inebriated.",al={"what does kravel want","kravel koalbeard goals","kravel motives"},it="wants",add=true},{q="Why is Kravel Koalbeard out in Thousand Needles?",a="The Mirage Raceway in the Shimmering Flats is a lawless hive of high-stakes gambling, fierce rivalry, and reckless engineering, making it prime hunting ground for a con artist. Kravel set up camp alongside the competing gnomes and goblins because their bitter obsession with beating one another leaves them blind to opportunists and easy marks for his schemes.",al={"why is kravel here","why is kravel at mirage raceway","kravel shimmer flats"},it="why_here",add=true}},ang={["race:Dwarf"]="Unlike the honest miners, prospectors, and mountaineers of Ironforge, Kravel is an unabashed rogue and swindler who embarrasses traditional dwarven values.",["race:Gnome"]="Gnomes should keep a close eye on their drinks and blueprints around Kravel, who is just as eager to drug gnomish pilots as he is to sabotage their machines.",["class:Rogue"]="Rogues will find Kravel's line of work familiar: theft, sabotage, blackmail, and manipulating greedy targets from the shadows."},kw={"blackmail","koalbeard","kravel","mirage raceway","rocket car","sabotage","shimmering flats","thousand needles"},rel={"subzone:mirage-raceway","zone:thousandneedles","quest:1110","quest:1492","subzone:booty-bay","topic:dwarf","topic:gnome","topic:goblin"},src={"Kravel Koalbeard"}}
E["npc:lakota-windsong"] = {t="npc",n="Lakota Windsong",z="thousandneedles",s="Lakota Windsong is a young tauren held captive atop the bluffs of Darkcloud Pinnacle in Thousand Needles. After rejecting an unwanted proposal from Arnak Grimtotem, she was abducted by force and awaits rescue from the Grimtotem tribe's clutches.",h="Lakota Windsong is a young tauren held captive atop the bluffs of Darkcloud Pinnacle in Thousand Needles.",sec={{t="A Deadly Courtship",b="Not long after the Third War, Lakota Windsong was pursued by Arnak Grimtotem. Unwilling to join his clan or accept his courtship, she turned down his proposal. Arnak refused to take no for an answer; he returned under cover of night, slaughtered Lakota's brother when he tried to intervene, and carried her off into the jagged heights of Thousand Needles. Confined high above the canyon floor at Darkcloud Pinnacle, she remains trapped under heavy guard while Arnak still insists on making her his bride.",sp=0},{t="Descent to Safety",b="Surrounded by treacherous Grimtotem bandits, Lakota cannot fight her way down the cliffs alone. Only a brave escort can lead her across the suspension bridges and down the winding paths to the canyon basin below. Once she breaks free of Darkcloud Pinnacle, Lakota flees toward the safety of Freewind Post, carrying word of her rescue to Thalia Amberhide and the defenders stationed there.",sp=1}},faq={{q="Why is Lakota Windsong being held at Darkcloud Pinnacle?",a="She refused a marriage proposal from Arnak Grimtotem. Rather than accept her refusal, Arnak murdered her brother and abducted Lakota, dragging her to the Grimtotem stronghold at Darkcloud Pinnacle in hopes of forcing her hand.",al={"why is lakota captured","who kidnapped lakota","why is lakota in darkcloud pinnacle"},it="why_here"},{q="Where does Lakota go once she is rescued?",a="After reaching the base of Darkcloud Pinnacle safely, Lakota makes her way to Freewind Post, where she can find refuge among the Horde defenders and report her ordeal to Thalia Amberhide.",al={"where does lakota run","where does she go after escort","lakota destination"},sp=1,it="next_step"},{q="Who is Arnak Grimtotem?",a="Arnak is a violent warrior of the treacherous Grimtotem clan who murdered Lakota's brother and abducted her when she declined to marry him.",al={"who is arnak","who kidnapped her","arnak lore"},it="threat"},{q="Who is Lakota Windsong?",a="Lakota Windsong is a tauren woman held captive atop Darkcloud Pinnacle. When Arnak Grimtotem sought her hand in marriage, Lakota refused him. Enraged by her rejection, Arnak murdered her brother and dragged her away to the Grimtotem stronghold in Thousand Needles, intending to force the union upon her against her will.",al={"lakota windsong who","who is lakota","lakota identity"},it="identity",add=true},{q="Whose side is Lakota Windsong on?",a="Lakota is aligned with the peaceful tauren of the Horde and looks to the braves at Freewind Post for protection. She holds deep enmity toward the Grimtotem clan, who brutally took her brother's life and abducted her.",al={"lakota windsong faction","is lakota horde","lakota allegiance"},it="side",add=true},{q="What does Lakota Windsong want?",a="Lakota desires only to escape Darkcloud Pinnacle and reach safety away from the Grimtotem bandits. With her brother slain defending her, she relies on someone bold enough to fight past her captors and guide her safely down the winding paths toward Freewind Post.",al={"lakota windsong goal","what does lakota need","lakota desires"},it="wants",add=true},{q="Who is Lakota Windsong tied to?",a="Lakota was fiercely protected by her brother, who lost his life attempting to defend her from Arnak Grimtotem. She also places her trust in Thalia Amberhide and the defenders stationed at Freewind Post.",al={"lakota family","lakota connections","who is lakota related to"},it="ties",add=true}},ang={["race:Tauren"]="Lakota's ordeal is a stark reminder of the treachery festering among the Grimtotem, whose defiance of Cairne Bloodhoof's leadership regularly turns violent.",["faction:Horde"]="Rescuing Lakota strikes a blow against Grimtotem dominance over Thousand Needles and secures safe passage for travelers resting at Freewind Post."},kw={"arnak grimtotem","darkcloud pinnacle","free at last","freewind post","lakota windsong","thalia amberhide","thousand needles"},rel={"quest:4904","subzone:darkcloud-pinnacle","subzone:freewind-post","npc:thalia-amberhide","zone:thousandneedles","topic:tauren","topic:horde","topic:third-war"},src={"Lakota Windsong"}}
E["npc:mad-magus-tirth"] = {t="npc",n="Magus Tirth",z="thousandneedles",s="Magus Tirth is an eccentric human wizard dwelling out on the salt flats of the Mirage Raceway in Thousand Needles. Known locally for breeding chickens and tormenting his polymorphed apprentice, he is also a scholar of formidable arcane lore who has squandered valuable tomes on racing bets.",h="Magus Tirth is an eccentric human wizard dwelling out on the salt flats of the Mirage Raceway in Thousand...",sec={{t="A Wizard in the Dust",b="While most mages of his caliber study in the libraries of Dalaran or Stormwind, Magus Tirth has taken up residence amid the grease and roar of the Shimmering Flats. Surrounded by speeding rocket cars, Tirth peddles chickens to passersby and spends his days barking orders at 'Plucky' Johnson, his unfortunate former apprentice whom he keeps trapped in poultry form. Despite this eccentric demeanor, Tirth possesses genuine arcane mastery, having authored esoteric texts on magical power before losing them to reckless wagers on the speedway.",sp=0},{t="Rituals and Debts",b="Tirth's scholarly legacy includes 'Rituals of Power', an arcane manual sought after by practicing mages. Unfortunately for aspiring spellcasters, Tirth no longer owns his own masterwork. Crushed under gambling debts accrued at the Mirage Raceway, the mage sold the tome to an agent of the Scarlet Crusade to square his losses, forcing apprentices and seekers of knowledge to track the book down into hostile territory.",sp=1}},faq={{q="Why is Magus Tirth out in the desert?",a="Tirth lives on the Shimmering Flats beside the Mirage Raceway, drawn by the spectacle and the gambling. Rather than pursuing scholarly life in a major city, he watches the gnome and goblin racers, sells chickens, and indulges his vices.",al={"why is tirth here","magus tirth shimmering flats","tirth location"},it="why_here"},{q="Who is the chicken next to him?",a="The chicken is 'Plucky' Johnson, Magus Tirth's former apprentice. Tirth magically polymorphed Johnson into a chicken and spends much of his time tormenting him, commanding him to dance out on the salt flats.",al={"who is plucky","plucky johnson","tirth chicken apprentice"},it="ties"},{q="What is the book Rituals of Power?",a="Rituals of Power is an advanced treatise on arcane energy authored by Magus Tirth. It is an essential text for mages looking to advance their craft, though Tirth parted with it to pay off his mounting racing debts.",al={"rituals of power","tirth book","mage quest book"}},{q="Why is his book difficult to obtain?",a="Tirth no longer has his copy of Rituals of Power. Mages seeking it must follow up on his account of how he parted with the tome.",al={"who has rituals of power","tirth debts","scarlet crusade book"}},{q="Who is Magus Tirth?",a="Magus Tirth is an eccentric human spellcaster residing at the Mirage Raceway out on the Shimmering Flats. Though clearly knowledgeable in esoteric arcane lore—having penned a notable magical tome titled Rituals of Power—he now spends his days peddling Ancona chickens and tormenting the polymorphed creature beside him.",al={"who is mad magus tirth","who is tirth","magus tirth lore"},it="identity",add=true},{q="Whose side is Magus Tirth on?",a="Magus Tirth remains strictly neutral. He makes his living out on the salt flats of the Shimmering Flats alongside goblin and gnome engineers, happily offering his wares and magical counsel to travelers of both the Alliance and the Horde without taking part in their wider war.",al={"is magus tirth alliance or horde","tirth faction","is magus tirth neutral"},it="side",add=true},{q="What does Magus Tirth want?",a="Beyond scraping together coin from race spectators by selling Ancona chickens, Tirth primarily amuses himself by tormenting the enchanted chicken at his side, Plucky. He once sought quick money to pay off his steep gambling debts, which led him to sell away his own scholarly research.",al={"what does tirth want","magus tirth motives","why is tirth selling chickens"},it="wants",add=true}},ang={["class:Mage"]="Tirth is an important figure for mages seeking to deepen their understanding of arcane power, as he authored the vital treatise 'Rituals of Power'."},kw={"ancona chicken","magus tirth","mirage raceway","plucky","plucky johnson","rituals of power","shimmering flats","thousand needles","tirth"},rel={"subzone:mirage-raceway","zone:thousandneedles","quest:1950","topic:scarlet-crusade"},src={"Magus Tirth"}}
E["npc:motega-firemane"] = {t="npc",n="Motega Firemane",z="thousandneedles",s="Motega Firemane is a tauren scholar stationed at Whitereach Post in Thousand Needles. Dedicated to cataloging the dangerous wildlife of the canyon, he finds his studies disrupted by a vengeful wind serpent spirit and the reckless misadventures of his young assistant.",h="Motega Firemane is a tauren scholar stationed at Whitereach Post in Thousand Needles.",sec={{t="Scholar of the Canyons",b="Four years following the Third War, Motega Firemane journeyed south into Thousand Needles to observe and record the distinct beasts surviving among the towering mesas. Accompanied by his youthful assistant, Pao'ka Swiftmountain—whose protective father was reluctant to let him leave Mulgore—Motega set up camp alongside Kanati Greycloud at Whitereach Post. While his original calling was quiet natural observation, the harsh perils of the canyon floor continually demand a more martial approach to survival.",sp=0},{t="The Wrath of Arikara",b="Motega's peaceful research was upended when word arrived from Freewind Post that Arikara, a ferocious and legendary winged serpent spirit, had returned to the canyons seeking vengeance against Cairne Bloodhoof. Perplexed by why such a creature held a vendetta against the High Chieftain, Motega acted swiftly to protect the Horde. He instructed scouts to gather Incendia agave from the canyon basin and carry it to Elder Magatha Grimtotem in Thunder Bluff to be enchanted into a sacred powder. Using this preparation, hunters summoned and slew the serpent spirit, returning its hide to Whitereach Post as proof that Cairne was safe.",sp=1},{t="Guardian of Whitereach",b="Arikara was not the only hazard challenging Motega's stay at Whitereach Post. Local Galak centaur continuously probed the camp, even scheming an assassination plot against Kanati Greycloud and his followers. To worsen matters, young Pao'ka wandered away from the safety of the campfire and vanished into the wyvern-infested heights of Highperch. Though frustrated by the young brave's thoughtlessness, Motega was immensely relieved when Horde travelers escorted the youth back alive.",sp=1}},faq={{q="Who is Motega Firemane?",a="Motega Firemane is a tauren researcher stationed at Whitereach Post in Thousand Needles. He came to the canyons to study the local wildlife alongside fellow braves and his assistant, Pao'ka Swiftmountain.",al={"motega firemane lore","who is motega","whitereach motega"},it="identity"},{q="Where can Motega Firemane be found?",a="He is located at Whitereach Post, a small Horde campsite nestled along the canyon floor of Thousand Needles, situated north of the shimmering salt flats.",al={"motega location","where is motega firemane","motega firemane map"},it="place",gp=true},{q="Why is Motega concerned about Arikara?",a="Arikara is a vengeful serpent spirit that has manifested in Thousand Needles targeting Cairne Bloodhoof. Though baffled as to why the spirit bears a grudge against the High Chieftain, Motega takes the threat seriously and directs hunters to summon and eliminate the creature.",al={"who is arikara","why kill arikara","arikara cairne"},sp=1,it="motive"},{q="What role does Magatha Grimtotem play in Motega's plans?",a="Motega tasks adventurers with collecting Incendia agave and carrying it to Magatha Grimtotem on the Elder Rise in Thunder Bluff. Magatha uses her shamanic knowledge to enchant the plant into a sacred powder capable of summoning the elusive Arikara.",al={"magatha incendia powder","motega and magatha","sacred fire quest lore"},sp=1,it="ties"},{q="What happened to Motega's companion, Pao'ka?",a="Pao'ka Swiftmountain strayed into the dangerous wyvern roosts of Highperch and became lost. Motega was anxious over the youth's fate, especially given how reluctant Pao'ka's father had been to allow the journey, but travelers successfully escorted him back to Whitereach Post.",al={"pao'ka swiftmountain","missing tauren highperch","homeward bound quest"},sp=1},{q="What other dangers does Whitereach Post face?",a="Beyond rogue spirits and predators, the camp is actively targeted by the nearby Galak centaur, who orchestrate ambushes and plot assassinations against Kanati Greycloud and the other tauren stationed at the post.",al={"whitereach post threats","centaur at whitereach","galak centaur plot"},it="threat"},{q="Whose side is Motega Firemane on?",a="Motega Firemane is loyal to the tauren and the Horde. Stationed at Whitereach Post alongside Kanati Greycloud, he cooperates closely with Horde travelers and looks out for the interests of Cairne Bloodhoof and the tribes under Thunder Bluff's banner.",al={"motega firemane faction","motega firemane horde or alliance","is motega horde"},it="side",add=true},{q="What does Motega Firemane want?",a="Motega is primarily focused on studying the unique wildlife of Thousand Needles while keeping an eye on his young companion, Pao'ka Swiftmountain. However, threats to Thunder Bluff quickly take priority. When warned of the vengeful wind serpent Arikara, he seeks to summon and destroy the beast before it can endanger Cairne Bloodhoof.",al={"what does motega want","motega firemane goals","what is motega trying to do"},it="wants",add=true},{q="Why is Motega Firemane here?",a="Motega traveled down into Thousand Needles to observe and study the exotic beasts native to the canyon floor and surrounding mesas. Whitereach Post serves as a base camp for his research, though local troubles—from lost companions to menacing mythical serpents—often pull him away from his scholarly pursuits.",al={"why is motega in thousand needles","what brought motega to whitereach post","motega firemane purpose"},it="why_here",add=true}},ang={["faction:Horde"]="Motega represents the Horde's expansion into the untamed regions of Kalimdor, maintaining a tenuous research outpost while safeguarding High Chieftain Cairne Bloodhoof from spiritual threats.",["race:Tauren"]="Through his reverence for nature and dutiful devotion to Cairne Bloodhoof, Motega embodies the tauren ethos of studying the Earth Mother's creatures while defending the tribe against ancient spirits.",["class:Hunter"]="Hunters find common ground with Motega, who relies on skilled trackers to harvest canyon flora, track wyverns in Highperch, and stalk the mighty spirit Arikara."},kw={"arikara","cairne bloodhoof","kanati greycloud","magatha grimtotem","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post"},rel={"subzone:whitereach-post","zone:thousandneedles","npc:pao-ka-swiftmountain","npc:kanati-greycloud","npc:magatha-grimtotem","npc:cairne-bloodhoof","subzone:highperch","npc:hagar-lightninghoof"},src={"Motega Firemane"}}
E["npc:pao-ka-swiftmountain"] = {t="npc",n="Pao'ka Swiftmountain",z="thousandneedles",s="Pao'ka Swiftmountain is a young tauren naturalist stranded among the wild wyverns of Highperch in Thousand Needles. Having traveled south under the guidance of Motega Firemane, his youthful curiosity got the better of him when he ventured too close to a nesting site and ended up cornered in the cliffs.",h="Pao'ka Swiftmountain is a young tauren naturalist stranded among the wild wyverns of Highperch in Thousand...",sec={{t="A Naturalist in Trouble",b="Pao'ka came to the canyon country of Thousand Needles alongside Motega Firemane, eager to catalog and study the dangerous beasts of the canyons. His father had been reluctant to let his son go on such a perilous journey, and Pao'ka's recent misadventure proves those concerns were warranted. Fascinated by the magnificent wyverns inhabiting Highperch, the young scholar crept up the mountain trail behind a solitary tauren totem. Unsurprisingly, the territorial beasts took offense to his intrusion, driving him deep into the crags where he found himself trapped and terrified, unable to slip past the swooping predators to return to Whitereach Post.",sp=0}},faq={{q="Who is Pao'ka Swiftmountain?",a="Pao'ka is a young tauren scholar who accompanied Motega Firemane to Thousand Needles to study regional wildlife, only to become trapped by territorial wyverns on Highperch.",al={"who is pao'ka","paoka swiftmountain","who is the tauren at highperch"},it="identity"},{q="Where can Pao'ka Swiftmountain be found?",a="He is stranded atop Highperch in Thousand Needles. Reaching him requires finding a towering tauren totem near the cliffs, where a narrow path behind it climbs up the mountainside into the wyvern roosts.",al={"where is paoka","highperch path","how to find paoka"},it="place",gp=true},{q="Why is he hiding in Highperch?",a="His fascination with wyverns led him too close to one of their nests. The angry beasts chased him away and cut off his retreat, forcing him into hiding for several days.",al={"why is paoka trapped","why did wyverns attack paoka"},it="why_here"},{q="What happens after you help him escape?",a="Once escorted safely out of the nesting grounds, Pao'ka flees back to Motega Firemane at Whitereach Post, desperately hoping his mentor will not report the blunder to his father.",al={"homeward bound outcome","does paoka make it back"},sp=1,it="next_step"},{q="Whose side is Pao'ka Swiftmountain on?",a="Pao'ka belongs to the Horde. He is a young tauren naturalist who traveled into the canyon under the guidance of elders from his people, relying on Horde champions to help him navigate the dangers of Thousand Needles.",al={"paoka swiftmountain faction","is paoka horde","paoka swiftmountain side"},it="side",add=true},{q="What does Pao'ka Swiftmountain want?",a="Pao'ka wants safe escort out of Highperch and back to Whitereach Post without facing his mentor's wrath. He ventured up into the cliffs eager to study the wild wyverns, but after disturbing a nest and getting chased into hiding, his primary desire is simply to escape with his life and avoid being sent home to his father in disgrace.",al={"paoka goal","what does paoka want","paoka swiftmountain motive"},it="wants",add=true},{q="Who is Pao'ka Swiftmountain tied to?",a="Pao'ka is under the mentorship of Motega Firemane at Whitereach Post, who convinced Pao'ka's hesitant father to allow the youth out into the wild to study native beasts. Pao'ka dreads disappointing Motega or proving his protective father right by failing his expedition.",al={"paoka swiftmountain connections","who does paoka know","paoka mentor"},it="ties",add=true}},ang={["faction:Horde"]="Pao'ka represents the next generation of tauren scholars exploring Kalimdor; keeping him alive maintains strong ties with the elders at Whitereach Post.",["race:Tauren"]="Wyverns are deeply revered by the tauren as allies and faithful mounts, making Pao'ka's poorly planned intrusion both embarrassing and dangerous."},kw={"highperch","homeward bound","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post","wyverns"},rel={"subzone:highperch","quest:4770","npc:motega-firemane","subzone:whitereach-post","zone:thousandneedles","topic:tauren","topic:horde"},src={"Pao'ka Swiftmountain"}}
E["npc:parqual-fintallas"] = {t="npc",n="Parqual Fintallas",z="thousandneedles",s="Parqual Fintallas is a Forsaken scholar and former human historian of Lordaeron, currently residing in the Undercity's Apothecarium. Despite the grim surroundings of his undead existence, he retains a polite demeanor and an enduring passion for ancient lore, often assisting travelers sent to consult his deep historical expertise.",h="Parqual Fintallas is a Forsaken scholar and former human historian of Lordaeron, currently residing in the...",sec={{t="Scholar of Lost Lordaeron",b="In life, Parqual was a respected human scholar of Lordaeron who knew all there was to know of the kingdom, immersing himself in historical texts. When the plague of undeath struck, Parqual was among the many citizens slain and raised, only to eventually break free under Lady Sylvanas Windrunner. While the Forsaken largely embrace cold pragmatism and turn away from their former lives, Parqual retains his scholarly passion and pleasant manners, quietly longing for the historical tomes and memories of the world that once was.",sp=0},{t="Keeper of Ancient Lore",b="Parqual dwells among the bubbling vats and alchemists of the Apothecarium in the Undercity. Despite his macabre surroundings, he remains an invaluable font of knowledge regarding Azeroth's history. When adventurers undertake rigorous intellectual trials—such as the elusive 'Test of Lore'—they are directed to Parqual, who sends them to the Scarlet Monastery's library for a book and then puts a question of his own to them.",sp=0}},faq={{q="Where can I find Parqual Fintallas?",a="Parqual Fintallas can be found standing in the Apothecarium within the Undercity, the capital city of the Forsaken situated beneath the ruins of Lordaeron.",al={"parqual fintallas location","where is parqual","parqual undercity"},it="place",gp=true},{q="What is Parqual Fintallas known for?",a="Parqual was an accomplished historian in life who knew almost everything there was to know about the kingdom of Lordaeron. Even in undeath, he serves as an intellectual authority, assisting adventurers seeking obscure historical texts and ancient knowledge.",al={"who is parqual","what does parqual do","parqual fintallas lore"},it="fame"},{q="Why is Parqual involved in the Test of Lore?",a="The Test of Lore requires adventurers to demonstrate knowledge as well as strength. Because of his scholarly background, Parqual sets one of its trials: he sends them to the Scarlet Monastery for the book Beginnings of the Undead Threat, then asks them a question about it.",al={"parqual test of lore","test of lore undercity","parqual fintallas quest"},it="motive"},{q="Does Parqual share the hostile demeanor of most Forsaken?",a="Unlike many bitter and cynical Forsaken, Parqual is remarkably gentle and polite. He greets adventurers with genuine warmth, noting how nice it is whenever someone takes the time to speak with him.",al={"is parqual friendly","parqual personality"}},{q="Who is Parqual Fintallas?",a="Parqual Fintallas was once a renowned human scholar in Capital City who knew everything there was to know about the kingdom of Lordaeron. Claimed by the Plague and risen into undeath, he now resides among the Forsaken in the Undercity's Apothecarium. Despite his condition, he retains his deep passion for historical lore, tomes, and quiet scholarship.",al={"who is parqual","parqual fintallas","who is fintallas"},it="identity",add=true},{q="Whose side is Parqual Fintallas on?",a="Parqual is aligned with the Forsaken and the Horde, dwelling peacefully within the Undercity. Unlike many of his embittered kin, he bears little malice toward travelers and willingly shares his historical expertise with Horde wanderers seeking knowledge.",al={"who does parqual serve","parqual faction","is parqual horde"},it="side",add=true},{q="What does Parqual Fintallas want?",a="Parqual seeks to preserve the history of Lordaeron and continue his scholarly pursuits in undeath. He often desires the recovery of ancient tomes and books from his former life, and he readily assists those who come seeking forgotten records and historical wisdom.",al={"what does parqual want","parqual fintallas goals","parqual motive"},it="wants",add=true},{q="Why is Parqual Fintallas here in the Apothecarium?",a="Parqual makes his home in the Undercity's Apothecarium, surrounded by researchers and scholars. Though surrounded by darker alchemical works, he uses the quiet corners of the city to study and preserve historical records, acting as a resource for those pursuing lost lore.",al={"why is parqual here","why is parqual in undercity","what is parqual doing in the apothecarium"},it="why_here",add=true}},ang={["race:Undead"]="Parqual is a rare reminder of the kingdom of Lordaeron's intellectual past, clinging quietly to scholarship and civilized conversation amidst the bleakness of the Apothecarium.",["faction:Horde"]="When Horde adventurers face trials of the mind rather than the blade, Parqual provides the deep historical wisdom needed to uncover Azeroth's ancient truths."},kw={"apothecarium","fintallas","historian","lordaeron","parqual","scholar","test of lore","undercity"},rel={"quest:1152","zone:undercity","subzone:apothecarium","topic:forsaken","topic:lordaeron","zone:thousandneedles"},src={"Parqual Fintallas"}}
E["npc:pilot-longbeard"] = {t="npc",n="Pilot Longbeard",z="thousandneedles",s="Pilot Longbeard is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed in the Hall of Arms within Ironforge's Military Ward. Though posted in the mountain city, he maintains close ties with gnomish tinkerers and fellow flight enthusiasts operating far away in the Shimmering Flats.",h="Pilot Longbeard is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed in the Hall of Arms...",sec={{t="A Pilot of the Siege Brigade",b="Found amongst the martial displays and weaponsmiths of Ironforge's Military Ward, Pilot Longbeard represents the proud siege engine corps of Khaz Modan. While his duties keep him within the fortress city, Longbeard keeps an eager ear out for innovations and news from fellow mechanics across the continent, including the Brassbolts brothers tinkering out on the salt flats of Kalimdor.",sp=0},{t="Connections Across Continents",b="Longbeard serves as a point of contact for adventurous travelers heading south into Kalimdor. He frequently directs promising recruits and couriers toward the Shimmering Flats of Thousand Needles, where gnomish inventors push mechanical boundaries alongside their goblin rivals.",sp=0}},faq={{q="Where can I find Pilot Longbeard?",a="He is located inside the Hall of Arms in the Military Ward of Ironforge, standing near the trainers and military displays.",al={"pilot longbeard location","where is longbeard ironforge","how to find pilot longbeard"},it="place",gp=true},{q="What is Pilot Longbeard's role?",a="Pilot Longbeard is a quest giver who directs Alliance adventurers toward ventures abroad, particularly connecting travelers with his friends, the Brassbolts brothers, out in Thousand Needles.",al={"what does longbeard do","pilot longbeard quest","why talk to longbeard"},it="identity"},{q="Who are the Brassbolts brothers to Longbeard?",a="They are gnomish tinkerers and associates of Longbeard operating in the Shimmering Flats, bound by a shared passion for engineering and experimental machinery.",al={"brassbolts connection","why does longbeard know brassbolts","longbeard shimmering deep"},it="ties"},{q="Is Pilot Longbeard related to Furen Longbeard?",a="They share the prominent Longbeard clan name in Ironforge, suggesting clan kinship, though Pilot Longbeard focuses on siege engines and engineering connections rather than smithing.",al={"furen longbeard brother","longbeard family dwarf","is he related to furen"}},{q="Whose side is Pilot Longbeard on?",a="Pilot Longbeard stands firmly with the Ironforge dwarves and the Alliance. Stationed within the Hall of Arms in Ironforge's Military Ward, he supports dwarf aviation and assists his fellows across the Alliance's far-reaching expeditions.",al={"pilot longbeard faction","is pilot longbeard alliance","longbeard allegiance"},it="side",add=true},{q="What does Pilot Longbeard want?",a="Pilot Longbeard seeks to stay in touch with his distant companions and retrieve valuable navigational assets. He directs travelers to aid his friends, the Brassbolts brothers out in the Shimmering Deep, and seeks to recover lost flight data, such as downed black boxes.",al={"pilot longbeard goal","what does longbeard need","pilot longbeard quests"},it="wants",add=true},{q="Why is Pilot Longbeard here?",a="As an experienced dwarven pilot, Longbeard is stationed at the Hall of Arms within Ironforge's Military Ward to coordinate aerial matters and maintain connections with Alliance aviators and gnomish engineers afield.",al={"why is pilot longbeard in ironforge","longbeard military ward reason","why is longbeard here"},it="why_here",add=true}},ang={["race:Dwarf"]="Pilot Longbeard exemplifies the dwarven adventurous spirit, bridging traditional Ironforge martial service with the excitement of siege engines and gnomish mechanics.",["profession:Engineering"]="As a siege engine pilot with contacts among gnome tinkerers, Longbeard appreciates the mechanical ingenuity required to keep machinery running and racing."},kw={"brassbolts","dwarf aviator","hall of arms","ironforge","military ward","pilot longbeard","shimmering deep","thousand needles"},rel={"zone:ironforge","subzone:military-ward","quest:1179","quest:467","zone:thousandneedles","npc:furen-longbeard","topic:dwarf"},src={"Pilot Longbeard"}}
E["npc:pozzik"] = {t="npc",n="Pozzik",z="thousandneedles",s="Pozzik is an esteemed goblin tinkerer and racer stationed at the Mirage Raceway on the Shimmering Flats in Thousand Needles. Once one of the most respected engineers in Undermine, he now dedicates his technical genius to constructing experimental rocket cars and settling the ultimate debate of engineering supremacy against his gnome counterpart.",h="Pozzik is an esteemed goblin tinkerer and racer stationed at the Mirage Raceway on the Shimmering Flats in...",sec={{t="A Master of Undermine",b="Before retiring to the harsh salt flats of Thousand Needles, Pozzik built a legendary reputation on the Isle of Kezan. As one of the most respected tinkerers out of Undermine, his technical expertise spans complex internal combustion, propulsion, and hazardous chassis construction. Rather than settling into comfortable obscurity, however, Pozzik took his mechanical mastery into the desert to push high-speed machinery far past its breaking point.",sp=0},{t="The Duel on the Salt Flats",b="At the Mirage Raceway, Pozzik teamed up with his perennial gnome counterpart, Fizzle Brassbolts. Despite the historic rivalry between goblin explosives and delicate gnomish calibration, the two worked together to construct the sprawling racetrack across the dried lakebed. They field opposing racing outfits, testing prototype rocket cars to definitively prove whose racial design philosophy dominates the track. Naturally, Pozzik is always on the lookout for resourceful adventurers willing to acquire parts and shave weight off his designs.",sp=0}},faq={{q="Who is Pozzik?",a="Pozzik is a veteran goblin tinkerer formerly from Undermine, now leading one side of the rocket-racing competition at the Mirage Raceway in Thousand Needles.",al={"pozzik","who is pozzik","pozzik lore"},it="identity"},{q="Why is Pozzik out in Thousand Needles?",a="After retiring from formal work in Undermine, Pozzik came to the Shimmering Flats to build and race experimental rocket cars across the vast, uninterrupted salt flats.",al={"why is pozzik here","pozzik shimmering flats"},it="why_here"},{q="What is his relationship with Fizzle Brassbolts?",a="Fizzle Brassbolts is Pozzik's longstanding gnomish rival and racetrack co-founder. Though they work side-by-side maintaining the Mirage Raceway, they constantly compete to prove goblin engineering is superior to gnomish craftsmanship.",al={"pozzik and fizzle","pozzik gnome rival"},it="ties"},{q="Does Pozzik work for the Horde or the Alliance?",a="Pozzik is entirely neutral, working as an independent goblin entrepreneur at the raceway. He is willing to do business and offer tasks to both Alliance and Horde travelers.",al={"is pozzik neutral","pozzik faction"},it="side"},{q="What kind of projects is Pozzik working on right now?",a="Pozzik is obsessed with squeezing more speed out of his rocket cars. He develops multi-engine racing chassis, gathers rare lightweight ores, and sends explorers out for salvaged parts and components.",al={"pozzik quests","what does pozzik build"},it="wants"},{q="Why is Pozzik famous?",a="Before settling in the Shimmering Flats, Pozzik earned a reputation as one of the most respected tinkerers in Undermine. His legendary engineering prowess carried over into his rocket car designs, where he revolutionized the sport by developing powerful two-engine racer models.",al={"pozzik fame","is pozzik famous","why is pozzik well known"},it="fame",add=true}},ang={["profession:Engineering"]="For engineers of either persuasion—goblin or gnomish—Pozzik represents the absolute pinnacle of high-risk, high-velocity applied mechanics.",["race:Gnome"]="Gnomes visiting the track will find in Pozzik their favorite foil: a boisterous goblin engineer convinced that brute thrust outmatches delicate precision."},kw={"fizzle brassbolts","mirage raceway","pozzik","rocket car","shimmering flats","thousand needles","tinker","undermine"},rel={"subzone:mirage-raceway","npc:fizzle-brassbolts","zone:thousandneedles","quest:1176","topic:goblin","zone:tanaris"},src={"Pozzik"}}
E["npc:thalia-amberhide"] = {t="npc",n="Thalia Amberhide",z="thousandneedles",s="Thalia Amberhide is a tauren residing at Freewind Post in the jagged canyon of Thousand Needles. A loyal friend to her kin, she waits with mounting concern for the safe return of Lakota Windsong from the clutches of the Grimtotem clan.",h="Thalia Amberhide is a tauren residing at Freewind Post in the jagged canyon of Thousand Needles.",sec={{t="A Friend at the Post",b="Perched atop the towering bluffs of Freewind Post, Thalia Amberhide is a quiet presence among the bustling tauren settlement. Her heart is heavy with worry for her close companion, Lakota Windsong, who was taken captive by Arnak Grimtotem and his treacherous kin. Thalia relies on passing Horde adventurers who brave the canyon depths to find Lakota, break her bonds, and guide her safely back up the lifts to the haven of the mesa.",sp=0}},faq={{q="Who is Thalia Amberhide?",a="Thalia Amberhide is a tauren living at Freewind Post in Thousand Needles. She is a loyal friend to Lakota Windsong, another tauren who has run afoul of the treacherous Grimtotem clan.",al={"thalia amberhide","who is thalia"},it="identity"},{q="Where can Thalia Amberhide be found?",a="She can be found up on the high mesa of Freewind Post, located in the middle of Thousand Needles. Travelers must take the massive wooden elevators from the canyon floor to reach the settlement.",al={"thalia location","where is thalia amberhide"},it="place",gp=true},{q="What is Thalia's connection to Lakota Windsong?",a="Thalia is a close friend of Lakota Windsong. When Lakota is captured by Arnak Grimtotem, Thalia serves as the welcoming contact at Freewind Post once an adventurer successfully helps Lakota escape her captors.",al={"thalia and lakota","who is lakota windsong"},it="ties"},{q="Whose side is Thalia Amberhide on?",a="Thalia Amberhide is loyal to the Horde and her tauren kin. Residing at Freewind Post in Thousand Needles, she welcomes Horde adventurers traveling across the windswept mesas and stands firm against hostile factions threatening the local tribes.",al={"thalia amberhide faction","is thalia amberhide horde","thalia horde or alliance"},it="side",add=true},{q="Why is Thalia Amberhide here?",a="Thalia makes her home atop Freewind Post, serving as a peaceful resident of the tauren mesa settlement. While she lives quietly among her people, her heart remains troubled by the threats facing her friends in the canyons below.",al={"why is thalia at freewind post","thalia amberhide location why","what brought thalia to thousand needles"},it="why_here",add=true},{q="What does Thalia Amberhide want?",a="Thalia cares deeply about the well-being of her close companion, Lakota Windsong. Her chief concern is the safety of those she holds dear against the predations of aggressive rival clans like the Grimtotem.",al={"what does thalia want","thalia amberhide motive","thalia amberhide goals"},it="wants",add=true}},ang={["race:Tauren"]="For tauren travelers, aiding Thalia and rescuing Lakota strikes directly at the sinister treachery of the Grimtotem tribe, defending their fellow kin against clan discord.",["faction:Horde"]="Freewind Post is a crucial Horde waypoint in Thousand Needles, and helping Thalia Amberhide safeguards the settlement against Grimtotem aggression."},kw={"arnak grimtotem","freewind post","grimtotem","lakota windsong","thalia amberhide","thousand needles"},rel={"npc:lakota-windsong","subzone:freewind-post","zone:thousandneedles","quest:4904","topic:tauren","topic:horde"},src={"Thalia Amberhide"}}
E["npc:wizlo-bearingshiner"] = {t="npc",n="Wizlo Bearingshiner",z="thousandneedles",s="Wizlo Bearingshiner is a goblin tinkerer stranded at Whitereach Post in Thousand Needles. The sole survivor of a centaur attack on his caravan, he recruits travelers to recover a valuable Hypercapacitor Gizmo from the wreckage.",h="Wizlo Bearingshiner is a goblin tinkerer stranded at Whitereach Post in Thousand Needles.",sec={{t="An Engineer at the Post",b="Staying alongside the tauren at Whitereach Post along the canyon road, Wizlo Bearingshiner faces an unwelcome delay. Centaur attacked his caravan, leaving him as its only survivor. His clients are waiting for their wares, and he worries that he will not deliver them in time.",sp=0},{t="A Stranded Shipment",b="Wizlo's best gizmo hangs around the neck of a fierce panther caged beside his ruined caravan north of Whitereach Post. Even the centaur avoid the beast. Wizlo offers travelers the cage key and a reward for recovering the hypercapacitor, though he admits he has yet to work out what the device actually does.",sp=0}},faq={{q="Who is Wizlo Bearingshiner?",a="Wizlo Bearingshiner is a goblin tinkerer stranded at Whitereach Post in Thousand Needles after centaur attacked his caravan. He seeks help recovering a Hypercapacitor Gizmo from a caged panther.",al={"wizlo bearingshiner","who is wizlo","whitereach goblin"},it="identity"},{q="Where can I find Wizlo Bearingshiner?",a="He is located at Whitereach Post, a Horde camp along the road near Camp E'thok in Thousand Needles.",al={"wizlo location","where is wizlo","find wizlo"},it="place",gp=true},{q="What kind of experiments does he run?",a="Wizlo is trying to recover his Hypercapacitor Gizmo. He admits that he still needs to figure out what it does; the device's exact function is unknown.",al={"wizlo quests","what does wizlo do","wizlo gadgets"}},{q="Why is a goblin working with the Horde at Whitereach Post?",a="Whitereach Post is an unintended stop for Wizlo. Centaur attacked his caravan nearby, and he is stranded while his clients await their shipments.",al={"why is wizlo here","is wizlo horde","goblin at whitereach"},it="side"},{q="Does Wizlo belong to the Steamwheedle Cartel?",a="No Steamwheedle affiliation is established for Wizlo. He is stationed with the Horde at Whitereach Post and is concerned with recovering his goods and delivering them to his clients.",al={"wizlo faction","steamwheedle wizlo","wizlo cartel"},it="ties"},{q="What is the Hypercapacitor Gizmo?",a="The Hypercapacitor Gizmo is a valuable device carried by a caged panther beside Wizlo's wrecked caravan. Its exact purpose is unknown—even Wizlo says he has yet to figure out what it does.",al={"hypercapacitor gizmo","wizlo device","gizmo quest"},it="item"},{q="What does Wizlo Bearingshiner want?",a="Wizlo wants his Hypercapacitor Gizmo recovered from the panther guarding his wrecked caravan north of Whitereach Post. Centaur attacked the caravan, leaving him stranded while his clients wait for their goods.",al={"what does wizlo want","wizlo bearingshiner goal","wizlo experiments"},it="wants",add=true},{q="Why is Wizlo Bearingshiner here in Thousand Needles?",a="Whitereach Post is an unintended stop after centaur attacked Wizlo's caravan nearby. He is the only survivor and is anxious about the deliveries his clients are expecting.",al={"why is wizlo here","why is wizlo in thousand needles","wizlo whitereach post why"},it="why_here",add=true}},ang={["profession:Engineering"]="Engineers may sympathize with Wizlo's desire to recover the mysterious Hypercapacitor Gizmo and discover what it does.",["faction:Horde"]="While making camp at Whitereach Post alongside the local Tauren, Horde travelers can easily employ Wizlo's mechanical expertise to secure useful gadgets."},kw={"goblin engineer","hypercapacitor gizmo","thousand needles","whitereach post","wizlo bearingshiner"},rel={"subzone:whitereach-post","zone:thousandneedles","quest:5151","topic:goblin"},src={"Wizlo Bearingshiner"}}
E["npc:wizzle-brassbolts"] = {t="npc",n="Wizzle Brassbolts",z="thousandneedles",s="Wizzle Brassbolts is a gnome engineer stationed alongside his fellow tinkerers out on the salt flats of Thousand Needles. Working with the gnomish racing team at the Mirage Raceway, he seeks durable local materials to reinforce their experimental rocket cars.",h="Wizzle Brassbolts is a gnome engineer stationed alongside his fellow tinkerers out on the salt flats of...",sec={{t="Tinkering on the Salt Flats",b="Out in the shimmering heat of the Shimmering Flats, the rivalry between gnomish and goblin engineering takes the form of high-speed rocket car races. Wizzle Brassbolts works as part of the gnomish raceway crew, striving to keep their vehicles intact against blistering speeds and abrasive salt. To bolster their machines, he recruits adventurers to hunt the local wildlife—such as the sturdy turtles wandering the basin—harvesting their hard shells to build new fuel tanks strong enough to hold his brother's corrosive new rocket fuel.",sp=0},{t="Friends in Distant Places",b="Wizzle maintains close ties with friends across the continents, including Pilot Longbeard, who sends couriers out with racing helmets for the brothers. With help like that, Wizzle keeps the gnomish team supplied despite their remote, inhospitable testing ground on the Shimmering Flats.",sp=0}},faq={{q="Where can I find Wizzle Brassbolts?",a="Wizzle Brassbolts is located at the Mirage Raceway on the Shimmering Flats, in the southeastern reaches of Thousand Needles. He stands among the gnomish pit crew and their machinery.",al={"wizzle location","where is wizzle brassbolts","wizzle brassbolts map"},it="place",gp=true},{q="Why is Wizzle collecting turtle shells?",a="His brother is designing a new rocket fuel so strong it could eat right through the car's chassis. Wizzle uses the rock-hard shells of the tortoises on the Shimmering Flats to build new fuel tanks that can hold it.",al={"hardened shells quest","why does wizzle want shells","turtle shells raceway"},it="motive"},{q="Who are the Brassbolts brothers?",a="The Brassbolts brothers are Wizzle and his brothers Fizzle and Rizzle, gnomish tinkerers who run the gnome rocket car team at the Mirage Raceway, racing against the goblins. Pilot Longbeard is a friend of theirs.",al={"brassbolts family","the brassbolts brothers","wizzle brothers"},it="ties"},{q="Is Wizzle friendly to Horde players?",a="Yes. The Mirage Raceway is neutral ground, and Wizzle's own tasks, such as gathering hardened tortoise shells, are open to Horde and Alliance adventurers alike.",al={"can horde talk to wizzle","wizzle brassbolts horde"},it="side"},{q="Who is Wizzle Brassbolts?",a="Wizzle Brassbolts is an intrepid gnomish engineer stationed out on the shimmering flats of the Shimmering Flats in Thousand Needles. Alongside his kin, he works diligently on cutting-edge engineering projects and mechanical innovations, representing the ingenuity of Gnomeregan amid the relentless heat of the salt flats.",al={"who is wizzle","wizzle brassbolts lore","who is wizzle brassbolts"},it="identity",add=true},{q="What does Wizzle Brassbolts want?",a="Wizzle seeks rare and durable materials from across the region to reinforce and perfect his engineering creations. Whether it is gathering hardened turtle shells or procuring formidable beast parts like tail fins, he relies on adventurous travelers to bring him the exotic components needed for his mechanical tests.",al={"what does wizzle want","wizzle brassbolts goal","wizzle brassbolts quest"},it="wants",add=true},{q="Why is Wizzle Brassbolts here?",a="Wizzle is stationed at the Mirage Raceway on the Shimmering Flats to support gnomish engineering efforts and the ongoing vehicle races against their goblin rivals. The vast, flat salt basin offers the perfect testing ground for high-speed machinery and experimental contraptions.",al={"why is wizzle here","why is wizzle at mirage raceway","wizzle thousand needles why"},it="why_here",add=true}},ang={["profession:Engineering"]="Wizzle exemplifies the gnomish engineering philosophy: pushing high-velocity machines to their limits and relying on unusual structural reinforcements when metal sheets fail.",["race:Gnome"]="Gnomes visiting the Shimmering Flats will find in Wizzle a kindred spirit, stubbornly determined to defeat the reckless contraptions of the Steamwheedle goblins using superior craft."},kw={"brassbolts","mirage raceway","pilot longbeard","rocket car","shimmering flats","thousand needles","wizzle"},rel={"subzone:mirage-raceway","quest:1105","quest:1179","npc:pilot-longbeard","zone:thousandneedles","topic:gnome","topic:alliance"},src={"Wizzle Brassbolts"}}
E["quest:1100"] = {t="quest",n="Lonebrow's Journal",z="thousandneedles",s="Lonebrow's Journal is an Alliance quest initiated by finding a weathered book held in the hand of a dead dwarf at the base of the Great Lift in Thousand Needles. The notes detail his final journey and prompt the finder to deliver the volume west to a night elf druid stationed on the Feralas border.",h="Lonebrow's Journal is an Alliance quest initiated by finding a weathered book held in the hand of a dead...",sec={{t="A Fallen Explorer",b="Near the base of the Great Lift, the massive mechanical elevator connecting the Barrens to the canyon floor of Thousand Needles, lies the body of Henrig Lonebrow. Clutched in his hand is a personal journal detailing his travels through this rugged territory. Left behind in a hostile desert dominated by centaur and tauren, his corpse serves as a grim warning of how unforgiving the canyon can be to isolated travelers.",sp=0},{t="A Dying Request",b="Reading through Henrig's journal reveals his intended path and final wish. Rather than leaving his findings to decay in the canyon, the explorer hoped his records would reach friendly hands. Following the road straight west across Thousand Needles leads out of the dry gullies and toward Thalanaar, the night elf outpost guarding the border to Feralas, where the druid Falfindel Waywarder awaits news of the traveler.",sp=0},{t="Uncovering the Kraul",b="When Falfindel Waywarder reviews Lonebrow's notes, the explorer's fate becomes intertwined with a larger menace in Southern Kalimdor. Henrig's observations point toward the bramble-choked warrens of Razorfen Kraul back to the north, revealing that a dangerous crone leads the quilboar dwelling inside.",sp=1}},faq={{q="Where do I find Henrig Lonebrow's body?",a="His body lies at the foot of the Great Lift in Thousand Needles. From the bottom of the western elevator ramp, head roughly twenty-five feet forward toward a low rock ledge, where his corpse rests with the journal in hand.",al={"henrig lonebrow location","where is lonebrow journal","lonebrow body","find lonebrow"},it="place",gp=true},{q="Who do I deliver the journal to?",a="Deliver the journal to Falfindel Waywarder, a night elf druid stationed at Thalanaar. Thalanaar is situated along the main westward road right on the border between Thousand Needles and Feralas.",al={"who gets lonebrow journal","where to turn in lonebrow","lonebrow turn in","falfindel location"},it="next_step",gp=true},{q="Who was Henrig Lonebrow?",a="Henrig Lonebrow was a dwarven traveler venturing through central Kalimdor. He perished near the base of the Great Lift, leaving behind a weathered journal detailing his observations of the surrounding lands and dangerous quilboar movements.",al={"who is henrig lonebrow","lonebrow backstory","who is lonebrow"},it="identity"},{q="What does this quest lead to?",a="Turning in the journal to Falfindel Waywarder unlocks the quest 'The Crone of the Kraul', which directs Alliance adventurers to venture into the Razorfen Kraul dungeon.",al={"lonebrow follow up","quest after lonebrow journal","lonebrow quest chain"},sp=1,it="next_step"},{q="Can Horde players pick up the journal?",a="No. The journal and its subsequent quest chain are strictly for Alliance players, leading directly to the Alliance border post at Thalanaar.",al={"is lonebrow journal alliance only","can horde do lonebrow journal","horde lonebrow"},it="side",gp=true},{q="Why was Lonebrow heading toward Thalanaar?",a="Thalanaar is the nearest Alliance outpost in the region, serving as a sanctuary between Thousand Needles and the wilds of Feralas. Lonebrow intended to share his regional observations with the night elves stationed there.",al={"why thalanaar","why send book to druid","lonebrow purpose"},it="motive"},{q="Why does the journal ask to be taken to Thalanaar?",a="Henrig Lonebrow knew his journey was ending in tragedy beneath the Great Lift. His final wish recorded in the weathered pages was for his findings to reach Falfindel Waywarder at the border post of Thalanaar. By seeing the journal delivered, you ensure that whatever critical intelligence or discoveries cost the dwarf his life are not lost to the sands of Thousand Needles.",al={"why deliver journal","journal purpose","henrig lonebrow journal motive"},it="purpose",add=true}},ang={["race:Dwarf"]="Henrig Lonebrow's demise serves as a somber reminder of the dangers dwarven explorers face far from Ironforge in the wild corners of Kalimdor.",["faction:Alliance"]="With few outposts between Theramore and Thalanaar, recovering Lonebrow's journal ensures vital intelligence reaches Alliance allies before it is lost to the canyon.",["class:Druid"]="Falfindel Waywarder in Thalanaar monitors unnatural shifts in the local ecosystem, making Lonebrow's notes regarding the quilboar in Razorfen of direct interest to the Cenarion Circle."},kw={"falfindel","feralas","great lift","henrig","journal","lonebrow","razorfen kraul","thalanaar","thousand needles","waywarder"},rel={"quest:1101","npc:falfindel-waywarder","subzone:great-lift","subzone:thalanaar","zone:thousandneedles","zone:razorfenkraul","zone:feralas","topic:dwarf"},m={start="Henrig Lonebrow's Journal",["end"]="Falfindel Waywarder",level="27",faction="Alliance",id=1100},src={"Lonebrow's Journal (quest)"}}
E["quest:1104"] = {t="quest",n="Salt Flat Venom",z="thousandneedles",s="Out on the blinding salt expanse of the Shimmering Flats, gnome engineer Fizzle Brassbolts searches for unusual ingredients to supercharge his rocket car. Convinced that the intensely saline venom of local scorpids will produce an ultra-hot burning propellant, he tasks passing adventurers with braving the stinging beasts.",h="Out on the blinding salt expanse of the Shimmering Flats, gnome engineer Fizzle Brassbolts searches for...",sec={{t="A Volatile Recipe",b="The Mirage Raceway is an endless battle of high-speed technical supremacy between gnomish precision and goblin audacity. For Fizzle Brassbolts, standard hydrocarbons and clockwork parts simply are not enough to outpace the competition. He envisions a custom fuel mixture tailored to burn far hotter than conventional propellants, driving their rocket cars across the dried salt lake at blistering speeds.",sp=0},{t="Saline Venom of the Salt Flats",b="Fizzle's breakthrough relies on the dangerous native fauna of the Shimmering Flats. The local scorpids have evolved to survive in an arid, salt-encrusted wasteland, resulting in an exceptionally saline venom. Rather than fearing its deadly toxicity, Fizzle sees it as a raw chemical payload. Once boiled, refined, and treated with exotic catalytic agents, he believes the salty venom will deliver the explosive combustion required to leave the goblin pit crews in the dust.",sp=0}},faq={{q="Why does Fizzle Brassbolts want scorpid venom?",a="Fizzle is inventing a new rocket car fuel that burns extremely hot. He believes the unusually high salt content found in the venom of native Shimmering Flats scorpids is the vital chemical component needed to complete his explosive mixture.",al={"why scorpid venom","what is venom for","fizzle fuel recipe"},it="motive"},{q="Where can the necessary scorpids be found?",a="Scorpids wander all across the open expanses of the Shimmering Flats, particularly prowling the western flats and the desert sands away from the central racetrack.",al={"scorpid location","where are scorpids","salt flat venom mobs"},it="place",gp=true},{q="What will Fizzle do with the venom once collected?",a="Fizzle intends to boil down the venom, treat it with a skipper-otomer, and blend it with a nega-catalyst to produce his high-octane rocket propellant—assuming he can find where he misplaced his notes.",al={"how is venom turned to fuel","fuel process"},it="item"},{q="Can members of both the Alliance and Horde help Fizzle?",a="Yes. The Mirage Raceway is managed under a neutral truce between the gnomes and goblins, allowing adventurers of either faction to assist the pit crews without political interference.",al={"is this quest neutral","horde or alliance"},it="side",gp=true},{q="Why are gnomes and goblins racing in Thousand Needles?",a="The Shimmering Flats provide a vast, perfectly flat, and unobstructed bed of hard-packed salt, making it the ideal proving ground for experimental, high-speed rocket cars and dragsters.",al={"why raceway here","why mirage raceway"},it="conflict"},{q="Does the fuel actually make the car fly?",a="While Fizzle enthusiastically claims the car will 'fly,' gnomish rocket vehicles on the salt flats are designed to skim the ground at breakneck speeds, though catastrophic liftoffs and crashes are never out of the question.",al={"does car fly","fizzle rocket car result"},it="power"}},ang={["race:Gnome"]="Fizzle represents classic gnomish ambition: relentless tinkering, questionable chemical safety, misplaced notes, and the constant urge to outshine goblin mechanics.",["profession:Engineering"]="Using organic toxins treated with catalysts like skipper-otomers highlights the creative and volatile experiments common in competitive vehicle engineering."},kw={"fizzle brassbolts","fuel","mirage raceway","rocket car","salty scorpid venom","shimmering flats","thousand needles"},rel={"npc:fizzle-brassbolts","subzone:mirage-raceway","subzone:shimmering-flats","zone:thousandneedles","topic:gnome"},m={start="Fizzle Brassbolts",level="30",id=1104,ri={"Salty Scorpid Venom"}},src={"Salt Flat Venom"}}
E["quest:1105"] = {t="quest",n="Hardened Shells",z="thousandneedles",s="At the Mirage Raceway in the Shimmering Flats, the gnome tinkerer Wizzle Brassbolts worries his brother's potent new rocket fuel will dissolve their racer from the inside out. To prevent a catastrophe on the salt flats, Wizzle enlists passersby to harvest hardened shells from the local tortoises to craft an impervious fuel tank.",h="At the Mirage Raceway in the Shimmering Flats, the gnome tinkerer Wizzle Brassbolts worries his brother's...",sec={{t="Volatile Innovations",b="Out in the blinding heat of the Shimmering Flats, the rivalry between gnome and goblin engineers pushes mechanical ambition to reckless extremes. Wizzle Brassbolts and his brother are determined to dominate the Mirage Raceway with their custom rocket car. However, his brother's experimental fuel mixture is showing signs of being far too potent. Fearing that the corrosive concoction will melt straight through the vehicle's standard chassis and tanks, Wizzle scrambles to find a container tough enough to survive the run.",sp=0},{t="Desert Armored Solutions",b="Rather than relying on refined metals that might dissolve under chemical strain, Wizzle turns to the natural adaptations of the salt flats. The native tortoises roaming Thousand Needles possess shells remarkably resistant to harsh elements and mechanical wear. By gathering these hardened carapaces, Wizzle hopes to fashion custom fuel tanks resilient enough to hold the volatile mixture without blowing the rocket car to pieces.",sp=0}},faq={{q="Why does Wizzle need tortoise shells instead of metal?",a="His brother is brewing an experimental rocket fuel that is corrosive enough to dissolve metal. Wizzle believes the natural, ultra-hard shells of the local tortoises will withstand the chemical wear better than standard tanks.",al={"why turtle shells","why tortoise shells","fuel tank shell"},it="item"},{q="Who is Wizzle Brassbolts?",a="Wizzle is a gnome engineer stationed at the Mirage Raceway in the Shimmering Flats. He works alongside his brother to build and fine-tune their high-speed rocket car to outrace their goblin competitors.",al={"wizzle","who is wizzle"},it="identity"},{q="Where can the tortoises be found?",a="The tortoises wander openly across the vast salt pan of the Shimmering Flats, with particularly dense gatherings basking near the old shipwreck in the northeastern section.",al={"tortoise location","where are the turtles","where to get hardened shells"},it="place",gp=true},{q="Is this an Alliance or Horde quest?",a="It is completely neutral. The Mirage Raceway operates outside faction warfare, focusing on engineering competitions, allowing both Alliance and Horde adventurers to assist Wizzle.",al={"is hardened shells neutral","alliance or horde"},it="side",gp=true},{q="What happens once the shells are delivered?",a="Wizzle eagerly begins fabricating them into reinforced fuel tanks, though he quickly realizes the shells are so durable he will likely ruin an entire toolbox carving them into shape.",al={"wizzle shell result","what does wizzle do with shells"},sp=1,it="next_step"},{q="Why is fuel tank failure such a concern on the flats?",a="Rocket cars travel at terrifying speeds across the salt. A tank failure caused by acidic fuel would ignite mid-run, destroying the vehicle and incinerating the pilot.",al={"rocket car danger","why worried about fuel"}},{q="Why does Wizzle Brassbolts want this done?",a="Wizzle's brother is designing an extremely volatile new fuel for their rocket car on the Mirage Raceway. While Wizzle admires his brother's brilliance, he is terrified that the concoction is corrosive enough to melt straight through the car's existing chassis during testing. To prevent a catastrophic disaster on the salt flats, Wizzle needs to craft sturdier replacement fuel tanks before his brother finishes the mixture.",al={"wizzle motive","why help wizzle","why does wizzle want shells"},it="motive",add=true},{q="What are the tortoises of the Shimmering Flats?",a="Saltstone tortoises wander the sun-baked expanses of the Shimmering Flats. Over generations in the harsh, arid basin, their carapaces have hardened into remarkably tough, resilient shells. They generally keep to themselves amidst the salt crust, making them an ideal, durable natural material for gnomish tinkerers in dire need of non-reactive, heat-resistant plating.",al={"salt flat tortoises","shimmering flats turtles","why are there tortoises here"},it="target",add=true}},ang={["profession:Engineering"]="Using organic armor plates to house volatile compounds is unorthodox, highlighting the eccentric trial-and-error approach gnomish tinkerers rely on under pressure.",["race:Gnome"]="Brotherly ingenuity and reckless scientific ambition meet head-on here, capturing the gnomish drive to out-innovate goblin rivals no matter the logistical hurdle."},kw={"hardened shells","mirage raceway","rocket car","shimmering flats","thousand needles","tortoise","wizzle brassbolts"},rel={"npc:wizzle-brassbolts","subzone:mirage-raceway","subzone:shimmering-flats","zone:thousandneedles","topic:gnome"},m={start="Wizzle Brassbolts",level="30",id=1105,ri={"Hardened Tortoise Shell"}},src={"Hardened Shells"}}
E["quest:1110"] = {t="quest",n="Rocket Car Parts",z="thousandneedles",s="Rocket Car Parts is an errand undertaken for the opportunistic dwarf merchant Kravel Koalbeard on the blinding salt pans of the Shimmering Flats. Rather than letting the violently scattered debris of high-speed racer crashes go to waste, Koalbeard pays wanderers to comb the desert floor and recover wrecked mechanisms to resell directly to the rival gnome and goblin pit crews.",h="Rocket Car Parts is an errand undertaken for the opportunistic dwarf merchant Kravel Koalbeard on the...",sec={{t="Debris on the Salt Flats",b="The Shimmering Flats serve as the proving ground for the fierce technological rivalry between goblin and gnomish engineers. High-velocity experimental rocket cars routinely suffer catastrophic malfunctions, leaving twisted gears, cylinders, and jagged sheets of metal scattered wide across the vast white desert. While the pit crews focus solely on building and tuning the next machine, the desert floor has quietly become a scrap yard of experimental engineering.",sp=0},{t="Koalbeard's Salvage Enterprise",b="Rather than competing directly on the track, the dwarf entrepreneur Kravel Koalbeard recognized a lucrative middleman opportunity at the Mirage Raceway. Gnome and goblin mechanics burn through parts at a furious pace and are constantly desperate for spare mechanisms to slap onto their vehicles. Koalbeard hires travelers to gather thirty bundles of shattered debris, turning devastating crashes into fresh inventory and neatly profiting off the drivers' misfortunes.",sp=0}},faq={{q="Who is Kravel Koalbeard?",a="Kravel Koalbeard is a shrewd dwarf merchant stationed at the Mirage Raceway in the Shimmering Flats. He runs various entrepreneurial schemes around the track, primarily focusing on scavenging, odd jobs, and turning the rivalries of gnomes and goblins into personal profit.",al={"kravel koalbeard","who gives rocket car parts","raceway dwarf"},it="identity"},{q="Why are there so many rocket car parts scattered on the ground?",a="The Mirage Raceway is an active testing and racing track where goblin and gnomish engineers push experimental rocket vehicles to dangerous limits. Violent wrecks and sudden explosions happen regularly across the salt pans, throwing structural fragments, gears, and cylinders across the expanse.",al={"why are there car parts in the desert","shimmering flats debris","broken rocket cars"},it="origin"},{q="What does Kravel do with the wrecked parts?",a="Koalbeard cleans up the collected scrap and pawns it straight back to the gnomish and goblin race teams. The crews constantly burn through materials and are eager to buy back whatever contraptions and metal scraps they can bolt onto their next prototypes.",al={"what does kravel want with parts","why collect car parts"},it="motive"},{q="Where are these parts located?",a="The parts lie scattered throughout the open desert floor across the Shimmering Flats, surrounding the central racing camp. They appear as discarded mechanical scrap heaps, twisted gears, cylinders, and flattened metal plates.",al={"where to find rocket car parts","parts locations","car parts shimmering flats"},it="place",gp=true},{q="Does this quest tie into other tasks around the raceway?",a="Yes. Scavenging the flats pairs naturally with culling local wildlife for other raceway patrons, such as gathering venom from scorpid stingers, harvesting turtle shells, and thinning out the local buzzards and basilisks while traversing the wide salt pans.",al={"raceway quests","shimmering flats hunting quests","quests to do with rocket car parts"},gp=true},{q="What happens to the drivers involved in these wrecks?",a="Rocket car racing is notoriously lethal. When sorting through the salvaged scrap, Koalbeard casually notices a severed ear crushed between metal plates, highlighting the grim reality that many pilots do not walk away from high-speed test runs.",al={"do drivers survive crashes","squashed ear","pilot deaths raceway"}},{q="What are the rocket car parts used for?",a="They are twisted salvage—gears, cylinders, and scrap metal thrown from high-speed collisions across the salt flats. Rather than letting them rust in the brine, Kravel Koalbeard gathers them to resell straight back to the frantic gnome and goblin pit crews. Desperate to rebuild their shattered racers and out-tinker their rivals, both sides will gladly buy back scavenged metal to weld onto their next reckless contraption.",al={"rocket car parts use","what are rocket car parts for","why collect rocket car parts"},it="item",add=true}},ang={["profession:Engineering"]="Combing the salt flats reveals the reckless ingenuity of rival goblin and gnomish designs, where unstable rocket boosters and improvised chassis frequently end in spectacular structural failures.",["race:Dwarf"]="While many Ironforge dwarves look to the raceway for mechanical innovation or excavation, Kravel Koalbeard embodies a thoroughly mercenary streak, interested strictly in the coin salvage operations bring.",["race:Gnome"]="Recovering these parts highlights the relentless, if occasionally disastrous, drive of gnomish engineers attempting to outpace and out-innovate their goblin competitors on the open track."},kw={"crashes","gnome","goblin","kravel koalbeard","mirage raceway","rocket car parts","salvage","scrap","shimmering flats","thousand needles"},rel={"subzone:mirage-raceway","subzone:shimmering-flats","npc:kravel-koalbeard","zone:thousandneedles","quest:1104","quest:1105","quest:1176","topic:goblin"},m={level="31",id=1110,ri={"Rocket Car Parts"}},src={"Rocket Car Parts (quest)"}}
E["quest:1149"] = {t="quest",n="Test of Faith",z="thousandneedles",s="The Test of Faith is a spiritual rite administered by the hermit Dorn Plainstalker high above the canyon floor of Thousand Needles. It challenges Horde adventurers to prove their resolve by stepping off a precarious wooden plank into the open chasm below.",h="The Test of Faith is a spiritual rite administered by the hermit Dorn Plainstalker high above the canyon...",sec={{t="A Measure of the Spirit",b="Dorn Plainstalker dwells in a secluded vantage overlooking the wind-carved spires of Thousand Needles, pondering the facets that make up a living being: the mind, the body, and the spirit. Rather than relying on simple tribal traditions, Dorn administers his own trials to measure what truly lies within an adventurer. He posits that while conviction can take many forms, the essential quality is simply having the fortitude to believe in something strongly enough to risk one's life on it.",sp=0},{t="The Leap into the Void",b="The trial is deceptively direct. Transported to the sheer summit of one of the towering stone needles, the supplicant stands atop weathered wooden planks suspended over empty air. To pass, one must conquer self-preservation and step off into the abyss without any tangible guarantee of survival. Those who jump find their descent broken by arcane or spiritual forces and are whisked back to safety, having demonstrated that their spirit is tempered enough to face unforeseen trials ahead.",sp=1}},faq={{q="Who is Dorn Plainstalker?",a="Dorn Plainstalker is a tauren hermit residing in a remote cliffside camp above Thousand Needles. He serves as a spiritual proctor, seeking out adventurers of the Horde to test the various aspects of their mortal makeup: faith, endurance, and strength.",al={"dorn plainstalker lore","who gives test of faith","quest giver thousand needles"},it="identity"},{q="Will jumping off the plank kill me?",a="No. While the drop off the needle spire looks entirely fatal, the trial functions as an act of trust. Once you step off the wooden planks, magical warding catches you mid-fall and teleports you directly back to Dorn Plainstalker's cave unscathed.",al={"do i die jumping","will fall damage kill me test of faith","is test of faith dangerous"},sp=1,gp=true},{q="What happens after passing the Test of Faith?",a="Proving your faith is merely the opening rite in Dorn's series of trials. Once your spirit is deemed receptive, Dorn immediately challenges your physical resilience in the Test of Endurance.",al={"what comes after test of faith","test of faith chain","dorn plainstalker next quest"},sp=1,it="next_step"},{q="Why does Dorn say failure means realizing the vastness of the Nether?",a="It is Dorn's grim philosophical reminder of mortality. In his eyes, those who lack the inner fire to commit fully to the challenge risk losing their lives—and their souls—to the endless void beyond the living world.",al={"vastness of the nether meaning","dorn plainstalker nether quote"}},{q="Can Alliance adventurers take this test?",a="No. Dorn Plainstalker only extends his wisdom and spiritual guidance to champions aligned with the Horde traversing the dangerous canyons of southern Kalimdor.",al={"is test of faith horde only","can alliance do test of faith"},it="side",gp=true},{q="Where does the Test of Faith take place?",a="The trial begins at Dorn's camp in the Thousand Needles canyon walls, which magically connects to the dizzying precipice of an isolated stone spire jutting out over the gorge floor.",al={"test of faith location","where is the plank thousand needles"},it="place",gp=true},{q="Why does Dorn Plainstalker test your faith?",a="Dorn Plainstalker believes every being is shaped by the spirit, the body, and the mind. While some qualities are shaped by cultural tradition, others can only be discovered deep within yourself. By offering these trials, Dorn aims to measure your inner strength and prepare your spirit for hardship. He demands a blind leap into the canyon winds to prove that you possess belief and trust without guarantee of survival, ensuring your mind is open to the greater challenges ahead.",al={"why does dorn want this done","dorn plainstalker motive","why leap of faith test"},it="motive",add=true}},ang={["race:Tauren"]="For the Shu'halo, undergoing rites of passage across Kalimdor's sacred geography is an ancient tradition, and Dorn's trial demands a visceral display of trust in the unseen.",["class:Priest"]="Priests who spend their days cultivating faith in higher powers find themselves challenged to put their theoretical convictions into literal physical motion.",["faction:Horde"]="The trials reflect the core values binding the fledgling Horde together in Kalimdor: absolute conviction, resilience against hostile environments, and unyielding will."},kw={"dorn plainstalker","horde","leap of faith","planks","test of endurance","test of faith","thousand needles"},rel={"npc:dorn-plainstalker","quest:1150","zone:thousandneedles","topic:horde"},m={start="Dorn Plainstalker",level="26",faction="Horde",id=1149},src={"Test of Faith (quest)"}}
E["quest:1150"] = {t="quest",n="Test of Endurance",z="thousandneedles",s="The Test of Endurance is the second rite in a series of spiritual trials overseen by Dorn Plainstalker in Thousand Needles. Having already proven their courage of spirit, Horde adventurers are tasked with pushing their physical endurance to the limit by infiltrating Roguefeather Den and drawing out the fierce harpy leader, Grenka Bloodscreech.",h="The Test of Endurance is the second rite in a series of spiritual trials overseen by Dorn Plainstalker in...",sec={{t="Testing the Body",b="Dorn Plainstalker, dwelling at the Weathered Nook, takes it upon himself to temper young warriors before they venture into the wider, harsher world. Where the initial rite proved that a traveler possessed unshakable faith and steady nerve, this trial tests physical fortitude. In Dorn's philosophy, true readiness requires harmony between spiritual devotion, mental discipline, and the sheer stamina to survive sustained brutality.",sp=0},{t="Incursion into Roguefeather Den",b="The chosen arena for this trial is Roguefeather Den, a treacherous cavern tucked within Screeching Canyon west of Freewind Post. Swarming with hostile harpies, the cave poses severe danger to solitary wanderers. To complete the trial, challengers must carve their way deep into the subterranean roost, sabotage the harpies' gathered provisions, and weather the flock's ferocious retaliation until the matriarch Grenka Bloodscreech herself takes the field.",sp=0}},faq={{q="Who gives the Test of Endurance?",a="The quest is offered by Dorn Plainstalker, an elder tauren stationed at the Weathered Nook in the canyon bluffs of Thousand Needles.",al={"quest giver test of endurance","who starts test of endurance","dorn plainstalker quest"},gp=true},{q="Where is Roguefeather Den located?",a="Roguefeather Den lies high along the southern canyon walls of Thousand Needles, west of Freewind Post. Travelers must ascend a winding path through Screeching Canyon to reach the ramp up to the cave entrance.",al={"roguefeather den location","where is harpy cave","screeching canyon ramp"},gp=true},{q="How do you summon Grenka Bloodscreech?",a="Grenka Bloodscreech appears after you fight your way to the deepest chambers of Roguefeather Den and vandalize the cache of food and supplies stored there by the harpies, provoking her into defending her roost.",al={"summon grenka","how to spawn grenka bloodscreech","find grenka"},gp=true},{q="What comes after the Test of Endurance?",a="Returning Grenka's severed claw to Dorn Plainstalker proves your physical stamina, prompting him to send you on the next challenge in his sequence: the Test of Strength.",al={"next quest after endurance","what follows test of endurance","dorn plainstalker next test"},it="next_step"},{q="Why does Dorn test adventurers who aren't tauren?",a="Dorn believes it is his calling to mentor all youth of the Horde, regardless of race or tribe. He views untested pride as a death sentence in the wider world, insisting that every warrior demonstrate readiness across body, mind, and spirit.",al={"why does dorn help horde","dorn plainstalker philosophy","tauren trials for other races"},it="why_me"},{q="What was the trial before this one?",a="Before testing the body's endurance, Dorn requires challengers to undertake the Test of Faith, a perilous leap of devotion that tests whether an adventurer's spirit will falter in the face of fear.",al={"previous quest","test before endurance","first trial"}},{q="Why does Dorn Plainstalker want this done?",a="Dorn Plainstalker sees it as his sacred obligation to prepare young adventurers for the deadly perils of the wider world. After ensuring your spirit and faith were intact, he insists on testing your physical body. By forcing you to weather wave after wave of furious harpies deep inside their own territory, he ensures you possess the stamina and resolve required to survive beyond the safety of home.",al={"why dorn test endurance","dorn plainstalker motive","purpose of test of endurance"},it="motive",add=true},{q="What is Grenka's Claw for?",a="The claw serves as undeniable proof that you stood your ground in the heart of Roguefeather Den, survived the harpies' sustained onslaught, and struck down their fierce matriarch, Grenka Bloodscreech. Dorn requires it to confirm that your endurance held up under relentless assault before he will present your next trial.",al={"grenkas claw use","why do i need grenkas claw","grenka claw purpose"},it="item",add=true},{q="Who is Grenka Bloodscreech?",a="Grenka Bloodscreech is a formidable leader among the Roguefeather harpies infesting the canyon caverns west of Freewind Post. Vicious and highly territorial, she rules the flock's inner sanctuary. When you storm deep into Roguefeather Den and smash their hoarded provisions, her fury draws her down from the roost to slay you herself.",al={"who is grenka","grenka bloodscreech lore","roguefeather harpy leader"},it="target",add=true}},ang={["race:Tauren"]="For tauren travelers, Dorn Plainstalker's trials reflect traditional rites of passage, testing whether an initiate's physical stamina matches the spiritual guidance of the Earth Mother.",["faction:Horde"]="Dorn offers these challenges to all Horde races, believing that young warriors from every tribe must be tempered against hardship before facing the perils of Kalimdor."},kw={"dorn plainstalker","freewind post","grenka bloodscreech","roguefeather den","screeching canyon","test of endurance","thousand needles","weathered nook"},rel={"npc:dorn-plainstalker","quest:1149","quest:1151","subzone:roguefeather-den","subzone:weathered-nook","subzone:freewind-post","zone:thousandneedles","topic:harpy"},m={start="Dorn Plainstalker",level="29",faction="Horde",id=1150,ri={"Grenka's Claw"}},src={"Test of Endurance"}}
E["quest:1151"] = {t="quest",n="Test of Strength",z="thousandneedles",s="The Test of Strength is the third trial overseen by the tauren mystic Dorn Plainstalker in Thousand Needles. To prove their physical prowess, Horde champions are tasked with hunting down Rok'Alim the Pounder, an ancient, free-roaming rock elemental, and returning with remnants of his shattered form.",h="The Test of Strength is the third trial overseen by the tauren mystic Dorn Plainstalker in Thousand Needles.",sec={{t="Remnants of the Black Empire",b="Long ago, during the reign of the Old Gods, primordial elementals blanketed the surface of the world, serving their dark masters. When those ancient entities were overthrown and sealed beneath the earth, the elemental spirits lost their tether to this realm, largely fading from physical existence unless bound and summoned by modern spellcraft. A few entities, however, were stubborn and potent enough to linger on Azeroth indefinitely without magical anchors. Rok'Alim the Pounder is one such relic, wandering the arid canyons of Thousand Needles as a living echo of that primordial age.",sp=0},{t="The Pounder of Thousand Needles",b="The local centaur clans gave Rok'Alim his moniker on account of the deafening, earthquake-like crashes produced when his stone fists strike the canyon floor. Anyone foolish or bold enough to stray into his roaming path is hammered into dust. Because Rok'Alim represents raw, unbridled physical mass, Dorn Plainstalker directs initiates to break the beast as a direct measure of their warrior spirit, demanding fragments of the elemental's stony heart as proof of victory.",sp=0}},faq={{q="Where does this quest begin and end?",a="The quest is offered and completed by Dorn Plainstalker, a tauren elder stationed at the Weathered Nook, a secluded canyon camp nestled high among the spires of Thousand Needles.",al={"quest giver","where to turn in","dorn location"},it="place",gp=true},{q="What is Rok'Alim the Pounder?",a="Rok'Alim is an ancient rock elemental who has endured in Kalimdor since the era of the Old Gods. Unlike modern summoned elementals, he possesses enough innate power to remain physically manifest on Azeroth entirely on his own.",al={"who is rokalim","what kind of mob is rokalim","elemental lore"},it="target"},{q="Why do the centaur call him 'the Pounder'?",a="The centaur tribes in the canyon dubbed him the Pounder because of the thunderous, rolling shockwaves his stone fists unleash when smashing anything in his path.",al={"the pounder nickname","centaur name for rokalim"},it="name"},{q="Where can Rok'Alim be found in the canyon?",a="Rok'Alim wanders the northwestern stretches of Thousand Needles, generally patrolling open ground south of the main road that cuts through the canyon floor.",al={"rokalim spawn","where is rokalim"},it="place",gp=true},{q="What place does this quest hold in the overall trial chain?",a="Test of Strength is the third trial in the chain. It follows the Test of Faith and the Test of Endurance, and directly precedes the final trial, the Test of Lore.",al={"quest chain order","what comes next","what comes before"},it="purpose"},{q="Why does Dorn require an elemental to be slain instead of a beast or enemy?",a="Dorn chooses Rok'Alim because the elemental is a pure manifestation of living stone and unyielding, primordial force. Conquering such an opponent proves physical superiority over the raw, unbending earth itself.",al={"why kill an elemental","purpose of test of strength"},it="motive"},{q="Why does Dorn Plainstalker want this done?",a="Dorn Plainstalker is putting you through an ancient tauren rite to prove your mettle before advancing to the final trials. Facing a mere beast or soldier would not truly gauge your might, so he demands you challenge an enduring remnant of primordial stone. Slaying Rok'Alim proves that your inner and physical strength can overcome even ancient elemental forces.",al={"dorn plainstalker motive","why does dorn want rokalim killed","why take the test of strength"},it="motive",add=true},{q="What are the Fragments of Rok'Alim for?",a="The fragments serve as incontrovertible proof that you stood before Rok'Alim the Pounder and reduced the ancient elemental to rubble. Dorn Plainstalker requires physical evidence of your victory to acknowledge that you have fulfilled the Test of Strength and earned passage to the next trial.",al={"fragments of rokalim use","what are the fragments for","why collect rokalim fragments"},it="item",add=true}},ang={["race:Tauren"]="For tauren pilgrims, facing down an untamed spirit of stone is a traditional test of harmony and physical will, demonstrating the hunter's capacity to endure and overcome the harshest forces of the Earth Mother.",["class:Shaman"]="Shaman recognize Rok'Alim not just as an obstacle, but as a dangerous, unbound manifestation of earth whose refusal to yield disturbs the local balance of spirits.",["faction:Horde"]="Completing the Weathered Nook rites earns the respect of the Thunder Bluff elders and cements an adventurer's reputation across Kalimdor."},kw={"dorn plainstalker","old gods","rock elemental","rok'alim","test of strength","the pounder","thousand needles","weathered nook"},rel={"npc:dorn-plainstalker","subzone:weathered-nook","quest:1150","quest:1152","quest:1149","zone:thousandneedles","topic:old-god","topic:centaur"},m={start="Dorn Plainstalker",level="30",faction="Horde",id=1151,ri={"Fragments of Rok'Alim"}},src={"Test of Strength"}}
E["quest:1152"] = {t="quest",n="Test of Lore",z="thousandneedles",s="Following trials of faith, endurance, and strength in Thousand Needles, Dorn Plainstalker directs Horde champions northward to Stonetalon Mountains. There, a wise shaman named Braug Dimspirit waits to administer the Test of Lore. This trial shifts the focus from physical resolve to an understanding of the world's deep history and widespread suffering.",h="Following trials of faith, endurance, and strength in Thousand Needles, Dorn Plainstalker directs Horde...",sec={{t="From Faith to Lore",b="In the sheltered refuge of the Weathered Nook, Dorn Plainstalker pushes initiates through demanding trials meant to test their spiritual conviction, physical endurance, and martial prowess. Yet brute strength and blind faith alone do not make a true champion of the Horde. Dorn recognizes his own boundaries as a teacher and sends those who have proven themselves to Stonetalon Mountains, where an elder shaman can test their intellect and worldliness.",sp=0},{t="The Road to Stonetalon",b="The journey takes travelers north across the dry scrub of the Barrens and into the crags of Stonetalon. High in the mountains, near the entrance to Talondeep Path—the cavern cutting through the rock toward Ashenvale—sits the hermitage of Braug Dimspirit. He watches over an embattled frontier where goblin logging ventures despoil the forests and hostile night elves fiercely defend their ancestral borders.",sp=0},{t="A Broader Perspective",b="Upon meeting Braug, the true purpose of the test becomes apparent. Rather than asking for blind factional pride, Braug reflects on the tragic state of Azeroth. He observes that while the orcs and Forsaken receive relentless blame for war and corruption, almost every civilization shares responsibility for the land's plight. Goblins tear down ancient timber, and night elves harbor deep distrust for the younger races. The Test of Lore demands that a champion see beyond immediate enmities and grasp the broader history of a wounded world.",sp=1}},faq={{q="What is the Test of Lore?",a="It is an instructional trial within a larger rite of passage designed by tauren elders. Initiates must prove that they possess not only physical might and faith, but also historical awareness and an understanding of Azeroth's shared past.",al={"test of lore meaning","what is this quest"},it="purpose"},{q="Where can I find Braug Dimspirit?",a="Braug Dimspirit resides in the Stonetalon Mountains, situated near Windshear Crag right by the entrance to the Talondeep Path cave that connects Stonetalon to Ashenvale.",al={"braug dimspirit location","where is braug"},it="place",gp=true},{q="Why does Dorn Plainstalker send you away?",a="Dorn oversees the trials of faith, endurance, and strength in Thousand Needles, but he admits that the lore of the world is not his domain to teach. He directs worthy initiates to Braug, a shaman with the necessary wisdom to test the mind.",al={"why stonetalon","why dorn sends you"},it="motive"},{q="What threats should travelers look out for on the way?",a="Dorn specifically warns that night elves prowl the borderlands near Ashenvale and Stonetalon, viewing Horde presence as an intrusion. The surrounding area in Windshear Crag is also rife with volatile goblin logging operations.",al={"dangers to braug","talondeep path danger"},it="danger"},{q="What is Braug Dimspirit's view of the world's conflicts?",a="Braug believes that all mortal races share blame for the world's suffering. While the orcs and Forsaken are frequently demonized by rivals, he points out that goblin greed and night elven arrogance have inflicted equal harm across Kalimdor and Lordaeron.",al={"braug dimspirit philosophy","what does braug believe"},it="conflict"},{q="What is the Talondeep Path?",a="Talondeep Path is a prominent mountain tunnel system linking Windshear Crag in the Stonetalon Mountains with the ancient woodland borders of southern Ashenvale.",al={"what is talondeep path","talondeep cave"},it="place"}},ang={["race:Tauren"]="The trials embody traditional tauren philosophies, valuing spiritual harmony and historical understanding above raw bloodlust.",["class:Shaman"]="Braug Dimspirit represents the shamanic worldview that reads the land's suffering through the reckless deeds of mortals, from goblin exploitation to ancient elven isolation.",["faction:Horde"]="Braug's trial forces Horde champions to reflect candidly on their own allies' reputations, reminding them that neither the orcs nor the Forsaken are solely responsible for the land's troubles."},kw={"braug dimspirit","dorn plainstalker","stonetalon mountains","talondeep path","test of lore","thousand needles","weathered nook","windshear crag"},rel={"quest:1151","quest:1149","npc:dorn-plainstalker","subzone:weathered-nook","subzone:talondeep-path","subzone:windshear-crag","zone:stonetalon","zone:thousandneedles"},m={start="Dorn Plainstalker",["end"]="Braug Dimspirit",level="30",faction="Horde",id=1152},src={"Test of Lore"}}
E["quest:1154"] = {t="quest",n="Test of Lore",z="thousandneedles",s="The Test of Lore is a trial set by Braug Dimspirit at the entrance to Talondeep Path, testing a Horde adventurer's mind rather than their physical endurance. To pass, the seeker must venture deep into the haunted barrow dens of Ashenvale, recover an ancient tome of dragon history, and study its contents before being quizzed.",h="The Test of Lore is a trial set by Braug Dimspirit at the entrance to Talondeep Path, testing a Horde...",sec={{t="A Shift in the Trials",b="After proving their physical endurance and unwavering faith across the salt flats and plateaus of Thousand Needles, candidates under Dorn Plainstalker's series of trials are sent north to Braug Dimspirit in the Stonetalon Mountains. Stationed near the mouth of Talondeep Path, Braug dismisses the earlier challenges as simple physical exercises. To truly serve the Horde with distinction, an adventurer requires a sharp and disciplined intellect, prepared to understand ancient histories rather than merely striking down beasts.",sp=0},{t="The Shadows of Dor'Danil",b="Braug directs petitioners to venture through Talondeep Path into the forested reaches of southern Ashenvale. There, hidden beneath the canopy south of Splintertree Post, lies the Dor'Danil Barrow Den. The subterranean sanctuary is a perilous ruin haunted by fallen night elf druids and the vicious creatures that slaughtered them. Rested upon a stony podium deep in the lower chambers lies the prize: 'Legacy of the Aspects', a rare manuscript detailing the ancient creation and corruption of the great Dragon Aspects.",sp=0},{t="Study or Suffer",b="Securing the tome is only half of Braug's trial. Before surrendering the volume, the seeker must commit its teachings to memory. Braug immediately takes the book upon delivery and tests the seeker's recall regarding the Titan-empowered protectors and the cataclysmic betrayal that birthed Deathwing. Those who fail to study or guess poorly find themselves abruptly banished across Kalimdor to Camp Taurajo in the southern Barrens, forced to trek back to Stonetalon in disgrace.",sp=1}},faq={{q="Who is Braug Dimspirit?",a="Braug Dimspirit is an elder tauren shaman stationed near the entrance to Talondeep Path in the Stonetalon Mountains. He serves as an examiner following Dorn Plainstalker's earlier trials, testing whether Horde champions possess the intellect and knowledge necessary to complement their raw martial prowess.",al={"braug dimspirit","who gives test of lore","stonetalon quest giver"},it="identity"},{q="Where is the book Legacy of the Aspects located?",a="The book rests inside the Dor'Danil Barrow Den in southern Ashenvale, located almost directly south of Splintertree Post. It sits on a stone podium situated upon a central platform in the subterranean depths of the barrows.",al={"legacy of the aspects location","where is the book","dor danil book spot"},it="place",gp=true},{q="What lurks inside Dor'Danil Barrow Den?",a="The barrow den was once a sanctuary for night elf druids, but tragedy struck the hollows. It is now overrun by the restless spirits of dead druids and the lethal invaders that butchered them, presenting a deadly maze for any trespasser.",al={"dor danil enemies","who guards the book","ashenvale barrow den"},it="danger"},{q="Why does Braug make me read the book before turning it in?",a="Braug takes the book when it is returned and tests your recall. He expects you to study it beforehand, because the trial measures knowledge rather than merely retrieving an object.",al={"why read legacy of aspects","quiz test of lore","what happens if i fail the question"},sp=1,it="motive"},{q="How does this quest fit into the broader trial series?",a="This trial follows the Test of Faith initiated by Dorn Plainstalker at the Weathered Nook in Thousand Needles. Where Dorn tested your nerve and survival against deadly odds, Braug assesses your lore-keeping and historical awareness.",al={"test of faith chain","what comes before test of lore","dorn plainstalker trials"},it="history"},{q="What is the subject matter of the Legacy of the Aspects?",a="The manuscript chronicles the mythic history of the Titans empowering the five great Dragon Aspects to safeguard Azeroth. Crucially, it touches upon the fall of Neltharion the Earth-Warder and his transformation into the monstrous destroyer known as Deathwing.",al={"legacy of the aspects story","book lore","what is the book about"},it="item"},{q="Why does Braug Dimspirit require me to find the Legacy of the Aspects?",a="Braug Dimspirit is testing your mind rather than your strength. Having already endured Dorn Plainstalker's physical trials, you are now being judged on your intellect, resourcefulness, and willingness to learn. By sending you alone into dangerous territory to recover and absorb ancient knowledge, Braug determines whether you possess the wisdom worthy of completing the trial series.",al={"why does braug test me","why the legacy of the aspects","why braug dimspirit test"},it="why_me",add=true}},ang={["faction:Horde"]="The trial reflects the Horde's need for warriors who can understand Kalimdor's deep history and navigate the perilous elven ruins of Ashenvale without succumbing to ignorance.",["class:Druid"]="Venturing into the Dor'Danil Barrow Den brings druidic travelers face-to-face with the tragedy of corrupted and slain night elf brethren who once slept in communion with the Emerald Dream."},kw={"ashenvale","braug dimspirit","camp taurajo","deathwing","dor'danil barrow den","dorn plainstalker","legacy of the aspects","talondeep path","test of lore"},rel={"quest:1152","quest:1149","subzone:dor-danil-barrow-den","subzone:talondeep-path","npc:dorn-plainstalker","npc:deathwing","topic:titan","subzone:camp-taurajo"},m={start="Braug Dimspirit",level="30",faction="Horde",id=1154,ri={"Legacy of the Aspects"}},src={"Test of Lore (2)"}}
E["quest:1159"] = {t="quest",n="Test of Lore",z="thousandneedles",s="This leg of the Test of Lore sends Horde adventurers across the Great Sea to the ruins of Lordaeron. Having answered Braug Dimspirit's initial riddle in the Stonetalon Mountains, you are directed to seek a former human scholar among the Forsaken in the Undercity.",h="This leg of the Test of Lore sends Horde adventurers across the Great Sea to the ruins of Lordaeron.",sec={{t="A Scholarly Alliance",b="After proving your mettle and unraveling the history of the Dragon Aspects recorded in the Legacy of the Aspects, Braug Dimspirit admits his own knowledge has limits. Rather than keeping the trial confined to Kalimdor, Braug demonstrates the broad, surprising reach of the Horde's ties by pointing you toward the undead capital beneath the ruins of Lordaeron.",sp=0},{t="The Sceptical Historian",b="In the damp corridors of the Apothecarium dwells Parqual Fintallas. Once an esteemed human chronicler of the northern kingdoms, Parqual's pursuit of knowledge survived the Scourge and his transformation into one of the Forsaken. Confronted by an outsider claiming to have completed the spiritual and physical trials of Thousand Needles, Parqual refuses to believe you are anything more than an opportunistic mercenary until you prove your worth to him directly.",sp=0}},faq={{q="Why does a tauren trial send me all the way to Undercity?",a="Braug Dimspirit acknowledges that true mastery of lore extends beyond the history of Kalimdor. He directs you to Parqual Fintallas, a renowned human scholar whose knowledge survived the fall of Lordaeron into undeath, to test your understanding of broader world history.",al={"why go to undercity","why lordaeron","braug sending to undead"},it="purpose"},{q="Where exactly is Parqual Fintallas located?",a="Parqual Fintallas resides in the Undercity, specifically standing along the southern bridge in the Apothecarium quarter.",al={"where is parqual","parqual location","find fintallas"},gp=true},{q="Who was Parqual Fintallas in life?",a="In life, Parqual Fintallas was an accomplished human historian within the kingdom of Lordaeron. After succumbing to the Plague of Undeath and joining Sylvanas's Forsaken, he maintained his scholarly pursuits, turning his intellect toward different, darker inquiries.",al={"parqual fintallas lore","who is parqual","fintallas backstory"},it="identity"},{q="Why doesn't Parqual believe Braug sent me?",a="Parqual is deeply skeptical of outsiders. He finds it incredible that an ordinary adventurer could leap from the spires of Thousand Needles, defeat primeval elementals, and retrieve ancient relics, assuming instead you merely overheard rumors in a tavern.",al={"why is parqual rude","parqual reaction","parqual doesn't believe me"},it="conflict"},{q="What larger trial is this quest part of?",a="This quest is the midpoint of the Test of Lore chain, which itself evolved out of the trial initiated by Dorn Plainstalker at the Weathered Nook. It assesses whether an initiate possesses not just combat prowess and courage, but the intellect and historical awareness worthy of a Horde champion.",al={"what chain is this","test of faith chain","what is test of lore"},it="history"},{q="What comes next after reaching Parqual?",a="Before Parqual will deign to ask you his own historical riddle, he demands you undertake an errand on his behalf in the Eastern Kingdoms to verify that you are truly the capable hero Braug claims you to be.",al={"what next after parqual","next quest after undercity","after talking to fintallas"},it="next_step"},{q="Why does Braug Dimspirit send you to Undercity?",a="Braug Dimspirit has tested your initial knowledge, but his role is only to guide you through the first stage of the Test of Lore. To truly challenge your understanding of the world, he recognizes that the next question requires a perspective beyond his own. He sends you to Parqual Fintallas—a famed historian from Lordaeron now among the Forsaken—so your devotion to history and truth can be judged by a scholar who pursues enlightenment of an entirely different nature.",al={"why does braug send me","braug dimspirit motive","why go to undercity braug"},it="motive",add=true}},ang={["race:Undead"]="Meeting Parqual highlights that despite their rot and undeath, Forsaken scholars like him retained the vast academic traditions and records of the fallen kingdom of Lordaeron.",["race:Tauren"]="For a tauren initiate, leaving the open plains and high mesas of Kalimdor to navigate the poisonous, claustrophobic sewers of Undercity makes this journey as much a cultural trial as a historical one.",["faction:Horde"]="This quest demonstrates the cross-continental cooperation binding the newly forged Horde, pairing tauren wisdom seekers with the grim archivists of Lordaeron."},kw={"apothecarium","braug dimspirit","dorn plainstalker","lordaeron","parqual fintallas","test of lore","thousand needles","undercity","weathered nook"},rel={"quest:1152","npc:parqual-fintallas","zone:undercity","subzone:apothecarium","quest:1149","zone:thousandneedles","subzone:weathered-nook","npc:dorn-plainstalker"},m={start="Braug Dimspirit",["end"]="Parqual Fintallas",level="30",faction="Horde",id=1159},src={"Test of Lore (4)"}}
E["quest:1176"] = {t="quest",n="Load Lightening",z="thousandneedles",s="Pozzik, the head goblin engineer out at the Mirage Raceway, needs materials to shave critical ounces off his rocket-car chassis. Rather than relying purely on heavy metal plating, the goblins salvage hollow bones from local desert vultures to build sturdy, ultralight steering and structural rigs.",h="Pozzik, the head goblin engineer out at the Mirage Raceway, needs materials to shave critical ounces off his...",sec={{t="Every Ounce Counts",b="Across the blinding white expanse of the Shimmering Flats, the rivalry between goblin and gnomish engineers is decided by fractions of a second. Raw engine thrust is useless if a racer is weighed down by excessive bulk. While gnome teams obsess over intricate gears and brass fittings, the goblin crew led by Pozzik seeks ruthless pragmatic efficiency: stripping out dense iron framing and replacing it with lighter, hollow structural components wherever the frame permits.",sp=0},{t="Desert Scavenging for Speed",b="Rather than shipping expensive, specialized composites out to Thousand Needles, Pozzik turns to the surrounding salt wastes. Salt Flats vultures are plentiful, their skeletons honed by flight to possess hollow, honeycombed cores that provide great tensile strength with almost no mass. By substituting worked vulture bones into the racer's steering rig and minor braces, Pozzik's mechanics aim to keep their machines nimble enough to outmaneuver the gnomes without shaking apart at top speed.",sp=0}},faq={{q="Why does Pozzik want vulture bones for a race car?",a="Goblin engineering favors ingenuity and opportunistic materials. Vulture bones are hollow and naturally lightweight, offering an ideal strength-to-weight ratio to reinforce delicate parts like steering rigs without weighing down the racer.",al={"vulture bones purpose","why bones","pozzik bones"},it="item"},{q="Who is Pozzik?",a="Pozzik is the lead goblin racing mechanic and team leader stationed at the Mirage Raceway in the Shimmering Flats. He directs the goblin pits against their bitter rivals, the gnomes.",al={"pozzik","pozzik lore","who is the goblin engineer"},it="identity"},{q="Where are these vultures found?",a="The scavengers and vultures circle the open expanse of the Shimmering Flats, particularly around the gigantic skeletal remains scattered in the northeastern stretches of the salt basin.",al={"vulture location","where to find hollow bones","shimmering flats scavengers"},it="target",gp=true},{q="What is the Mirage Raceway?",a="The Mirage Raceway is a neutral racing ground established on the expansive dry salt lake of Thousand Needles. Goblins and gnomes compete there in high-speed, dangerous experimental rocket-car races.",al={"raceway lore","what is mirage raceway","shimmering flats track"},it="place"},{q="Are the gnomes doing the same thing?",a="While the gnomes also look for ways to streamline their racers, their engineering tradition leans toward precision clockwork and complex metals rather than the goblins' scrappy, salvage-based modifications.",al={"gnome racers","gnome vs goblin","are gnomes using bones"},it="conflict"},{q="Does this work help with Pozzik's larger racing effort?",a="Yes. Proving your reliability by lightening the racer earns Pozzik's trust, leading to further work involving track rivalries and official goblin sponsorship out on the flats.",al={"quest continuation","what comes next","goblin sponsorship"},it="next_step"},{q="Why is Pozzik so focused on lightening his racer?",a="At the Mirage Raceway, speed is everything, and races often come down to tiny fractions of an advantage. Pozzik is competing directly against gnome engineering, where any excess bulk can cost him a victory on the salt flats. Shaving every spare ounce off the frame and steering rig allows his rocket car to reach maximum acceleration without sacrificing structural integrity.",al={"pozzik motive","why lighten racer","why does pozzik need light parts"},it="motive",add=true},{q="Why are there so many vultures in the Shimmering Flats?",a="The Shimmering Flats are an unforgiving, sun-baked expanse littered with the remains of massive ancient beasts and fallen wanderers. Salt scavengers thrive out here by circling overhead and feeding on the carrion left behind by the harsh desert climate and the flats' violent basilisk and silithid populations.",al={"why vultures shimmering flats","salt flats vultures lore","thousand needles vultures"},it="target",add=true}},ang={["profession:Engineering"]="Pozzik's reliance on avian bone frames showcases quintessential goblin ingenuity: functional, improvised, and surprisingly effective at reducing curb weight.",["race:Gnome"]="Watching goblins literally lash scavenged bird carcasses into mechanical steering rigs is bound to scandalize any classically trained Tinker Town engineer."},kw={"bones","load lightening","mirage raceway","pozzik","rocket car","shimmering flats","thousand needles","vulture"},rel={"npc:pozzik","subzone:mirage-raceway","subzone:shimmering-flats","zone:thousandneedles","topic:goblin"},m={start="Pozzik",level="30",faction="Neutral",id=1176,ri={"Hollow Vulture Bone"}},src={"Load Lightening"}}
E["quest:1179"] = {t="quest",n="The Brassbolts Brothers",z="thousandneedles",s="Pilot Longbeard in Ironforge needs a courier to deliver a crate of reinforced siege engine helmets across the sea to Kalimdor. His friends, the Brassbolts brothers, are testing high-speed rocket cars in the Shimmering Flats and urgently need head protection for their accident-prone test drivers.",h="Pilot Longbeard in Ironforge needs a courier to deliver a crate of reinforced siege engine helmets across the...",sec={{t="A Long-Distance Favor",b="While stationed among his aerial machinery in Ironforge, the dwarven aviator Pilot Longbeard received an urgent request from the Shimmering Flats in southern Kalimdor. His friends, a pair of inventive gnomes known as the Brassbolts brothers, had taken up residence on the vast salt pans to race experimental machinery. Longbeard is tied down by military and piloting duties, leaving him unable to deliver the supplies himself.",sp=0},{t="Safety at High Velocity",b="The Brassbolts' rocket car has turned out to be extraordinarily fast—so fast that their test drivers keep wiping out across the salt beds and suffering severe concussions. Longbeard procures a crate of heavy-duty dwarven Siege Engine helmets to protect their craniums. Delivering the crate gives the gnomes the leverage they need to coax reluctant pilots back behind the wheel of their volatile speed machine.",sp=0}},faq={{q="Who is Pilot Longbeard?",a="Pilot Longbeard is a dwarven aviator located in Ironforge. An acquaintance of the Brassbolts brothers, he acts as their supply contact back in the Eastern Kingdoms, procuring heavy dwarven gear they cannot easily manufacture out in the field.",al={"pilot longbeard","quest giver","who gives this quest"},it="identity"},{q="Who are the Brassbolts brothers?",a="The Brassbolts brothers, including Wizzle Brassbolts, are ambitious gnomish engineers who established a presence at the Mirage Raceway in the Shimmering Flats. They spend their days designing and tuning cutting-edge rocket cars to outrace goblin competitors.",al={"brassbolts brothers","wizzle brassbolts","gnome brothers"},it="people"},{q="Where is the Shimmering Flats?",a="The Shimmering Flats is an expansive, sun-baked salt plain located in southern Kalimdor, past the tall canyon pillars of Thousand Needles. Its sheer, obstacle-free expanse makes it an ideal proving ground for experimental high-speed vehicles.",al={"shimmering flats location","where to deliver","where is race track"},it="place",gp=true},{q="Why do the gnomes need Siege Engine helmets?",a="The Brassbolts' rocket car achieves immense speeds, but its steering and stability leave much to be desired. Driver crashes and concussions became so frequent that no test pilots were willing to get behind the wheel without substantial dwarven head protection.",al={"why helmets","crash helmets","rocket car crashes"},it="motive"},{q="Why doesn't Longbeard deliver them himself?",a="Pilot Longbeard is tied down by his military obligations and duties in Ironforge. Because making the long voyage across the Great Sea to southern Kalimdor would abandon his post, he relies on traveling adventurers to haul the heavy crate.",al={"why not longbeard","longbeard duties"},it="why_me"},{q="Can Horde players complete this task?",a="No. This quest originates with Pilot Longbeard in the Alliance capital of Ironforge and is exclusive to Alliance couriers, although the Mirage Raceway itself welcomes both factions.",al={"is this alliance only","horde version","faction"},gp=true}},ang={["race:Gnome"]="The Brassbolts' pursuit of pure velocity showcases classic gnomish ambition, where mechanical innovation takes absolute precedence over minor details like braking and driver longevity.",["race:Dwarf"]="Only sturdy dwarven Siege Engine armor is thick enough to survive a full-throttle gnomish rocket collision out on the salt flats.",["profession:Engineering"]="A quintessential engineering supply run, bridging dwarven heavy-armor craftsmanship with gnomish high-velocity propulsion experiments."},kw={"brassbolts","ironforge","mirage raceway","pilot longbeard","rocket car","shimmering flats","thousand needles","wizzle brassbolts"},rel={"npc:wizzle-brassbolts","npc:pilot-longbeard","subzone:shimmering-flats","zone:thousandneedles","topic:gnome"},m={start="Pilot Longbeard",["end"]="Wizzle Brassbolts",level="30",faction="Alliance",id=1179},src={"The Brassbolts Brothers"}}
E["quest:1950"] = {t="quest",n="Get the Scoop",z="thousandneedles",s="Magus Tirth has locked a crucial spellbook inside his magically sealed strongbox, but he cannot recall the activation phrase to open it. To retrieve the tome, you must locate his missing apprentice somewhere around the Shimmering Flats racetrack and pry the forgotten words from him.",h="Magus Tirth has locked a crucial spellbook inside his magically sealed strongbox, but he cannot recall the...",sec={{t="A Magus and His Memory",b="Magus Tirth is an eccentric spellcaster dwelling on the cracked salt bed of the Shimmering Flats in Thousand Needles. While he possesses the esoteric knowledge and tomes that advancing mages desperately seek, dealing with him requires patience. Tirth relies heavily on an assistant to manage mundane details, including the spoken passwords guarding his arcane repositories. When tasked with retrieving a book of power, visiting practitioners quickly learn that Tirth has locked the volume away behind magic words that have slipped his mind entirely.",sp=0},{t="Fowl Play",b="Tracking down Tirth's apprentice, Johnson, is not a matter of simply wandering the paddocks of the Mirage Raceway. After asking around the goblins and gnomes running the track, one discovers that Johnson has suffered the quintessential occupational hazard of serving an erratic wizard: transfiguration. Cursed by his master into the form of a common chicken, Johnson wanders the salt flats, unable to speak until a passing traveler draws near and breaks the magical haze long enough for him to squawk out the missing password.",sp=1}},faq={{q="Who is Magus Tirth?",a="Magus Tirth is a reclusive human wizard stationed near the Mirage Raceway in the Shimmering Flats of Thousand Needles. He possesses advanced arcane lore sought out by mages looking to hone their craft.",al={"tirth lore","who is magus tirth","tirth shimmer flats"},it="identity"},{q="Why does Tirth need the password to his own box?",a="Tirth magically locked his strongbox using a spoken phrase, relying on his assistant to remember mundane details like passwords. True to his absent-minded nature, he forgot the words as soon as his apprentice vanished.",al={"why tirth forgot","tirth strongbox password"},it="motive"},{q="Where did the apprentice go?",a="Johnson did not flee far. He is wandering near the racetrack east of Tirth's camp, though locating him is complicated by the fact that Tirth turned him into a chicken.",al={"find tirth assistant","where is apprentice johnson","johnson location"},sp=1,it="target"},{q="Why was the apprentice turned into a chicken?",a="Tirth placed a curse on Johnson before forgetting he had done so. Upon learning the fate of his assistant, Tirth vaguely assumes the apprentice deserved it for being an ungrateful pupil.",al={"why johnson chicken","tirth polymorph apprentice"},sp=1},{q="What is inside Tirth's strongbox?",a="The magically sealed chest holds a book containing rituals and instructions essential for a mage's continuing education and magical implements.",al={"tirth strongbox contents","what book is in the chest"},it="item"},{q="Who can undertake this task?",a="This errand is part of a dedicated trial meant exclusively for mages seeking specialized instruction and materials to craft a potent wand.",al={"can non mages do get the scoop","is this quest mage only"},gp=true},{q="Why does Magus Tirth send you instead of finding the apprentice himself?",a="Magus Tirth has no intention of scouring the Shimmering Flats himself when you are the one begging for his knowledge. You came seeking his rare magical tome, and since he cannot recall the verbal incantation to open his own magically sealed strongbox without his missing assistant, he makes helping him the price of his aid.",al={"why send me","why doesn't tirth find johnson","why do i have to find the apprentice"},it="why_me",add=true}},ang={["class:Mage"]="Dealing with Tirth offers a humorous yet cautionary glimpse into the perils of polymorph curses and the absent-mindedness that can afflict powerful scholars."},kw={"get the scoop","johnson","magus tirth","mirage raceway","shimmering flats","strongbox","thousand needles","wand quest"},rel={"zone:thousandneedles","subzone:drag"},m={start="Magus Tirth",level="30",faction="Neutral",id=1950},src={"Get the Scoop"}}
E["quest:4542"] = {t="quest",n="Message to Freewind Post",z="thousandneedles",s="Message to Freewind Post is a Horde quest tasking travelers with carrying urgent dispatches from Brave Moonhorn near the border lifts down into Thousand Needles. The missive warns Cliffwatcher Longhorn of intensifying centaur raids against local caravans. It also raises early concerns regarding the suspicious, standoffish behavior of the neighboring Grimtotem clan.",h="Message to Freewind Post is a Horde quest tasking travelers with carrying urgent dispatches from Brave...",sec={{t="A Warning Down the Canyon",b="Standing watch near the canyon's western approaches, Brave Moonhorn keeps a vigil over the roads leading down into Thousand Needles. With centaur aggression abruptly spiking, communication between border sentries and the regional leadership is vital. Moonhorn entrusts passing Horde adventurers with carrying an urgent dispatch southeast to Cliffwatcher Longhorn, the commander stationed atop the mesa settlement of Freewind Post.",sp=0},{t="Rising Perils and Uneasy Kin",b="Upon receiving the message, Longhorn confirms the dire situation: a recent supply caravan was intercepted and slaughtered by marauding centaur, leaving Freewind Post in desperate need of retaliation and defense. Just as concerning is Moonhorn's parting caution to avoid the local Grimtotem tauren, whose uncharacteristically bizarre and hostile demeanor hints at deeper rifts brewing across the arid flats.",sp=0}},faq={{q="Who sends the message to Freewind Post?",a="Brave Moonhorn, a tauren scout keeping watch along the western entrance to Thousand Needles, gives you the urgent missive to deliver.",al={"quest giver","who starts message to freewind post","brave moonhorn"},it="identity"},{q="Who receives the urgent message?",a="Cliffwatcher Longhorn receives the message atop the towering mesa settlement of Freewind Post, located southeast of the Great Lift.",al={"where to turn in","cliffwatcher longhorn location","freewind post leader"},it="identity"},{q="What does the urgent message report?",a="The message alerts Freewind Post to a sudden increase in centaur attacks and caravan harassment along the trails below.",al={"message contents","what is the message about"},it="purpose"},{q="Why is Brave Moonhorn worried about the Grimtotem?",a="Moonhorn notes that the nearby Grimtotem clan members have been acting strange and distant toward other tauren, advising travelers to steer clear of them.",al={"grimtotem warning","why avoid grimtotem"},it="threat"},{q="What happens after Longhorn reads the message?",a="Enraged by the slaughter of a recent supply caravan, Cliffwatcher Longhorn immediately orders retaliatory action against the local centaur in the follow-up mission, Pacify the Centaur.",al={"next quest","after message to freewind post"},it="next_step"},{q="How do you reach Freewind Post from the canyon floor?",a="Follow the main canyon road east until you reach the base of the massive needle mesa, then ride the wooden platform lift directly up into the village.",al={"getting to freewind post","how to get up freewind post"},gp=true},{q="Why does Brave Moonhorn want the message delivered to Freewind Post?",a="Centaur attacks in the canyon have surged, putting travelers, caravans, and outposts in immediate danger. Stationed at the Great Lift, Brave Moonhorn witnesses the escalating violence firsthand and knows that Cliffwatcher Longhorn and the garrison atop Freewind Post need advance warning to organize defenses and protect vital supply routes.",al={"why send message to freewind post","brave moonhorn motive","why warn longhorn"},it="motive",add=true},{q="Why does Brave Moonhorn need an adventurer to carry the message?",a="Brave Moonhorn is stationed as a guard holding the vital border at the Great Lift between the Barrens and Thousand Needles. With centaur raids escalating and the neighboring Grimtotem clan acting suspiciously, Moonhorn cannot abandon his sentry post without leaving the lift defenseless, making a capable traveler the best choice to run the dispatch.",al={"why can't moonhorn deliver it","why me message to freewind post","why does moonhorn need help"},it="why_me",add=true}},ang={["race:Tauren"]="For the tauren, the centaur have been ancestral, bitter rivals for generations. Moonhorn's warning serves as a grim reminder that their ancient enemies still hunt the trails of Kalimdor, even as tensions with the reclusive Grimtotem clan simmer.",["faction:Horde"]="Freewind Post serves as the Horde's vital lifeline across the expanse of Thousand Needles. Keeping the communication lines open between outpost watchers and the settlement's leadership is critical to securing the desert trade routes."},kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","grimtotem","message to freewind post","thousand needles","urgent message"},rel={"npc:brave-moonhorn","npc:cliffwatcher-longhorn","subzone:freewind-post","quest:4841","quest:5064","topic:centaur","zone:thousandneedles"},m={start="Brave Moonhorn",["end"]="Cliffwatcher Longhorn",level="25",faction="Horde",id=4542},src={"Message to Freewind Post"}}
E["quest:4767"] = {t="quest",n="Wind Rider",z="thousandneedles",s="Wind Rider is a Horde quest offered by Elu atop Freewind Post in Thousand Needles. Aspiring to become a wind rider himself, Elu tasks adventurers with climbing into the craggy heights of Highperch to gather wild wyvern eggs to bolster the Horde's aerial mount reserves.",h="Wind Rider is a Horde quest offered by Elu atop Freewind Post in Thousand Needles.",sec={{t="The Call of the Sky",b="Across Kalimdor, the Horde relies heavily on wind riders to ferry couriers, scouts, and warriors across vast distances. At Freewind Post, a young tauren named Elu aspires to join their esteemed ranks. With the demands of the expanding Horde outpacing the availability of mounts, Elu has been charged with helping procure new wyverns to supply the master wind riders, offering eager travelers a chance to assist in this vital effort.",sp=0},{t="Ascending Highperch",b="Highperch rises atop the towering mesas of Thousand Needles, serving as a prime nesting ground for wild wyverns. Gathering viable eggs requires braving the cliffs and facing the fiercely protective adults that patrol the roosts. By securing these clutches, Elu hopes to prove his dedication and begin the rigorous process of hand-raising and training wyverns for the Horde's flight masters.",sp=0}},faq={{q="Who gives this quest?",a="The quest is given by Elu, an aspiring wind rider located atop Freewind Post in Thousand Needles.",al={"wind rider quest giver","who starts wind rider","elu location"},it="identity"},{q="What does Elu need?",a="Elu asks you to bring him ten Highperch Wyvern Eggs gathered directly from the nests in Highperch.",al={"wind rider objectives","what do i collect","wyvern eggs"},it="purpose",gp=true},{q="Where is Highperch located?",a="Highperch is an elevated mesa plateau located northwest of Freewind Post, or just south of Whitereach Post. A natural ramp marked by a totem pole leads up from the canyon floor to the nesting grounds.",al={"how to get to highperch","highperch entrance","where are wyvern eggs"},it="place",gp=true},{q="Why is the Horde gathering wild wyvern eggs?",a="The Horde's master wind riders are facing growing demand for aerial mounts across their outposts, and captive breeding alone cannot keep up. Raising wyverns from wild clutches allows handlers to train fresh mounts to meet their transport and scouting needs.",al={"why harvest wyvern eggs","lore behind wyvern eggs"},it="motive"},{q="Are the wild wyverns hostile?",a="Yes. Wild wyverns are fiercely territorial and protective of their broods, readily attacking anyone who approaches their clutches on Highperch.",al={"will wyverns attack","wyvern danger"},it="danger"},{q="What does Elu intend to do with the eggs?",a="Elu hopes that delivering the eggs will allow him to begin formal wind rider training, raising and bonding with the creatures to serve the Horde in the skies.",al={"elu wyverns","what happens to the eggs"},it="item"}},ang={["faction:Horde"]="Wyverns form the backbone of the Horde's transit network in Kalimdor, making the replenishment of their stables critical for frontier communication and defense.",["race:Tauren"]="The wind riders of Freewind Post take pride in their mastery of aerial flight, viewing the stewardship and training of wyverns as an honorable pursuit.",["class:Hunter"]="Hunters familiar with taming and beast temperament will appreciate the peril and precision required to snatch wild clutches directly from a territorial predator's nest."},kw={"elu","freewind post","highperch","thousand needles","wind rider","wyvern eggs"},rel={"npc:elu","subzone:highperch","subzone:freewind-post","subzone:whitereach-post","zone:thousandneedles","topic:horde","quest:92472"},m={start="Elu",level="29",faction="Horde",id=4767,ri={"Highperch Wyvern Egg"}},src={"Wind Rider (quest)"}}
E["quest:4770"] = {t="quest",n="Homeward Bound",z="thousandneedles",s="Homeward Bound is a Horde quest that tasks adventurers with rescuing Pao'ka Swiftmountain, a young tauren naturalist stranded in the wyvern nesting grounds of Highperch. After getting separated and lost while studying the dangerous beasts, Pao'ka must be escorted safely down the cliffs back toward Whitereach Post.",h="Homeward Bound is a Horde quest that tasks adventurers with rescuing Pao'ka Swiftmountain, a young tauren...",sec={{t="A Naturalist in Over His Head",b="Pao'ka Swiftmountain accompanied the elder Motega Firemane from Mulgore to Thousand Needles to study the unique wildlife of the canyon floor and its towering stone pillars. Driven by curiosity and overconfidence, Pao'ka crept alone into the heights of Highperch to observe the local wyverns firsthand. The territorial beasts drove him off, leaving the young scholar stranded, terrified, and hiding among the crags for days.",sp=0},{t="The Path Down the Crags",b="Highperch is thick with aggressive wyverns fiercely guarding their clutches and high roosts. Escorting Pao'ka back to level ground requires carving a path straight through the nesting predators. Unprepared for open combat, the panicked youth relies entirely on passing Horde travelers to fend off the swarming wyverns until he reaches the relative safety of the canyon path leading east.",sp=0},{t="Relief and Reckoning",b="Reaching the base of the cliffs allows Pao'ka to scramble safely home to Whitereach Post. His guardian, Motega Firemane, is stunned to learn what transpired. Motega had promised Pao'ka's hesitant father that he would look after the boy during their field studies. Relieved that Pao'ka survived his foolish expedition, Motega rewards his saviors while privately lamenting that he did not chain the reckless apprentice to a totem.",sp=1}},faq={{q="Who is Pao'ka Swiftmountain?",a="Pao'ka Swiftmountain is a young tauren apprentice who traveled to Thousand Needles with Motega Firemane to document and study wild creatures. His youthful enthusiasm led him to wander into Highperch unsupervised.",al={"paoka","pao'ka","who is the escort npc"},it="identity"},{q="Why was Pao'ka hiding in Highperch?",a="He ventured into the roosts alone to get a closer look at the native wyverns and their nests. The aggressive beasts attacked him, forcing him into hiding and leaving him trapped on the high mesa.",al={"why is paoka in highperch","what happened to paoka","why is he stuck"},it="why_here"},{q="Who is Motega Firemane?",a="Motega Firemane is a tauren naturalist stationed at Whitereach Post in Thousand Needles. He was entrusted by Pao'ka's father to oversee the youth's safety during their scientific expedition.",al={"motega","who is motega firemane","quest turn in npc"},it="identity"},{q="Where is Highperch located?",a="Highperch is an elevated mesa and wyvern nesting ground situated in the western expanse of Thousand Needles, just west of Whitereach Post and northwest of Freewind Post.",al={"highperch location","where is highperch","where do i escort him from"},it="place",gp=true},{q="Where is Whitereach Post?",a="Whitereach Post is a small Horde encampment located east of Highperch in Thousand Needles, serving as a field base for tauren naturalists studying the canyon's fauna.",al={"whitereach location","where is whitereach post"},it="place",gp=true},{q="Does Motega know Pao'ka was missing?",a="No. Pao'ka snuck away to Highperch on his own without telling Motega, which is why Motega was completely unaware of the danger his apprentice was in until you report the rescue.",al={"did motega know","why didn't motega search for him"},sp=1},{q="Why does Pao'ka Swiftmountain want this done?",a="Pao'ka snuck into Highperch alone to observe the wyverns and wound up cornered after venturing too close to their nests. Trapped and lost for days amidst aggressive predators, he cannot fight his way down on his own. Worse, he knows Motega Firemane will be furious if his reckless expedition is discovered, making an escorted escape his only hope of surviving and returning to Whitereach Post.",al={"why help paoka","paoka motive","why does paoka need escort"},it="motive",add=true},{q="Why does Pao'ka need you to escort him rather than the guards?",a="Pao'ka snuck away from Whitereach Post in secret, and no one back at camp even knows he went missing. Calling for guards would expose his disobedience to Motega Firemane, but more urgently, he has been trapped in the aerie for days without seeing an ally. You are simply the first friendly traveler to stumble upon his hiding spot.",al={"why me paoka","why doesn't paoka call guards","why help paoka alone"},it="why_me",add=true}},ang={["race:Tauren"]="The bond between tribes and elders is paramount among the tauren; Motega's deep responsibility to Pao'ka's father highlights the close communal obligations that guide their expeditions.",["faction:Horde"]="Wyverns are essential allies and mounts for the Horde across Kalimdor, making the wild specimens of Highperch an area of great natural and strategic curiosity."},kw={"escort","highperch","homeward bound","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post","wyvern"},rel={"npc:pao-ka-swiftmountain","npc:motega-firemane","subzone:highperch","subzone:whitereach-post","quest:4767","subzone:freewind-post","zone:thousandneedles","topic:tauren"},m={start="Pao'ka Swiftmountain",["end"]="Motega Firemane",level="29",faction="Horde",id=4770},src={"Homeward Bound"}}
E["quest:4821"] = {t="quest",n="Alien Egg",z="thousandneedles",s="Rumors among the tauren of Freewind Post speak of a bizarre, foreign egg guarded fiercely by wild serpents on the canyon floor. Hagar Lightninghoof tasks Horde adventurers with tracking down and retrieving the specimen before whatever lurks inside breaks free.",h="Rumors among the tauren of Freewind Post speak of a bizarre, foreign egg guarded fiercely by wild serpents on...",sec={{t="A Strange Nest",b="Word reached Freewind Post of an unusual egg spotted deep in the serpent dens that dot the canyon floor beneath the towering stone needles. The serpents native to the canyon watch over the egg as though it were their own brood, striking out at any traveler who ventures too close. Intrigued and wary of what might threaten the local hunting grounds, Hagar Lightninghoof asks brave scouts to locate the clutch, bypass the slithering sentries, and secure the oddity for study.",sp=0},{t="The Hatchling Awakens",b="Upon inspecting the retrieved egg closely, Hagar discovers far more than an ordinary reptilian clutch. The shell fractures immediately upon handling, unleashing a juvenile winged monstrosity known as a Young Arikara. Rather than attacking, the newborn creature bursts skyward, fleeing the wooden platforms of Freewind Post and signaling that far deeper primordial forces stir within the canyon winds.",sp=1}},faq={{q="Where can the Alien Egg be found?",a="The egg rests within one of several serpent nests scattered along the cliff bases of Thousand Needles, particularly to the south and northeast of Freewind Post. It sits directly on the canyon floor, surrounded by hostile native serpents.",al={"alien egg location","where is alien egg","egg spawn thousand needles"},it="place",gp=true},{q="Why are the local serpents guarding it?",a="Though the egg belongs to a distinct flying serpent known as Arikara, the canyon's common serpents instinctively protect it as if it were a member of their own clutch, aggressively defending the nest from any curious intruders.",al={"why do serpents protect the egg","serpent behavior alien egg"},sp=1,it="hostile"},{q="Who is Hagar Lightninghoof?",a="Hagar Lightninghoof is a tauren scout and warden stationed high atop Freewind Post in Thousand Needles. He keeps watch over unusual movements and ecological threats across the canyon floor, coordinating Horde efforts to manage local beasts.",al={"hagar lightninghoof lore","who is quest giver hagar"},it="identity"},{q="What happens when you deliver the egg?",a="When Hagar begins to examine the egg, it cracks open to reveal a Young Arikara. The winged serpent briefly startles Hagar before taking flight and escaping into the skies of Thousand Needles.",al={"what hatches from alien egg","what is inside the egg"},sp=1,it="next_step"},{q="What does this quest lead to?",a="Delivering the egg begins the Arikara chain, immediately leading to the quest 'Serpent Wild', where Hagar seeks to understand the nature of the strange winged serpents rising in the canyon.",al={"next quest after alien egg","arikara chain next step"},sp=1,it="next_step"},{q="Is the egg literally from outer space?",a="In this context, 'alien' refers to something wholly foreign, unnatural, and unfamiliar to the local ecology of Thousand Needles rather than a star-traveling organism. It belongs to the legendary wind serpent Arikara.",al={"is alien egg extraterrestrial","is egg alien"},sp=1,it="origin"},{q="Why does Hagar Lightninghoof want the Alien Egg?",a="Hagar has heard troubling rumors of an unfamiliar, foreign egg discovered within the serpent dens of Thousand Needles. Because none of the scouts have been able to get close enough to examine it past the serpents fiercely protecting it, he wants it recovered so he can study it firsthand. He is deeply concerned about what kind of unknown creature might hatch from it beneath Freewind Post.",al={"why hagar wants egg","hagar lightninghoof motive","why alien egg quest"},it="motive",add=true},{q="What is the Alien Egg?",a="The Alien Egg is an unusual clutch found deep in the serpent dens across Thousand Needles. While it does not look like standard serpent brood, local wind serpents fiercely guard it as if it were their own. Hagar Lightninghoof seeks it out to inspect its origins, though upon closer inspection, it quickly hatches into a young winged serpent that takes flight.",al={"what is alien egg","alien egg purpose","alien egg lore"},sp=1,it="item",add=true}},ang={["race:Tauren"]="Living above the canyon floor on Freewind Post, the tauren rely on understanding the delicate balance of the wildlife below; an invasive or unnatural serpent brood poses a direct disruption to their home.",["class:Hunter"]="Hunters familiar with the beasts of Kalimdor will immediately recognize that the brood nests in the canyon harbor something far more primordial than common desert serpents.",["faction:Horde"]="Freewind Post serves as the Horde's primary outpost in Thousand Needles, making the containment of emerging apex predators a key priority for defending supply lines."},kw={"alien egg","arikara","freewind post","hagar lightninghoof","serpent den","serpent wild","serpents","thousand needles"},rel={"npc:hagar-lightninghoof","quest:4865","quest:5088","subzone:freewind-post","zone:thousandneedles"},m={start="Hagar Lightninghoof",level="26",faction="Horde",id=4821,ri={"Alien Egg"}},src={"Alien Egg (quest)"}}
E["quest:4841"] = {t="quest",n="Pacify The Centaur",z="thousandneedles",s="Pacify the Centaur is a retaliatory hunting mission issued by Cliffwatcher Longhorn atop Freewind Post. Charged with clearing the threat gathering beneath the canyon spires, Horde adventurers strike deep into the Galak centaur encampments of Splithoof Crag.",h="Pacify the Centaur is a retaliatory hunting mission issued by Cliffwatcher Longhorn atop Freewind Post.",sec={{t="A Threat on the Canyon Floor",b="Perched upon its precarious desert mesa, Freewind Post grants the tauren a commanding vantage over the canyon floor of Thousand Needles. However, that high ground offers little peace when hostile enemies mass directly beneath the ropes and elevators. The Galak centaur have established a sprawling war camp nestled directly north along the canyon wall at Splithoof Crag, directly menacing supply lines and tauren movement through the needles.",sp=0},{t="Retaliation and Bloodshed",b="To counter the growing danger, Cliffwatcher Longhorn sends capable Horde travelers to thin the Galak ranks through unsparing violence. Rather than merely defending the access lifts, the tauren believe the only way to safeguard Freewind Post is to break the centaur vanguard in their own camp. Taking down their scouts, beast-wranglers, and windchaser mystics is meant to blunt any concerted assault on the post before it can begin.",sp=0}},faq={{q="Who gives the quest Pacify the Centaur?",a="Cliffwatcher Longhorn gives the quest atop Freewind Post in Thousand Needles. He serves as one of the post's key defenders, monitoring the dangers lurking across the surrounding salt flats and canyons.",al={"quest giver","who starts pacify the centaur","cliffwatcher longhorn"},gp=true},{q="Where are the Galak centaur located?",a="The Galak centaur are encamped directly north of Freewind Post up against the northern cliff wall of Thousand Needles, in an area designated as Splithoof Crag.",al={"galak camp location","where is splithoof crag","centaur location"},it="place",gp=true},{q="Why do the tauren want the centaur killed?",a="The centaur have long waged a brutal, genocidal war against the nomadic tauren across central Kalimdor. With the Galak clan establishing a forward camp right at the foot of Freewind Post, Cliffwatcher Longhorn demands swift retribution to ensure the safety of the Horde's desert stronghold.",al={"why kill centaur","tauren centaur conflict","why revenge"},it="motive"},{q="What kinds of centaur need to be slain?",a="The quest tasks you with hunting down twelve Galak Scouts, ten Galak Wranglers, and six Galak Windchasers from their encampment at Splithoof Crag.",al={"galak targets","which centaur to kill","quest objectives"},it="target",gp=true},{q="What comes after completing Pacify the Centaur?",a="Once the Galak ranks are thinned, Cliffwatcher Longhorn turns his attention toward other regional threats, directing you into the follow-up mission Grimtotem Spying.",al={"next quest","what follows pacify the centaur","quest chain after centaur"},it="next_step",gp=true},{q="What pre-requisite leads into this mission?",a="The mission opens up following the delivery quest Message to Freewind Post, which directs travelers to report directly to Cliffwatcher Longhorn.",al={"prereq","previous quest","how to unlock pacify the centaur"},gp=true},{q="Who are the Galak centaur camping north of Freewind Post?",a="The Galak tribe represents the local centaur threat in Thousand Needles, entrenched directly beneath the mesa cliffs at Splithoof Crag. Known for their fierce scouts, beast-tamers, and windchasers, they maintain an aggressive presence that constantly harasses travelers and tauren outposts throughout the canyon floor.",al={"who are galak centaur","galak centaur","centaur north of freewind post"},it="target",add=true}},ang={["race:Tauren"]="For the shu'halo, the sight of centaur camps encroaching upon a settlement triggers memories of generational slaughter. Thinning the Galak is a matter of pure cultural survival.",["faction:Horde"]="Freewind Post is the Horde's vital lifeline connecting the Southern Barrens and the shimmering salt flats of the Great Lift. Leaving aggressive centaur beneath its towers endangers every caravan traversing the zone."},kw={"cliffwatcher longhorn","freewind post","galak scout","galak windchaser","galak wrangler","pacify the centaur","splithoof crag","thousand needles"},rel={"npc:cliffwatcher-longhorn","subzone:freewind-post","subzone:splithoof-crag","zone:thousandneedles","quest:4542","quest:5064","topic:centaur"},m={start="Cliffwatcher Longhorn",level="25",faction="Horde",id=4841},src={"Pacify the Centaur"}}
E["quest:4865"] = {t="quest",n="Serpent Wild",z="thousandneedles",s="Serpent Wild is a Horde quest in Thousand Needles that connects the discovery of strange alien eggs to ancient tauren legends. Following an unsettling revelation at Freewind Post, Hagar Lightninghoof dispatches adventurers northwest to Motega Firemane at Whitereach Post to confront the awakening of Arikara.",h="Serpent Wild is a Horde quest in Thousand Needles that connects the discovery of strange alien eggs to...",sec={{t="A Legend Made Flesh",b="When strange, unnatural eggs began appearing in Thousand Needles, local tauren feared an ecological disaster. However, inspecting the artifacts reveals something far older and more ominous than ordinary predators: signs pointing to the vengeance spirit Arikara. Stunned by the horrifying confirmation, Hagar Lightninghoof realizes the canyon faces a mythical threat long thought relegated to fireside lore.",sp=0},{t="The Road to Whitereach",b="Recognizing that the threat surpasses simple physical defense, Hagar urges immediate council with Motega Firemane. Stationed northwest along the canyon floor at Whitereach Post, Motega serves as a watcher and spiritual guide versed in the traditional omens of the Needles. His guidance is essential if the Horde hopes to understand and appease or destroy the rising vengeance spirit.",sp=0}},faq={{q="Who starts the quest Serpent Wild?",a="Hagar Lightninghoof, located high atop Freewind Post in Thousand Needles, offers the quest immediately after you investigate the strange alien eggs found throughout the canyon.",al={"who gives serpent wild","serpent wild questgiver","hagar lightninghoof quest"},gp=true},{q="Where is Motega Firemane located?",a="Motega Firemane resides at Whitereach Post, a small tauren camp situated along the road northwest of Freewind Post, past the fork that leads toward the Great Lift.",al={"where is motega firemane","motega firemane location","find motega"},it="place",gp=true},{q="Who or what is Arikara?",a="Arikara is a legendary wind serpent spirit embodying vengeance in tauren mythology, whose rumored presence in Thousand Needles poses a dire spiritual and physical threat to the local tribes.",al={"what is arikara","arikara lore","legend of arikara"},it="threat"},{q="What prerequisite must be finished before taking this quest?",a="You must complete the quest Alien Egg, wherein you recover an unusual egg from the wild beasts of the canyon and deliver it to Hagar Lightninghoof for inspection.",al={"prereq for serpent wild","alien egg quest chain","serpent wild unlock"},gp=true},{q="What happens after reaching Motega Firemane?",a="Speaking with Motega unlocks the quest Sacred Fire, starting the ritual preparations necessary to confront the spirit Arikara.",al={"what comes after serpent wild","serpent wild follow up","sacred fire quest"},it="next_step"},{q="Why is Hagar Lightninghoof so alarmed?",a="Hagar believed the tales of Arikara were mere stories. Actually seeing evidence of the vengeance spirit's manifestation in the canyon terrifies him, prompting him to send for elder wisdom immediately.",al={"why is hagar scared","hagar wiping brow","hagar reaction"},it="motive"}},ang={["race:Tauren"]="The awakening of Arikara turns folklore into urgent crisis, testing the spiritual stewardship of the tauren defending Thousand Needles.",["class:Shaman"]="Disturbances of vengeful spirits like Arikara highlight the delicate balance of elemental and spiritual forces inhabiting the canyon mesas.",["faction:Horde"]="Keeping the supply lines open through Thousand Needles requires resolving mystical threats that could terrorize the road between the Great Lift and Feralas."},kw={"arikara","freewind post","hagar lightninghoof","motega firemane","sacred fire","serpent wild","thousand needles","whitereach post"},rel={"npc:hagar-lightninghoof","npc:motega-firemane","subzone:whitereach-post","subzone:freewind-post","quest:5062","quest:5088","zone:thousandneedles","subzone:great-lift"},m={start="Hagar Lightninghoof",["end"]="Motega Firemane",level="26",faction="Horde",id=4865},src={"Serpent Wild"}}
E["quest:4881"] = {t="quest",n="Assassination Plot",z="thousandneedles",s="Assassination Plot is a Horde quest initiated by recovering intercepted centaur orders in Thousand Needles. The orders reveal an impending strike targeting the tauren Kanati Greycloud at his hunting camp by Whitereach Post.",h="Assassination Plot is a Horde quest initiated by recovering intercepted centaur orders in Thousand Needles.",sec={{t="A Hunter in Hostile Lands",b="Thousand Needles has long been contested terrain dominated by warring centaur clans and dangerous wildlife. When the tauren brave Kanati Greycloud set up a hunting camp at Whitereach Post, the small post southwest of the Great Lift, the local centaur viewed it as an audacious intrusion into their territory. Rather than merely driving game away, the centaur resolved to eliminate Greycloud entirely to discourage any further Horde expansion through the canyon.",sp=0},{t="The Intercepted Orders",b="The plot comes to light when a traveler recovers a written decree outlining the centaur strategy. The note names Kanati Greycloud directly, castigating his boldness and commanding a strike force to converge upon Whitereach Post to wipe out the camp and anyone who might dare follow him. Delivering the missive to Kanati forewarns the hunter, prompting him to prepare for an immediate stand against the raiders.",sp=1}},faq={{q="What is the assassination plot?",a="It is a coordinated ambush planned by local centaur against Kanati Greycloud, a tauren who set up a hunting camp at Whitereach Post in Thousand Needles. The centaur want him dead to prevent the Horde from gaining a foothold in the canyon.",al={"assassination plot overview","what is this quest about","centaur plot"},it="purpose"},{q="Who is Kanati Greycloud?",a="Kanati Greycloud is a tauren who has set up a hunting camp at Whitereach Post, the small post southwest of the Great Lift in Thousand Needles. Camping so close to the centaur clans' canyons makes him a prime target.",al={"who is kanati","kanati greycloud","whitereach post npc"},it="identity"},{q="Why do the centaur want to kill Kanati?",a="The centaur view Kanati's presence at Whitereach Post as an intolerable intrusion into Thousand Needles. They plan to kill him to dismantle the hunting camp and deter any future Horde scouts from settling in the region.",al={"why kill kanati","centaur motive","why do centaur attack"},it="motive"},{q="Where is Whitereach Post?",a="Whitereach Post is a small tauren camp situated in Thousand Needles, resting southwest of the Great Lift along the canyon floor.",al={"whitereach post location","where is kanati's camp","where is whitereach"},it="place",gp=true},{q="Can Alliance players complete this quest?",a="Alliance travelers can find the Assassination Note too, but they can't deliver the warning: Kanati Greycloud is a Horde tauren, and only the Horde can bring it to him.",al={"can alliance do this","alliance assassination note","alliance turn in"},it="side",gp=true},{q="What happens after Kanati is warned?",a="Upon receiving the warning, Kanati refuses to flee. Instead, he braces himself to fight off the attackers, leading directly into the defense of Whitereach Post when the centaur war band arrives.",al={"what happens next","next quest","protect kanati"},sp=1,it="next_step"}},ang={["race:Tauren"]="Centaur animosity runs deep in tauren memory. Defending Kanati Greycloud at Whitereach Post is a direct continuation of the long struggle to safeguard Kalimdor's plains and canyons from centaur aggression.",["faction:Horde"]="Whitereach Post serves as a small Horde outpost southwest of the Great Lift, making Kanati's survival critical for keeping watch over Thousand Needles."},kw={"assassination note","assassination plot","centaur","great lift","horde","kanati greycloud","thousand needles","whitereach post"},rel={"npc:kanati-greycloud","quest:4966","subzone:whitereach-post","zone:thousandneedles","subzone:great-lift","topic:centaur","topic:tauren","topic:horde"},m={start="Assassination Note",["end"]="Kanati Greycloud",level="28",faction="Horde",id=4881},src={"Assassination Plot"}}
E["quest:4904"] = {t="quest",n="Free At Last",z="thousandneedles",s="Free at Last is a rescue mission atop the windswept spires of Darkcloud Pinnacle. Lakota Windsong, a tauren woman held captive by Arnak Grimtotem, needs protection as she flees her captor's stronghold and returns to her friend Thalia Amberhide at Freewind Post.",h="Free at Last is a rescue mission atop the windswept spires of Darkcloud Pinnacle.",sec={{t="A Brutal Abduction",b="The Grimtotem clan's aggressive presence in Thousand Needles is not limited to skirmishes over land. Arnak Grimtotem sought to take Lakota Windsong as his bride, but when she refused his advances, he chose violence. Arnak returned in the night, struck down Lakota's brother when he tried to defend her, and dragged her away to Darkcloud Pinnacle.",sp=0},{t="Escape from Darkcloud Pinnacle",b="Perched across the high wooden suspension bridges above Thousand Needles, Darkcloud Pinnacle is swarming with hostile Grimtotem warriors. Escorting Lakota requires navigating the descent while fighting off waves of Grimtotem bandits intent on recapturing her before she reaches the canyon floor.",sp=0},{t="A Bitter Homecoming",b="Once safely down from the pinnacle, Lakota makes her way back to the safety of Freewind Post. Her companion, Thalia Amberhide, receives the news with immense relief but deep mourning for Lakota's fallen brother, offering his remaining belongings as a token of gratitude to those who brought her home alive.",sp=0}},faq={{q="Why was Lakota Windsong captured?",a="Arnak Grimtotem intended to marry Lakota Windsong. After she refused his proposal, he raided her home at night, murdered her protective brother, and dragged her against her will to Darkcloud Pinnacle.",al={"why is lakota captured","who kidnapped lakota","why did arnak take lakota"},it="why_here"},{q="Where is Darkcloud Pinnacle located?",a="Darkcloud Pinnacle is a cluster of towering rock spires linked by bridges in northern Thousand Needles, situated just southeast of the Great Lift and south of Razorfen Downs.",al={"darkcloud pinnacle location","how to get to darkcloud pinnacle","where is lakota"},it="place",gp=true},{q="Who is Arnak Grimtotem?",a="Arnak is a ruthless member of the Grimtotem tribe stationed on Darkcloud Pinnacle. Besides kidnapping Lakota and slaying her brother, he is also an outlaw marked for death by the Horde authorities at Freewind Post.",al={"arnak lore","who is arnak","wanted arnak"},it="identity"},{q="Who should you speak to after the rescue?",a="Once Lakota is safely escorted off the spires to the canyon floor, you must return to Freewind Post atop the high bluffs and speak with Thalia Amberhide.",al={"where to turn in free at last","who is thalia amberhide","turn in free at last"},it="next_step",gp=true},{q="Why do the Grimtotem attack during the escape?",a="Arnak's Grimtotem bandits patrol the heights of Darkcloud Pinnacle and aggressively ambush anyone trying to help his intended captive reach freedom.",al={"why do bandits spawn","grimtotem bandits escort"},it="hostile"},{q="What happens to Lakota's brother?",a="Lakota's brother was killed trying to defend her from Arnak Grimtotem during the initial kidnapping. His heirlooms are later given away by Thalia as a reward for rescuing his sister.",al={"lakotas brother","who died saving lakota","what happened to lakota brother"},it="history"},{q="Why does Lakota Windsong need your help to escape?",a="Lakota was violently abducted by Arnak Grimtotem after she rejected his marriage proposal, and her brother was slain attempting to defend her. Trapped high on Darkcloud Pinnacle surrounded by hostile Grimtotem warriors, she cannot fight her way down alone. Desperate to flee Arnak's forced courtship and return to Thalia Amberhide at Freewind Post, she needs your armed escort to carve a path through the bandits guarding the mesas.",al={"why help lakota windsong","lakota motive","why does lakota need escort"},it="motive",add=true}},ang={["race:Tauren"]="The Grimtotem clan continues to show their disregard for the peace and unity of the tauren people, demonstrating their brutality through forced kidnappings and fratricide right under the gaze of Freewind Post.",["faction:Horde"]="The Horde holds Freewind Post as an essential fortress in southern Kalimdor, making the lawlessness and kidnappings by the Grimtotem at Darkcloud Pinnacle an intolerable threat to the road."},kw={"arnak grimtotem","darkcloud pinnacle","escort","free at last","freewind post","lakota windsong","thalia amberhide","thousand needles"},rel={"npc:lakota-windsong","npc:thalia-amberhide","quest:5147","subzone:darkcloud-pinnacle","subzone:freewind-post","quest:5064","topic:tauren","zone:thousandneedles"},m={start="Lakota Windsong",["end"]="Thalia Amberhide",level="29",faction="Horde",id=4904},src={"Free at Last (Thousand Needles)"}}
E["quest:4966"] = {t="quest",n="Protect Kanati Greycloud",z="thousandneedles",s="Protect Kanati Greycloud is a Horde quest at Whitereach Post in Thousand Needles. Warned that centaur assassins have targeted the tauren Kanati Greycloud, adventurers must make a stand beside him and repel a squad of Galak assassins.",h="Protect Kanati Greycloud is a Horde quest at Whitereach Post in Thousand Needles.",sec={{t="An Ambush Revealed",b="While stationed among the towering sandstone spires of Whitereach Post, the tauren Kanati Greycloud learns from intercepted centaur orders of an assassination plot directed squarely at his life. The Galak tribe of centaur, relentless in their hostility toward the nomadic tauren and their Horde allies, are not content merely raiding supply paths; they seek to eliminate those who settle in their canyons.",sp=0},{t="Defending Whitereach Post",b="Realizing the attack is imminent and suspecting the enemy forces might outnumber his initial estimates, Kanati asks travelers at the post to fight alongside him. When the Galak assassins strike, Kanati stands his ground, relying on allied blades and spells to break the ambush before the centaur can claim their prize.",sp=0}},faq={{q="Who is Kanati Greycloud?",a="Kanati Greycloud is a tauren who has set up a hunting camp at Whitereach Post in Thousand Needles, close to the canyons the local centaur clans claim as their own.",al={"who is kanati","kanati greycloud lore","who is the quest giver"},it="identity"},{q="Why are the centaur trying to assassinate him?",a="The local Galak centaur view the tauren and their Horde encampments as encroaching enemies on their canyon territory. By killing Kanati, the centaur mean to rid the canyon of his hunting camp and of all who might follow him.",al={"why do centaur attack kanati","centaur assassination reason","assassination plot why"},it="motive"},{q="Where does this defense take place?",a="The ambush takes place directly at Whitereach Post, a small Horde-affiliated outpost situated along the canyon paths of Thousand Needles.",al={"where is this quest","protect kanati location","where does the ambush happen"},it="place"},{q="Which centaur clan attacks Kanati Greycloud?",a="The assassins belong to the Galak tribe, the prominent centaur clan inhabiting the canyons and ravines of Thousand Needles.",al={"what tribe attacks","who are the assassins","which centaur"},it="hostile"},{q="What happens after the assassins are defeated?",a="With the Galak assassins slain, Kanati's life is preserved and Whitereach Post remains secure. Kanati thanks his defenders for standing with him through the surprise assault, successfully concluding the defensive chain.",al={"what happens next","quest follow up","after protecting kanati"},sp=1,it="next_step"},{q="Does Kanati Greycloud fight in the battle?",a="Yes. Kanati does not cower or flee; he actively joins the fray alongside whoever answers his plea, fighting to repel the assassins that came to end his vigil.",al={"does kanati help","kanati fighting","is kanati passive"}},{q="Who are the centaur attacking Kanati Greycloud?",a="The attackers are assassins from the Galak centaur tribe, sent to strike deep into Whitereach Post. Having discovered Kanati Greycloud's presence and his efforts against them, their warband dispatched a dedicated hit squad to eliminate the tauren scout directly at his own camp.",al={"who are the assassins","protect kanati assassins","which centaur attack"},it="target",add=true},{q="Why does Kanati Greycloud need your help defending the post?",a="While Kanati is a capable tauren warrior who fights alongside you, he realizes the centaur have dispatched more assassins than he can handle alone. Whitereach Post is isolated with little immediate reinforcement, making your presence the deciding factor between repelling the ambush and being overwhelmed.",al={"why does kanati need help","why me protect kanati","can kanati fight alone"},it="why_me",add=true}},ang={["race:Tauren"]="The blood feud between the tauren and the centaur runs deep, making the defense of a fellow tribesman from cowardly assassination a matter of survival and honor.",["faction:Horde"]="Whitereach Post serves as a critical vantage point in Thousand Needles, and keeping sentries like Kanati alive is vital to securing Horde operations throughout the canyon."},kw={"assassination plot","assassins","centaur","galak","kanati greycloud","thousand needles","whitereach post"},rel={"npc:kanati-greycloud","subzone:whitereach-post","zone:thousandneedles","topic:centaur","topic:horde"},m={start="Kanati Greycloud",level="28",faction="Horde",id=4966},src={"Protect Kanati Greycloud"}}
E["quest:5064"] = {t="quest",n="Grimtotem Spying",z="thousandneedles",s="Cliffwatcher Longhorn tasks Horde champions with infiltrating Darkcloud Pinnacle to discover what the elusive Grimtotem clan is plotting. Three unknown couriers were spotted visiting the mesa, leaving guarded correspondence scattered across their mountaintop village. Uncovering these secret notes exposes a brewing scheme that threatens the tauren settlements of Thousand Needles.",h="Cliffwatcher Longhorn tasks Horde champions with infiltrating Darkcloud Pinnacle to discover what the elusive...",sec={{t="Eyes in the Wind",b="Freewind Post sits precariously on high spires, but its defenders must constantly look over their shoulders at their hostile cousins. The Grimtotem clan has long maintained a tense, resentful stance toward the Horde, clinging to their isolationist strongholds atop Darkcloud Pinnacle. Cliffwatcher Longhorn noticed a shift in their behavior when three mysterious agents arrived over successive weeks, conferring with clan leadership in secret. Longhorn suspects these emissaries carried marching orders or alliances meant to undermine Thunder Bluff's presence in the canyon.",sp=0},{t="Infiltration of Darkcloud Pinnacle",b="Darkcloud Pinnacle is a fortified network of sheer mesas connected by wooden rope bridges. Penetrating the village requires braving dense patrols of hostile Grimtotem warriors and shamans. Longhorn's scouts confirmed that the mysterious messages were locked away in separate chests spread across the outpost's central dwellings and outer bluffs. Securing the three secret notes requires sneaking or fighting across the entire settlement to snatch the clan's private communications from under their watchful eyes.",sp=0},{t="Dire Portents",b="Returning the three retrieved notes to Cliffwatcher Longhorn validates Freewind Post's darkest fears. The correspondence reveals that the Grimtotem are not merely posturing; they are actively coordinating with outside agents for an impending move. While the full extent of their machinations remains shrouded, Longhorn immediately begins drafting contingencies to protect the canyon posts from sudden betrayal.",sp=1}},faq={{q="Who is sending agents to meet with the Grimtotem?",a="Cliffwatcher Longhorn only knows that three agents of unknown origin were seen visiting Darkcloud Pinnacle over recent weeks. The exact identity of their backers is kept strictly under wraps within the guarded notes.",al={"who visited grimtotem","grimtotem secret agents","who sent the notes"},it="conflict"},{q="Where is Darkcloud Pinnacle located?",a="Darkcloud Pinnacle is situated in western Thousand Needles, southeast of the Great Lift. A marked path with a blue totem leads up the mesa cliffs into the village, where wooden bridges connect several high pinnacles.",al={"where is darkcloud pinnacle","how to get to darkcloud pinnacle","darkcloud pinnacle entrance"},it="place",gp=true},{q="Why are the Grimtotem hostile to other tauren?",a="The Grimtotem believe the tauren are superior to all other races and fiercely reject Cairne Bloodhoof's alliance with the Horde. While some Grimtotem reside under a fragile peace in Thunder Bluff, clans like those on Darkcloud Pinnacle operate with open hostility toward both the Horde and the Alliance.",al={"why do grimtotem hate horde","grimtotem vs thunder bluff","are grimtotem evil"},it="hostile"},{q="Who gives the quest Grimtotem Spying?",a="Cliffwatcher Longhorn offers the quest at Freewind Post in Thousand Needles, but only after you have proven your reliability by completing earlier tasks for the post.",al={"who starts grimtotem spying","grimtotem spying quest giver"},it="origin",gp=true},{q="What prerequisite quests are required before this one?",a="You must complete 'Message to Freewind Post' and 'Pacify the Centaur' before Cliffwatcher Longhorn trusts you enough to entrust you with the espionage mission against the Grimtotem.",al={"prereqs for grimtotem spying","how to unlock grimtotem spying","grimtotem spying chain"},gp=true},{q="What happens when you turn in the three secret notes?",a="Upon reading the contents, Cliffwatcher Longhorn reacts with shock, declaring the news to be dire. He acknowledges that Freewind Post must urgently prepare defenses for whatever scheme the Grimtotem are preparing.",al={"grimtotem spying completion","what do the notes say"},sp=1,it="next_step"},{q="Why does Cliffwatcher Longhorn want this done?",a="Cliffwatcher Longhorn has watched three mysterious agents visit Darkcloud Pinnacle over recent weeks to confer secretly with the Grimtotem Clan. The Grimtotem are notoriously treacherous and untrustworthy, and their clandestine meetings signal that a quiet plot is brewing in the Needles. Longhorn needs those guarded messages retrieved before whatever scheme they are concocting can strike Freewind Post unprepared.",al={"why grimtotem spying","cliffwatcher longhorn motives","why spy on grimtotem"},it="motive",add=true},{q="Who are you sent against at Darkcloud Pinnacle?",a="You are sent directly into the heart of Darkcloud Pinnacle, a fortified village inhabited by the Grimtotem Clan. Unlike the peaceful tribes under Cairne Bloodhoof, this aggressive and secretive tauren clan fiercely guards its territory across the spires of Thousand Needles. Infiltrating their settlement means braving their sentries and raiding their guarded chests to uncover what they are hiding.",al={"who is at darkcloud pinnacle","who are you infiltrating","grimtotem spying target"},it="target",add=true},{q="Why does Cliffwatcher Longhorn entrust this mission to you?",a="You have already proven your loyalty and strength by assisting Freewind Post and dealing with the local centaur threat. Infiltrating a heavily fortified Grimtotem mesa is a delicate and deadly covert operation, not an open assault for the post's standard guards. Longhorn needs a proven, capable outsider who can slip in, secure the documents, and survive.",al={"why does longhorn send you","why me grimtotem spying"},it="why_me",add=true}},ang={["race:Tauren"]="The Grimtotem clan's treachery strikes deeply at the tauren, whose society values harmony and family honor. Discovering that kin are meeting secretly with unknown conspirators threatens everything Cairne Bloodhoof has built.",["faction:Horde"]="Freewind Post is a critical Horde lifeline through southern Kalimdor. Any subversive plotting among the Grimtotem at Darkcloud Pinnacle endangers the tenuous supply lines running between the Barrens and Tanaris.",["class:Rogue"]="Recovering the three chests across Darkcloud Pinnacle's suspended bridges and heavily patrolled buildings is an ideal covert operation, rewarding stealth over outright confrontation."},kw={"cliffwatcher longhorn","darkcloud pinnacle","freewind post","grimtotem","secret notes","spying","tauren","thousand needles"},rel={"npc:cliffwatcher-longhorn","subzone:darkcloud-pinnacle","subzone:freewind-post","quest:4841","quest:4542","quest:5147","npc:lakota-windsong","zone:thousandneedles"},m={start="Cliffwatcher Longhorn",level="28",faction="Horde",id=5064},src={"Grimtotem Spying"}}
E["quest:5147"] = {t="quest",n="Wanted - Arnak Grimtotem",z="thousandneedles",s="Wanted: Arnak Grimtotem is a Horde bounty posted at Freewind Post demanding the execution of a violent Grimtotem exile. Arnak is targeted by the local authorities for murder and kidnapping on the mesas above the canyon.",h="Wanted: Arnak Grimtotem is a Horde bounty posted at Freewind Post demanding the execution of a violent...",sec={{t="A Gruesome Crime",b="While tensions between the mainstream tauren of the Horde and the reclusive Grimtotem tribe are perpetually strained, Arnak took matters far beyond political friction. Branded an outcast, Arnak murdered a tauren and abducted the victim's sister, Lakota Windsong. In response to these heinous acts, Cliffwatcher Longhorn of Freewind Post sanctioned an open bounty calling for the rogue tauren's death.",sp=0},{t="Darkcloud Pinnacle",b="Arnak took refuge upon the high crags of Darkcloud Pinnacle, an extensive network of rope bridges and mesa encampments occupied by the Grimtotem clan near the entrance to Razorfen Downs. Trapped upon these windswept heights alongside Arnak is his captive, Lakota Windsong, awaiting rescue from anyone brave enough to fight across the Grimtotem bridges.",sp=0}},faq={{q="Who is Arnak Grimtotem?",a="Arnak Grimtotem is a notorious tauren outcast who committed murder and kidnapped Lakota Windsong. His violent crimes prompted Freewind Post to put a bounty on his head.",al={"who is arnak","arnak grimtotem lore","who is the wanted tauren"},it="target"},{q="Where can Arnak Grimtotem be found?",a="He is located high up on the northern cliff mesas of Darkcloud Pinnacle in Thousand Needles, accessible by ascending the winding path south of the Great Lift and crossing the high wooden bridges toward Razorfen Downs.",al={"where is arnak","arnak grimtotem location","how to find arnak"},gp=true},{q="Who is Lakota Windsong?",a="Lakota Windsong is a tauren captive held by Arnak on Darkcloud Pinnacle. Her brother was murdered by Arnak during her abduction, and she remains stranded on the mesa until Arnak is dealt with.",al={"who is lakota","lakota windsong story"}},{q="Who offers the bounty reward?",a="Cliffwatcher Longhorn in Freewind Post manages the bounty. He rewards travelers who present Arnak's severed hoof as proof that the rogue tauren has been brought to justice.",al={"who turns in arnak","bounty turn in","cliffwatcher longhorn reward"}},{q="Is Arnak officially working for the Grimtotem tribe?",a="The bounty specifically describes Arnak as an outcast, indicating he has acted beyond any tribal law. Nevertheless, he has taken refuge within the Grimtotem stronghold of Darkcloud Pinnacle.",al={"is arnak with grimtotem","arnak tribe status"}},{q="What proof is required to claim the bounty?",a="Hunters must sever and return Arnak's Hoof to Cliffwatcher Longhorn at Freewind Post to verify his death and receive the bounty.",al={"what do i bring cliffwatcher longhorn","arnak proof","arnaks hoof"},it="item"},{q="Why is Freewind Post offering a bounty on Arnak Grimtotem?",a="Cliffwatcher Longhorn and the defenders of Freewind Post posted the bounty to bring an end to Arnak's crimes across the canyon. Branded an outcast even among his own folk, Arnak committed the brutal murder of a fellow tauren and kidnapped the victim's sister, Lakota Windsong. With the safety of travelers and local tribes threatened by his unchecked violence, Freewind Post wants him permanently eliminated to restore justice to the Thousand Needles.",al={"arnak grimtotem bounty why","why kill arnak","why is arnak wanted"},it="motive",add=true}},ang={["race:Tauren"]="For tauren loyal to Cairne Bloodhoof, tracking down Arnak is an act of tribal justice, punishing a kinslayer who dishonored their traditions by abducting Lakota Windsong.",["faction:Horde"]="Freewind Post serves as the Horde's vital lifeline through Thousand Needles, and eliminating ruthless renegades on Darkcloud Pinnacle secures the heights along the canyon floor."},kw={"arnak grimtotem","bounty","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","outcast","thousand needles"},rel={"npc:cliffwatcher-longhorn","npc:lakota-windsong","quest:4904","subzone:darkcloud-pinnacle","subzone:freewind-post","quest:5064","zone:thousandneedles","topic:tauren"},m={start="Wanted Poster - Arnak Grimtotem",["end"]="Cliffwatcher Longhorn",level="29",faction="Horde",id=5147,ri={"Arnak's Hoof"}},src={"Wanted - Arnak Grimtotem"}}
E["quest:5151"] = {t="quest",n="Hypercapacitor Gizmo",z="thousandneedles",s="Following a deadly centaur ambush on a merchant caravan in Thousand Needles, the goblin tinkerer Wizlo Bearingshiner was left as the sole survivor. Desperate to reclaim his prized invention, he hires adventurers to breach the wreckage, unlock an iron cage, and wrest the gizmo from the neck of a fearsome caged predator.",h="Following a deadly centaur ambush on a merchant caravan in Thousand Needles, the goblin tinkerer Wizlo...",sec={{t="Ambush in the Needles",b="Caravans venturing beneath the towering sandstone spires of Thousand Needles run a perilous gauntlet. Hostile centaur prowl the canyon floor, fiercely guarding their territory and raiding any travelers bold enough to pass through. When one such trade caravan was overrun just north of Whitereach Post, the centaur slaughtered the travelers and plundered the wagons, leaving only the goblin Wizlo Bearingshiner to limp back to safety.",sp=0},{t="An Unlikely Guardian",b="In the chaos of the raid, the centaur looted nearly every valuable scrap, but they gave one ruined wagon a wide berth. Bound inside a sturdy transport cage was a ferocious, enraged panther with Wizlo's prized hypercapacitor gizmo fastened directly around its neck. Daunted by the predator's snarling fury, the centaur abandoned the cage intact, forcing Wizlo to entrust its key to brave mercenaries capable of slaying the beast and reclaiming his gadget.",sp=0},{t="Tinkerer's Ambition",b="True to goblin fashion, Wizlo's passion for mechanical wonder often outpaces practical understanding. Despite hailing the hypercapacitor gizmo as his finest creation and risking lives to retrieve it from the clutches of an apex predator, he admits upon its return that he still has to tinker with it to figure out what it actually does.",sp=1}},faq={{q="Who is Wizlo Bearingshiner?",a="Wizlo Bearingshiner is a goblin tinkerer and merchant who took refuge at Whitereach Post after his caravan was ambushed and destroyed by centaur on the canyon floor of Thousand Needles.",al={"who is wizlo","wizlo bearingshiner lore","quest giver wizlo"},it="identity"},{q="Why is the gizmo around the panther's neck?",a="During the transport or the chaos of the centaur ambush, the device ended up secured around the captive beast's neck. Because the panther was so terrifying, the raiding centaur refused to touch the cage, inadvertently making the predator the device's guardian.",al={"why does the panther have the gizmo","panther necklace","collar gizmo"}},{q="Where is the wrecked caravan located?",a="The wrecked caravan lies just north of Whitereach Post in Thousand Needles, sitting among shattered wagons surrounded by hostile centaur camps.",al={"caravan location","where to find panther cage","cage location"},it="place",gp=true},{q="Why didn't the centaur loot the cage?",a="According to Wizlo, the enraged panther is so ferocious that even the ruthless centaur marauders trembled in its presence and chose to leave the beast locked in its cage rather than risk opening it.",al={"why centaur left panther","centaur afraid of panther","why is cage untouched"}},{q="What does the Hypercapacitor Gizmo actually do?",a="Wizlo proclaims it his finest gizmo, though upon having it returned, he confesses he still has to spend time studying and tinkering with it to discover what function it actually performs.",al={"what does gizmo do","hypercapacitor function","what is the gizmo"},sp=1,it="item"},{q="Who controls Whitereach Post?",a="Whitereach Post is a tauren settlement allied with the Horde, perched amidst the canyon mesas to monitor centaur activity and provide safe harbor to Horde travelers.",al={"whitereach post faction","is whitereach horde"},it="in_charge"},{q="Why does Wizlo Bearingshiner want the Hypercapacitor Gizmo back?",a="Wizlo is the sole survivor of a caravan overrun by centaur in the canyon flats. He considers the hypercapacitor to be his finest invention, even admitting he still needs to figure out entirely what it does. Desperate to salvage the prized contraption from the wreckage of his expedition, he is willing to reward anyone brave enough to wrest it back.",al={"wizlo bearingshiner motive","why recover hypercapacitor","why does wizlo want gizmo"},it="motive",add=true},{q="What beast is guarding the Hypercapacitor Gizmo?",a="The contraption hangs around the neck of an unusually ferocious, caged panther trapped inside the ruined caravan. The beast was so vicious that the raiding centaur dared not touch its iron cage when looting the rest of the supplies, leaving the predator stranded amid the debris just north of the post.",al={"who is guarding the gizmo","panther target","what is the panther"},it="target",add=true},{q="Why does Wizlo Bearingshiner need your help?",a="Wizlo barely escaped the centaur slaughter with his life and is an engineer, not a warrior. The tauren at Whitereach Post maintain their own vigil against the hostile tribes, leaving little interest or manpower to help an eccentric goblin reclaim abandoned tinkering projects from a caged monster surrounded by raiders.",al={"why does wizlo need me","why ask adventurer","why cant wizlo get gizmo"},it="why_me",add=true}},ang={["profession:Engineering"]="Wizlo's frantic pursuit of an invention whose purpose he cannot quite recall exemplifies the chaotic, trial-and-error philosophy of classic goblin engineering.",["faction:Horde"]="Operating out of Whitereach Post, Horde scouts and travelers continually battle the predatory centaur clans that menace transit routes through central Kalimdor.",["class:Hunter"]="The enraged panther held in the wrecked caravan is an unusually formidable beast, fierce enough to terrify a full warband of centaur marauders."},kw={"centaur caravan","enraged panther","goblin engineering","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner"},rel={"npc:wizlo-bearingshiner","subzone:whitereach-post","zone:thousandneedles","topic:centaur","topic:horde"},m={start="Wizlo Bearingshiner",level="30",faction="Horde",id=5151,ri={"Hypercapacitor Gizmo"}},src={"Hypercapacitor Gizmo (quest)"}}
E["quest:5762"] = {t="quest",n="Hemet Nesingwary",z="thousandneedles",s="This errand sends travelers across the sea from the salt pans of Kalimdor to the steaming jungles of Stranglethorn Vale. Kravel Koalbeard, an opportunistic merchant at the Mirage Raceway, tasks adventurers with delivering a long-overdue package of specialty supplies to the renowned big-game hunter Hemet Nesingwary.",h="This errand sends travelers across the sea from the salt pans of Kalimdor to the steaming jungles of...",sec={{t="A Transcontinental Delivery",b="Out in the blinding expanse of the Shimmering Flats, commerce moves fast, but shipments sometimes lag behind. Kravel Koalbeard eventually receives a delayed crate earmarked for one of his wealthy patrons, Hemet Nesingwary. Having departed the Thousand Needles long before the parcel arrived, Hemet paid in advance to have it forwarded along to his wilderness hunting camp in Stranglethorn Vale. Rather than make the arduous trek himself, Kravel enlists roving adventurers willing to bridge the ocean divide.",sp=0},{t="Ammunition for the Hunt",b="Tracking down Nesingwary's expedition north of Grom'gol Base Camp reveals the contents of the heavy crate: specialized heavy-gauge ammunition vital for bringing down the dangerous predators prowling the jungle. Hemet immediately recognizes the distinctive white crust of the salt flats clinging to the courier's gear, pleased that his old ties with the wily Kravel yielded the firepower his safari desperately needed.",sp=0}},faq={{q="Where does this delivery begin and end?",a="The delivery begins with Kravel Koalbeard at the Mirage Raceway in the Shimmering Flats, located in southern Thousand Needles. It finishes halfway across the world at Hemet Nesingwary's expedition camp, nestled in northern Stranglethorn Vale just north of Grom'gol.",al={"quest start and end","where is hemet","where do i go"},it="place",gp=true},{q="What is inside Kravel's Crate?",a="The crate contains special-gauge ammunition tailored for big-game firearms. Hemet Nesingwary ordered the bespoke shot to pierce the thick hides of Stranglethorn's fiercest beasts.",al={"whats in the crate","crate contents","kravel package"},it="item"},{q="Why didn't Kravel deliver the crate himself?",a="Kravel is an enterprising dwarven merchant busy overseeing his investments and schemes at the Mirage Raceway. He prefers to hire passing adventurers with the coin Nesingwary provided in advance rather than abandon his post to cross the seas.",al={"why kravel hire someone","why does kravel need help"},it="why_me"},{q="How does Hemet know where the courier came from?",a="Upon receiving the parcel, Hemet immediately smells and identifies the distinct salt crust clinging to the courier's garments, noting it came straight off the Shimmering Flats rather than standard desert dust.",al={"desert salt","hemet dialogue salt"}},{q="What kind of relationship do Kravel and Hemet have?",a="Hemet is an old, lucrative customer of Kravel's. While Kravel respects Hemet's deep pockets, Hemet fondly regards Kravel as a 'crusty old' rogue who is perpetually up to no good.",al={"kravel and hemet history","do they know each other"},it="ties"},{q="Who is Hemet Nesingwary?",a="Hemet Nesingwary is a celebrated dwarven marksman, author, and big-game hunter who leads an ongoing safari through the perilous depths of Stranglethorn Vale.",al={"who is hemet","nesingwary lore"},it="identity"},{q="Why does Kravel Koalbeard want this crate delivered to Hemet?",a="Kravel is maintaining a lucrative business connection. Hemet Nesingwary is a remarkably wealthy dwarf, and Kravel knows that keeping such rich clientele satisfied pays off. Hemet paid upfront for the crate to be forwarded to his hunting grounds once it arrived, so honoring the deal protects Kravel's reputation and guarantees future coin.",al={"why deliver kravel crate","kravel koalbeard motive","why send crate to hemet"},it="motive",add=true}},ang={["class:Hunter"]="Carrying specialized ammunition directly to Hemet Nesingwary introduces trackers to Azeroth's most famous big-game safari.",["race:Dwarf"]="Delivering custom munitions between two roguish dwarven acquaintances shows how far Ironforge expatriates scatter to pursue coin and quarry."},kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale"},rel={"npc:kravel-koalbeard","subzone:shimmering-flats","zone:thousandneedles","topic:dwarf"},m={start="Kravel Koalbeard",["end"]="Hemet Nesingwary",level="31",id=5762},src={"Hemet Nesingwary (quest)"}}
E["quest:6627"] = {t="quest",n="Test of Lore",z="thousandneedles",s="The Test of Lore is a trial of intellect and historical memory set by the hermit Braug Dimspirit in the Stonetalon Mountains. After retrieving the ancient tome Legacy of the Aspects, travelers must demonstrate their understanding of ancient history by answering Braug's inquiry. Those who fail to heed the text find themselves abruptly banished across Kalimdor.",h="The Test of Lore is a trial of intellect and historical memory set by the hermit Braug Dimspirit in the...",sec={{t="A Trial of Wisdom",b="Part of a broader series of trials originating with Dorn Plainstalker at the Weathered Nook, the Test of Lore shifts focus away from martial survival or blind trust toward understanding the world's ancient past. Braug Dimspirit, residing in the crags of the Stonetalon Mountains, requires seekers to recover ancient texts and genuinely absorb the knowledge held within their pages.",sp=0},{t="Legacy of the Aspects",b="The lesson centers upon the creation and division of the Dragon Aspects, specifically the fateful pact made long before the Great Sundering. Braug tests the seeker's recall regarding the Earth Warder, Neltharion, whose descent into madness and betrayal reshaped the surface of Azeroth. Those who do not respect history are not allowed to proceed along the path of wisdom.",sp=0},{t="The Price of Guesswork",b="Braug does not tolerate idle guessing. A seeker who provides an incorrect answer is instantly expelled by mystic means, finding themselves teleported miles away to Camp Taurajo in the southern Barrens. Reclaiming one's standing requires a long trek back up into Stonetalon to face the hermit's scrutiny a second time.",sp=1}},faq={{q="What is the answer to Braug Dimspirit's question?",a="Braug asks about the identity of the Earth Warder detailed in the tome Legacy of the Aspects. The correct answer is Neltharion, the Black Aspect who would later turn against his fellow dragons.",al={"braug question answer","test of lore answer","legacy of the aspects question"},gp=true},{q="What happens if you answer incorrectly?",a="Giving Braug the wrong name causes an immediate magical banishment, teleporting you directly to Camp Taurajo in the Barrens. You must travel all the way back to his perch in the Stonetalon Mountains to attempt the trial again.",al={"wrong answer test of lore","failed test of lore","teleported to taurajo"},gp=true},{q="Who is Braug Dimspirit?",a="Braug Dimspirit is an elder hermit dwelling in the Stonetalon Mountains who administers tests of knowledge and lore for the Horde, continuing the series of spiritual trials initiated in Thousand Needles.",al={"braug dimspirit","who gives test of lore"},it="identity"},{q="How does this connect to the trials in Thousand Needles?",a="The trial began with Dorn Plainstalker at the Weathered Nook in Thousand Needles with the Test of Faith. Dorn tests physical and spiritual trust, then sends worthy initiates across Kalimdor to have their intellect, resolve, and strength vetted by other wise elders.",al={"dorn plainstalker connection","test of faith chain"},it="origin"},{q="What book is Braug quizzing you about?",a="The quiz tests your comprehension of the Legacy of the Aspects, an ancient treatise detailing the blessing of the five Great Dragon Aspects by the titans to guard Azeroth.",al={"what book braug","legacy of the aspects"},it="item"},{q="Where does this quest chain lead next?",a="Passing Braug's quiz on the Dragon Aspects leads into further investigative trials of ancient history, requiring seekers to scour distant regions for more lost records and ancestral knowledge.",al={"what is after test of lore","next quest in test of lore"},it="next_step"},{q="Why is Braug Dimspirit testing you?",a="Braug Dimspirit serves as an examiner in the trials that began in Thousand Needles. While other trials challenge your martial prowess or faith, the Test of Lore is designed to ensure you do not rely solely on brute force. By requiring you to retrieve ancient texts and comprehend their contents, Braug seeks to cultivate wisdom and historical understanding in those who aspire to represent the Horde.",al={"why does braug test you","braug dimspirit purpose","why test of lore"},it="motive",add=true}},ang={["faction:Horde"]="The Horde's trials in Kalimdor demand more than brute force; warriors and shamans alike are expected to understand the ancient scars and draconic powers that shaped the continent.",["race:Tauren"]="The trial embodies the tauren respect for ancestral wisdom and ancient history, ensuring young champions do not march blindly without knowing the balance of the world.",["class:Mage"]="Mages will find Braug's teleportation ward both impressive and punitive, demonstrating that Stonetalon's hermits wield ancient magic to discipline careless scholars."},kw={"aspects","braug dimspirit","earth warder","neltharion","stonetalon","taurajo","test of faith","weathered nook"},rel={"quest:1152","quest:1149","npc:dorn-plainstalker","zone:stonetalon","subzone:camp-taurajo","subzone:weathered-nook","zone:barrens","zone:thousandneedles"},m={start="Braug Dimspirit",level="30",faction="Horde",id=6627},src={"Test of Lore (3)"}}
E["quest:6628"] = {t="quest",n="Test of Lore",z="thousandneedles",s="This trial marks the intellectual examination in a broader series of spiritual tests originating in Thousand Needles. After scouring the world for historical texts, initiates present themselves to Parqual Fintallas in the Undercity to prove they understand the darker histories that shape Azeroth.",h="This trial marks the intellectual examination in a broader series of spiritual tests originating in Thousand...",sec={{t="A Trial of Knowledge",b="While many trials among the Horde test martial strength or raw endurance, the Test of Lore demands scholarly dedication. Originating from Dorn Plainstalker's spiritual regimen at the Weathered Nook, the journey carries candidates far from the wind-carved canyons of Thousand Needles into the shadowed halls of the Undercity. Parqual Fintallas serves as the examiner, holding seekers to an exacting standard of historical literacy.",sp=0},{t="The Scourge's Genesis",b="To satisfy Parqual, an initiate must study 'Beginnings of the Undead Threat,' a text detailing the cursed origins of the Scourge in Lordaeron. The core of his interrogation concerns the origin of the entity reigning on the Frozen Throne: the former elder shaman Ner'zhul, whose essence was forged by the Burning Legion into the Lich King. Knowing this grim lineage is considered essential for understanding the Forsaken's existence and the dangers facing Kalimdor and the Eastern Kingdoms alike.",sp=1}},faq={{q="What is the answer to Parqual's question?",a="Parqual Fintallas asks for the original name of the Lich King. The correct answer is Ner'zhul, the ancient orc shaman whose spirit was bound to the Frozen Throne.",al={"lich king answer","parqual question","test of lore answer"},gp=true},{q="What happens if you answer the question wrong?",a="Answering incorrectly saddles you with the Mark of Shame debuff, forcing you to wait out the penalty before Parqual will permit you to attempt the examination again.",al={"mark of shame","wrong answer test of lore"},gp=true},{q="Where does this quest chain begin?",a="The overarching trial begins with Dorn Plainstalker at the Weathered Nook, located within the towering spires of Thousand Needles.",al={"where does test of lore start","dorn plainstalker questline"},gp=true},{q="Where is Parqual Fintallas located?",a="Parqual Fintallas resides in the Undercity, lingering among the Forsaken's subterranean libraries and corridors where he interrogates prospective students.",al={"find parqual","parqual fintallas location"},gp=true},{q="What text is this trial based on?",a="The test is based upon the tome 'Beginnings of the Undead Threat', which details the origins of the Plague of Undeath and the creation of the Lich King.",al={"which book for test of lore","beginnings book"},it="item"},{q="Why is a Thousand Needles quest sending people to Undercity?",a="The trials established by the tauren are designed to challenge every facet of an adventurer. To test lore, candidates are sent across the sea to seek out scholarly records preserved in the ruins of Lordaeron.",al={"why go to undercity","thousand needles undercity"},it="purpose"},{q="Why does Parqual Fintallas want this done?",a="Parqual Fintallas is putting your dedication to the pursuit of knowledge to the ultimate test. He believes that knowledge is paramount to survival in this perilous world—the more you learn and observe, the more of the truth you will see. Having tasked you with procuring the tome on the Undead Threat, he demands proof that you actually studied and absorbed its grim history rather than merely running an errand.",al={"parqual motive","why is parqual testing me","why test of lore"},it="motive",add=true}},ang={["race:Tauren"]="Initiated through elder tradition, this test pushes tauren travelers to learn the grim histories of their northern Forsaken allies and the world beyond Kalimdor.",["race:Undead"]="The subject matter strikes at the heart of Forsaken identity: the tragedy of Ner'zhul's creation and the genesis of the curse that bound them before Sylvanas broke the Lich King's grip.",["faction:Horde"]="The trial strengthens ties between Kalimdor's tribes and the kingdom beneath Lordaeron, reminding champions that wisdom is as vital to the Horde's survival as raw strength."},kw={"dorn plainstalker","lich king","mark of shame","nerzhul","parqual fintallas","test of lore","thousand needles","undercity","weathered nook"},rel={"npc:parqual-fintallas","quest:1599","quest:1149","npc:dorn-plainstalker","zone:undercity","zone:thousandneedles","subzone:weathered-nook","topic:lich-king"},m={start="Parqual Fintallas",level="30",faction="Horde",id=6628},src={"Test of Lore (6)"}}
E["quest:8682"] = {t="quest",n="Skyseer the Elder",z="thousandneedles",s="Skyseer the Elder is an honored ancestral spirit residing atop Freewind Post during the Lunar Festival. Travelers seek out his presence high above Thousand Needles to pay their respects to the ancestors and receive his ancient blessing.",h="Skyseer the Elder is an honored ancestral spirit residing atop Freewind Post during the Lunar Festival.",sec={{t="A Beacon in the Needles",b="Perched upon the lofty wooden bluffs of Freewind Post, Elder Skyseer appears bathed in a radiant pillar of celestial light. Positioned near the bridges leading toward the massive mechanical lifts, his ghostly presence offers a quiet sanctuary amid the windswept mesas of Thousand Needles.",sp=0},{t="The Ancestral Path",b="Elder Skyseer receives visiting adventurers who come to honor the past during the celebration of the Lunar Festival. Beyond acknowledging their homage, the venerable elder can guide travelers toward his kin scattered across Kalimdor, including Elder Morningdew and Elder Runetotem.",sp=0}},faq={{q="Where is Elder Skyseer located?",a="Elder Skyseer stands on the upper mesa of Freewind Post in Thousand Needles, situated near the suspension bridges close to the cliffside lifts.",al={"skyseer location","where is skyseer","freewind post elder"}},{q="What is the purpose of seeking out Elder Skyseer?",a="During the Lunar Festival, travelers visit ancestral spirits like Elder Skyseer to pay their respects, receive a Coin of Ancestry, and hear guidance regarding the locations of other elders.",al={"why visit skyseer","skyseer quest objective","lunar festival skyseer"}},{q="Why is Elder Skyseer glowing?",a="Like other honored spirits visiting during the festival, Elder Skyseer is illuminated from the heavens by a bright shaft of moonlight, marking him as an ancestor communing with the living.",al={"why is skyseer in light","elder light beam"}},{q="Which other elders does Skyseer provide directions for?",a="Elder Skyseer provides guidance on how to find nearby ancestral spirits, including Elder Morningdew, Elder Runetotem, Elder Dreamseer, and Elder Wildmane.",al={"other elders","who does skyseer mention","skyseer directions"}},{q="Can Alliance travelers speak with Elder Skyseer?",a="Yes, although Freewind Post is a heavily fortified Horde settlement. Alliance adventurers must tread carefully around the guards to approach the elder without inciting bloodshed.",al={"can alliance talk to skyseer","alliance freewind post elder"}},{q="What happens when you speak to Elder Skyseer?",a="Upon greeting him and paying homage, Elder Skyseer commends your spirit and grants a token of ancestral blessing, completing the brief encounter.",al={"skyseer reward","completing skyseer the elder"}}},ang={["faction:Alliance"]="Elder Skyseer rests inside the Horde stronghold of Freewind Post, requiring Alliance pilgrims to navigate the perilous heights and hostile guards to pay their respects.",["race:Tauren"]="Greeting an honored elder atop one of your people's most iconic mesa aeries embodies the deep reverence the Shu'halo hold for their ancestral lineage.",["class:Druid"]="Communing with the ancient spirits under the moonlight aligns closely with the teachings of Cenarius and honoring those who walked the land before."},kw={"ancestor","coins of ancestry","elder skyseer","freewind post","lunar festival","skyseer","thousand needles"},rel={"npc:elder-skyseer","subzone:freewind-post","zone:thousandneedles","npc:elder-morningdew","npc:elder-runetotem","topic:light"},m={start="Elder Skyseer",id=8682},src={"Skyseer the Elder"}}
E["quest:8724"] = {t="quest",n="Morningdew the Elder",z="thousandneedles",s="Morningdew the Elder is an honored ancestral spirit visited during the Lunar Festival in Thousand Needles. Illuminated by a radiant beam of starlight, she offers ancient wisdom and directs pilgrims toward other elders scattered across Kalimdor.",h="Morningdew the Elder is an honored ancestral spirit visited during the Lunar Festival in Thousand Needles.",sec={{t="A Celestial Presence in the Canyons",b="During the Lunar Festival, the spirits of ancient ancestors manifest across Azeroth to share their blessings with travelers. Elder Morningdew appears bathed in a shaft of lunar light, standing out starkly against the dusty red stone and noisy industrial hubbub of Thousand Needles. She reminds mortal travelers to look beyond earthly concerns to the starry expanse above.",sp=0},{t="Wisdom of the Heavens",b="When approached, Morningdew encourages seekers to look toward the countless stars for answers to earthly mysteries. Beyond her contemplative greetings, she serves as a guide for festival pilgrims, sharing knowledge of the locations of other venerated spirits walking the lands, including Elder High Mountain, Elder Grimtotem, Elder Mistwalker, Elder Moonwarden, and Elder Windtotem.",sp=0}},faq={{q="Who is Elder Morningdew?",a="Elder Morningdew is an ancestral spirit who manifests during the Lunar Festival. Bathed in starlight, she offers wisdom and guidance to passing adventurers seeking to honor the elders.",al={"elder morningdew","morningdew lore","who is morningdew"}},{q="Where can Elder Morningdew be found?",a="She is located in Thousand Needles, visibly marked by a radiant pillar of light descending from the sky.",al={"morningdew location","where is elder morningdew","find elder morningdew"}},{q="What is the purpose of visiting Elder Morningdew?",a="Travelers visit her during the Lunar Festival to pay their respects to the ancestors, receive ancestral blessings, and learn the whereabouts of other elders throughout the region.",al={"why visit morningdew","morningdew purpose","lunar festival elder"}},{q="Which other elders does Morningdew know about?",a="Elder Morningdew provides directions to five other honored spirits: Elder High Mountain, Elder Grimtotem, Elder Mistwalker, Elder Moonwarden, and Elder Windtotem.",al={"morningdew other elders","elders list morningdew","who does morningdew mention"}},{q="Why is there a pillar of light shining down on her?",a="Every ancestral spirit during the Lunar Festival is illuminated by a beam of celestial starlight, highlighting their ethereal presence and connection to the heavens above.",al={"morningdew light beam","shaft of light elder","why does elder glow"}},{q="What does Morningdew teach pilgrims?",a="Morningdew teaches that the heavens and their countless stars hold answers to earthly mysteries, encouraging those who are wise and fortunate to gaze upward to find truth.",al={"morningdew advice","morningdew dialogue","what does morningdew say"}}},ang={["class:Druid"]="The Lunar Festival and its celestial elders embody deep connections to Elune, nature, and ancestral communion held sacred by Cenarion circles.",["class:Shaman"]="Communing with honored spirits like Elder Morningdew is central to understanding the balance of ancestors and elements throughout the world.",["race:NightElf"]="Elders illuminated by starlight evoke the ancient traditions of honoring the heavens and the ancient wisdom woven throughout Kalimdor's history.",["race:Tauren"]="Revering the wisdom of ancestral elders is a pillar of tauren culture, making the pilgrimage to spirits like Morningdew deeply meaningful."},kw={"ancestor","elder morningdew","elders","lunar festival","morningdew the elder","shimmering flats","starlight","thousand needles"},rel={"npc:elder-morningdew","zone:thousandneedles","topic:light"},m={start="Elder Morningdew",id=8724},src={"Morningdew the Elder"}}
E["subzone:camp-e-thok"] = {t="subzone",n="Camp E'thok",z="thousandneedles",s="Camp E'thok is a Galak centaur settlement located in northwestern Thousand Needles. The aggressive centaur tribe uses this canyon encampment as a base to stage ambushes against passing caravans traveling through the riverbed below.",h="Camp E'thok is a Galak centaur settlement located in northwestern Thousand Needles.",sec={{t="A Galak Stronghold",b="Tucked into the rugged northwestern reaches of Thousand Needles, Camp E'thok serves as a key settlement for the hostile Galak centaur. Like their kin across Kalimdor, the Galak are relentlessly predatory, preying upon any travelers wandering into the canyon shadows. The camp is notorious for orchestrating raids against merchant caravans, notably ambushing the goblin Wizlo Bearingshiner and seizing his goods—though his prized gadget managed to slip beyond their grasp, guarded by his fierce pet panther.",sp=0}},faq={{q="Who lives in Camp E'thok?",a="The encampment is occupied by the Galak clan of centaur, an aggressive tribe dominating parts of northwestern Thousand Needles.",al={"who is in camp ethok","camp ethok inhabitants","who controls camp ethok"},it="residents"},{q="What happened to Wizlo Bearingshiner here?",a="A merchant caravan containing the goblin Wizlo Bearingshiner was ambushed by the Galak centaur from Camp E'thok. While they ransacked the caravan, they failed to take Wizlo's prized gadget because it was secured around the collar of his fierce pet panther.",al={"wizlo bearingshiner raid","goblin caravan attacked","what did centaur steal from wizlo"},it="history"},{q="Where is Camp E'thok located?",a="Camp E'thok is situated in northwestern Thousand Needles, nestled along the base of the canyon walls near Splithoof Heights.",al={"camp ethok location","where is camp ethok","camp ethok map"},gp=true},{q="What is Camp E'thok?",a="Camp E'thok is an active encampment of the Galak centaur tribe, settled in the canyons of northwestern Thousand Needles. The centaur use this fortified site as a base to stage violent ambushes and raids against travelers and merchant caravans passing through the gorges below.",al={"what is camp ethok","camp ethok lore","tell me about camp ethok"},it="place",add=true},{q="Is Camp E'thok dangerous?",a="Camp E'thok is extremely dangerous. The Galak centaurs dwelling here attack outsiders on sight, preying upon any trade caravans daring to traverse the canyon. Anyone wandering into the camp will find themselves facing hostile warriors, shamans, and whatever plunder they have violently gathered.",al={"is camp ethok hostile","how dangerous is camp ethok","danger camp ethok"},it="danger",add=true}},ang={["race:Tauren"]="The relentless aggression of the Galak centaur at Camp E'thok is a constant reminder of the ancestral war between the tauren and centaur throughout southern Kalimdor."},kw={"camp e'thok","centaur","ethok","galak","thousand needles","wizlo bearingshiner"},rel={"zone:thousandneedles","topic:centaur","npc:wizlo-bearingshiner","topic:goblin"},src={"Camp E'thok"}}
E["subzone:darkcloud-pinnacle"] = {t="subzone",n="Darkcloud Pinnacle",z="thousandneedles",s="Darkcloud Pinnacle is a fortified tauren settlement perched atop several interconnected mesas east of the Great Lift in Thousand Needles. Held by the aggressive Grimtotem clan, the aerial stronghold serves as a base of operations for regional disruption and shady dealings.",h="Darkcloud Pinnacle is a fortified tauren settlement perched atop several interconnected mesas east of the...",sec={{t="A Clifftop Stronghold",b="Spanning three main mesas joined by rope bridges, Darkcloud Pinnacle commands the canyon basin below. The heights are accessible only by a steep natural slope leading from the canyon floor across wooden bridges, or via a high crossing near Razorfen Downs. From these windswept rocks, the Grimtotem watch the valley, safe from casual assault and isolated from the broader tauren tribes.",sp=0},{t="Schemes on the Mesas",b="Commanded by leaders such as Arnak Grimtotem and Harb Foulmountain, the settlement is more than a simple outpost. Secret correspondence discovered on the mesa suggests the Grimtotem are actively coordinating with dark and unknown powers, pursuing ambitions far removed from the peace forged by Cairne Bloodhoof in Thunder Bluff.",sp=1}},faq={{q="Who controls Darkcloud Pinnacle?",a="The stronghold belongs to the Grimtotem clan, an aggressive and reclusive tauren faction openly hostile to most outsiders and deeply suspicious of the Horde.",al={"who lives at darkcloud pinnacle","darkcloud pinnacle owners","who is at darkcloud pinnacle"},it="residents"},{q="How do you reach Darkcloud Pinnacle?",a="The pinnacle can be accessed by climbing a natural ramp up an adjacent mesa from the canyon floor and crossing wooden rope bridges, or via a bridge situated near Razorfen Downs.",al={"how to get up darkcloud pinnacle","darkcloud pinnacle path","entrance to darkcloud pinnacle"},it="arrival",gp=true},{q="Who leads the Grimtotem here?",a="The settlement's operations are overseen by prominent Grimtotem figures, including Arnak Grimtotem and Harb Foulmountain.",al={"darkcloud pinnacle leaders","who leads darkcloud pinnacle","grimtotem bosses"},it="leader"},{q="What are the Grimtotem plotting here?",a="The Grimtotem at the pinnacle maintain secret communications with an unknown dark influence, working toward shadowy goals that threaten the stability of Thousand Needles.",al={"what is happening at darkcloud pinnacle","grimtotem conspiracy"},it="threat"},{q="What is Darkcloud Pinnacle?",a="Darkcloud Pinnacle is a fortified tauren village perched high above the canyon floor of Thousand Needles, just east of the Great Lift. It spans three inhabited mesas linked together by suspended rope bridges. The settlement serves as a major stronghold for the Grimtotem tribe, an aggressive and isolationist tauren clan that jealously defends its territory from outsiders.",al={"what is darkcloud pinnacle","darkcloud pinnacle info","about darkcloud pinnacle"},it="place",add=true},{q="Is Darkcloud Pinnacle dangerous?",a="Very dangerous. The Grimtotem tauren who occupy Darkcloud Pinnacle are violently hostile to trespassers and maintain a heavy guard across the entire settlement. With its high mesas and narrow rope bridges, fighting here carries the constant peril of falling into the canyon below, and the tribe's shamans and warriors are prepared to kill anyone who ventures up the slopes.",al={"darkcloud pinnacle danger","how dangerous is darkcloud pinnacle","is darkcloud dangerous"},it="danger",add=true}},ang={["race:Tauren"]="The Grimtotem's treacherous behavior on these mesas stands in stark opposition to the unity and peace Cairne Bloodhoof strives to maintain among the tribes.",["faction:Horde"]="The Grimtotem occupying this mesa act as hostiles, menacing travelers passing from the Great Lift deeper into Thousand Needles."},kw={"arnak grimtotem","darkcloud pinnacle","grimtotem","harb foulmountain","mesa","thousand needles"},rel={"zone:thousandneedles","subzone:great-lift","subzone:razorfen-downs-classic","topic:tauren"},src={"Darkcloud Pinnacle"}}
E["subzone:freewind-post"] = {t="subzone",n="Freewind Post",z="thousandneedles",s="Freewind Post is the primary Horde outpost in Thousand Needles, perched high atop one of the canyon's dramatic stone mesas. Accessible primarily by tauren lift and winding rope bridges, it serves as a defensive refuge against centaur warbands and a vital frontier staging ground.",h="Freewind Post is the primary Horde outpost in Thousand Needles, perched high atop one of the canyon's...",sec={{t="A Fortress in the Sky",b="Built directly upon the canyon mesas, Freewind Post relies on ingenuity and height to safeguard its people. The Galak centaur dominate the arid canyon floor below, but they cannot effectively scale the towering cliffs or breach the heavy wooden elevators that haul Horde travelers up into the sky. A labyrinth of rope and plank bridges connects Freewind to neighboring spires, forming a secure aerie. Beyond keeping centaur raiding parties at bay, the outpost also helps manage the screeching harpies nesting along the bluffs and tends to the nearby wyvern grounds at Highperch, where wild eggs are culled and trained as loyal wind rider mounts for the Horde.",sp=0},{t="Shadows from Darkcloud Pinnacle",b="Despite its impregnable height, Freewind Post faces growing tension with its neighbors to the northwest: the Grimtotem tribe stationed at Darkcloud Pinnacle. Once tolerated as stubborn traditionalists, the Grimtotem under Chieftain Arnak have increasingly turned to violence, kidnapping, and murder. Suspicious rituals and whispers of dark power surround the nearby peaks. The local tauren watch the skies and rope bridges with growing dread, conscious that their most dangerous enemies do not prowl the salt flats below, but sit entrenched across the canyon winds.",sp=1}},faq={{q="Why is Freewind Post built so high up on a mesa?",a="The vertical layout keeps the settlement safe from the hostile Galak centaur warbands patrolling the canyon bottom. Centaur excel on flat terrain but cannot scale sheer cliff faces or easily breach the mechanical wooden lifts used by the tauren.",al={"why is freewind post in the sky","why mesa","freewind post elevation"},it="purpose"},{q="How do you get up and down from the post?",a="Most travelers use the large mechanical wooden lifts stationed at the base of the main mesa. There is also a back route consisting of a precarious series of rope bridges and wooden ramps winding between neighboring rock pillars, though a careless step can mean a lethal plunge to the canyon floor.",al={"how to get up freewind post","freewind post elevator","freewind entrance"},it="arrival",gp=true},{q="What is the relationship between Freewind Post and the Grimtotem?",a="Relations are deeply strained. The Grimtotem occupying Darkcloud Pinnacle northwest of Freewind Post are accused of murders, kidnappings, and unprovoked hostility toward other tauren, leaving the outpost's defenders in a state of quiet vigilance against their neighboring kin.",al={"grimtotem freewind post","darkcloud pinnacle freewind","why are grimtotem bad here"},it="conflict"},{q="What importance does Highperch have to the post?",a="Highperch is an ancestral nesting ground for wild wyverns just across the canyon. The tauren of Freewind Post monitor these beasts and cull eggs from their nests, which are then nurtured and raised to serve as wind rider mounts throughout the Horde.",al={"why highperch","highperch wyverns freewind"},it="ties"},{q="What is Freewind Post?",a="Freewind Post is a fortified Horde outpost situated high atop a towering stone needle in the middle of Thousand Needles. Populated predominantly by tauren loyal to Thunder Bluff, it serves as a central hub of trade, defense, and communication for travelers navigating the canyons between the Southern Barrens, Feralas, and Tanaris.",al={"what is freewind post","freewind post","about freewind post"},it="place",add=true},{q="What happened at Freewind Post?",a="The tauren established Freewind Post atop the high mesas to build a defensible stronghold beyond the reach of the rampaging Galak centaur below. Over time, it grew into an essential outpost for securing the canyons, studying and harvesting wyvern mounts from nearby Highperch, and monitoring the increasingly hostile Grimtotem clan at Darkcloud Pinnacle.",al={"freewind post history","history of freewind post","what happened here"},it="history",add=true},{q="Who lives in or runs Freewind Post?",a="The post is inhabited and defended by Horde-aligned tauren loyal to High Chieftain Cairne Bloodhoof. Alongside brave braves guarding the bridges and lifts, it is home to merchants, wind rider masters, and elders who coordinate patrols against regional threats like the Galak centaur, screeching harpies, and treachery from the nearby Grimtotem.",al={"who runs freewind post","freewind post residents","who lives here"},it="residents",add=true},{q="Is Freewind Post dangerous?",a="The outpost itself is well protected, but its sheer height makes a misstep off the edges or swaying rope bridges fatal. Beyond its perimeter, the surrounding canyon floor crawls with hostile Galak centaur, ravaging harpies roost in the canyon spires, and the sinister Grimtotem tribe plots against the town from neighboring Darkcloud Pinnacle.",al={"is freewind post dangerous","freewind post dangers","threats to freewind post"},it="danger",add=true}},ang={["race:Tauren"]="Freewind Post displays the architectural ingenuity of the shu'halo, adapting mesa heights to shut out traditional centaur marauders while tending the ancestral wyverns of the bluffs.",["faction:Horde"]="Freewind Post is the sole major Horde sanctuary and flight connection between the Southern Barrens and Tanaris, providing essential logistical support across central Kalimdor."},kw={"darkcloud pinnacle","elevator","freewind post","galak","highperch","mesa","tauren","thousand needles","wyverns"},rel={"zone:thousandneedles","subzone:darkcloud-pinnacle","subzone:highperch","topic:grimtotem-tribe","topic:centaur","topic:tauren","subzone:camp-taurajo","zone:thunderbluff"},src={"Freewind Post"}}
E["subzone:great-lift"] = {t="subzone",n="Great Lift",z="thousandneedles",s="The Great Lift is a massive, tauren-engineered elevator system perched on the southern edge of the Barrens. It serves as the primary route lowering travelers and supplies hundreds of feet into the sheer canyon basin of Thousand Needles. Despite its strategic value, aggressive quilboar encroaching through the southern wastes have made approaching the rim increasingly perilous.",h="The Great Lift is a massive, tauren-engineered elevator system perched on the southern edge of the Barrens.",sec={{t="A Gateway Carved from Wood and Rope",b="Spanning the sheer cliff edge between the southern Barrens and the canyon floor of Thousand Needles, the Great Lift stands as a marvel of practical tauren construction. Built using heavy timber, braided rope, and counterweighted pulleys, its paired platforms carry caravans, couriers, and warriors safely across a vertical precipice that would otherwise break any wagon. At the top and bottom platforms, tauren like Brave Moonhorn and Grish Longrunner maintain watch, keeping travelers informed of the road ahead and ensuring cargo passes smoothly.",sp=0},{t="Dangers at the Rim",b="Operating the lift has become increasingly hazardous due to the hostile territory above it. Aggressive quilboar tribes in the southern Barrens have expanded aggressively southward, choking the road toward the lift and threatening to cut off Thousand Needles from the northern trails entirely. Those who make the long journey south must constantly fend off razorfen raiders before they can ever step foot onto the wooden platforms.",sp=0}},faq={{q="Who built the Great Lift?",a="The Great Lift was designed and constructed by the tauren to bridge the massive vertical gap between the arid plateaus of the Barrens and the deep canyon floor of Thousand Needles.",al={"who made the great lift","great lift builders","tauren elevator origin"},it="origin"},{q="Why is traveling to the lift dangerous?",a="The encroaching quilboar of the southern Barrens have aggressively expanded their territory toward the rim. Their raiding parties prowl the approaches, often harassing or outright ambushing supply caravans and couriers bound for the elevator platforms.",al={"why are there quilboar here","southern barrens danger","lift road blocked"},it="threat"},{q="Who watches over the Great Lift?",a="Brave Moonhorn and Grish Longrunner are stationed at the lift to watch the routes, assist Horde travelers, and keep an eye on the surrounding wilderness.",al={"who guards the lift","lift keepers","tauren at the lift"},it="residents"},{q="Where does the Great Lift lead?",a="Riding the platforms down brings travelers onto the canyon floor of Thousand Needles, while ascending leads straight into the southern Barrens.",al={"where does lift go","what is below the lift","lift destination"},it="purpose"},{q="What is the Great Lift?",a="The Great Lift is a massive tauren-engineered elevator situated along the precipice dividing the southern Barrens from the canyon floor of Thousand Needles. It serves as the primary route for travelers, merchants, and messengers seeking to descend the towering cliffs safely without braving treacherous drop-offs.",al={"what is great lift","great lift info","about great lift"},it="place",add=true},{q="Is the Great Lift dangerous?",a="The mechanical platform itself is sound, but the surrounding approaches are fraught with peril. Aggressive quilboar tribes in the southern Barrens have expanded their territory right up to the cliffs, ambushing caravans and threatening to cut off travelers attempting to reach the elevator edge.",al={"is great lift dangerous","great lift safe","threats near great lift"},it="danger",add=true}},ang={["faction:Horde"]="The lift is a vital Horde arterial link connecting central Kalimdor to the isolated reaches of Thousand Needles and Shimmering Flats.",["race:Tauren"]="Constructed with sturdy timber and counterweights, the lift showcases your people's ingenious ability to overcome rugged landscape obstacles without scarring the earth."},kw={"brave moonhorn","elevator","great lift","grish longrunner","quilboar","the barrens","thousand needles"},rel={"zone:thousandneedles","zone:barrens","npc:brave-moonhorn","npc:grish-longrunner","topic:tauren","topic:quilboar"},src={"Great Lift"}}
E["subzone:highperch"] = {t="subzone",n="Highperch",z="thousandneedles",s="Highperch is an elevated plateau in western Thousand Needles, towering high above the canyon floor. It is renowned as a primary nesting ground for wild wyverns and wind riders. The roost is home to fierce prides defending their young among the windswept crags.",h="Highperch is an elevated plateau in western Thousand Needles, towering high above the canyon floor.",sec={{t="Aerie of the Wyverns",b="Rising sharply out of the canyon floor, Highperch is a rugged sanctuary for Kalimdor's native wyverns. The plateau provides natural defense against predators and an unobstructed launch point for their hunting flights across Thousand Needles. Within its reaches, wyvern prides live under the protection of watchful patriarchs and matriarchs, guarding their nests. The beasts fiercely defend their territory against any intruders who manage to climb into their high domain.",sp=0},{t="A Refuge in the Heights",b="While hostile to outsiders, the high cliffs occasionally attract travellers and hunters willing to brave the dangerous ascent. The tauren scout Pao'ka Swiftmountain is stranded on these perilous heights and needs help reaching Whitereach Post. For adventurers journeying through the canyon, scaling the ramp to Highperch means contending with dozens of razor-sharp talons and venomous tails.",sp=0}},faq={{q="What creatures live at Highperch?",a="Highperch is inhabited exclusively by wild wyverns and wind riders. You will encounter protective patriarchs, consorts, soaring adults defending their clifftop nests.",al={"highperch beasts","what is at highperch","highperch mobs"},it="residents"},{q="Where is Highperch located?",a="Highperch is situated in western Thousand Needles, accessible via a winding ramp that leads up from the southern wall of the canyon floor.",al={"highperch location","how to find highperch","where is highperch"},gp=true},{q="Why is Highperch significant to the Horde?",a="Wyverns, also known as wind riders, are the vital flying mounts of the Horde, having allied with the orcs during the Third War. Natural roosts like Highperch represent the wild heritage and thriving population of these loyal beasts.",al={"horde connection to highperch","wyverns and horde","why do orcs care about highperch"},it="purpose"},{q="Who is Pao'ka Swiftmountain?",a="Pao'ka Swiftmountain is a tauren scout stranded amidst the deadly wyvern nests on Highperch. He needs an escort to Whitereach Post.",al={"paoka swiftmountain","tauren at highperch","who got trapped at highperch"},it="people"},{q="What is Highperch?",a="Highperch is an elevated mesa and nesting ground rising above the western canyons of the Thousand Needles. It serves as one of the primary natural habitats for the region's proud wild wyverns, filled with their roosts and soaring flocks.",al={"what is highperch","highperch info","about highperch"},it="place",add=true},{q="What happened at Highperch?",a="For generations, wild wyverns have made their nests high upon this cliffside haven. The tauren scout Pao'ka Swiftmountain is stranded amidst the crags and seeks help returning to Whitereach Post.",al={"highperch history","what happened here","highperch past"},it="history",add=true},{q="Is Highperch dangerous?",a="Yes. The wild wyverns nesting across the crags are fiercely protective of their clutches and territory. Consorts and powerful patriarchs will swoop down upon any trespasser climbing up from the canyon floor who ventures too close to their roosts.",al={"is highperch dangerous","highperch dangers","danger highperch"},it="danger",add=true}},ang={["faction:Horde"]="The wind riders nesting upon Highperch are close kin to the noble flying mounts that carry the Horde across Kalimdor, making the sanctuary an awe-inspiring sight for Horde champions.",["class:Hunter"]="The sprawling aerie offers seasoned hunters a firsthand look at wild wyverns hunting and guarding their nests in their natural, untamed habitat."},kw={"aerie","highperch","nest","pao'ka swiftmountain","thousand needles","wind rider","wyvern"},rel={"zone:thousandneedles","npc:pao-ka-swiftmountain","quest:4767"},src={"Highperch"}}
E["subzone:ironstone-camp"] = {t="subzone",n="Ironstone Camp",z="thousandneedles",s="Ironstone Camp is an outpost established by the Horde along the western border of the Shimmering Flats in Thousand Needles. Originally deployed to expel Alliance dwarven excavators from the nearby digsite, the encampment's forces now face a deadly threat after subterranean silithid overran the excavation.",h="Ironstone Camp is an outpost established by the Horde along the western border of the Shimmering Flats in...",sec={{t="A Change of Mission",b="Ironstone Camp sits directly on the threshold between the high pillars of Thousand Needles and the blazing salt expanse of the Shimmering Flats. The Horde detachment stationed here was initially dispatched with a clear and singular objective: dislodge the dwarven excavators digging at the Rustmaul Digsite. However, their military confrontation was cut short when a swarm of voracious silithid burst forth from a nearby cavern, violently engulfing the dig and attacking both sides. Led by Moktar Krin, the surviving camp defenders have diverted their efforts to combating the insectoid infestation before the swarm spreads unchecked across the region.",sp=0}},faq={{q="What is the purpose of Ironstone Camp?",a="Ironstone Camp was set up as a forward Horde staging point to drive Alliance dwarven excavators out of the Rustmaul Digsite. However, an unexpected swarm of subterranean silithid erupted into the area, shifting the encampment's priority to survival and containment of the insect menace.",al={"why is ironstone camp here","ironstone camp purpose","horde camp shimmering flats"},it="purpose"},{q="Who leads the forces at Ironstone Camp?",a="Moktar Krin directs the Horde fighters stationed here. With the original mission disrupted by the insect outbreak, he coordinates patrols and tasks travelers with culling the aggressive silithid infesting the neighboring digsite.",al={"ironstone camp leader","moktar krin","who runs ironstone camp"},it="leader"},{q="Where is Ironstone Camp located?",a="The camp is situated in Thousand Needles right on the western edge of the Shimmering Flats, resting close to the path leading out of the canyon floor toward the blinding salt flats.",al={"ironstone camp location","where is ironstone camp","how to find ironstone camp"},it="place",gp=true},{q="What is Ironstone Camp?",a="Ironstone Camp is a small Horde outpost pitched right at the border of Thousand Needles and the Shimmering Flats. Its forces were originally sent into the salt flats to confront and drive off the dwarven excavators working the nearby Rustmaul Digsite. Instead of a straightforward skirmish with the Alliance, the scouts found themselves facing a far deadlier nightmare boiling up from beneath the earth.",al={"what is ironstone camp","ironstone camp lore","about ironstone camp"},it="place",add=true},{q="What happened at Ironstone Camp?",a="The camp was established to monitor and dismantle the dwarven operation at Rustmaul Digsite. Before the Horde forces could complete their mission, ravenous silithid erupted from a nearby cave system and overran the area. The insectoid swarm slaughtered and displaced the excavators and quickly turned its aggression on this camp, forcing the Horde scouts to abandon their original plans and fight desperately for survival.",al={"ironstone camp history","what happened here ironstone","ironstone camp background"},it="history",add=true},{q="Who lives in Ironstone Camp?",a="The camp is inhabited by a detachment of Horde soldiers, scouts, and overseers, including Moktar Krin. Cut off and pressured by the sudden silithid emergence, they remain entrenched on the rim of the flats, seeking able-bodied adventurers of the Horde to assist in repelling the encroaching insectoid threat.",al={"who is at ironstone camp","ironstone camp residents","who lives here ironstone"},it="residents",add=true},{q="Is Ironstone Camp dangerous?",a="Within the borders of the camp itself, Horde travelers will find safe harbor among their allies, though Alliance members will be met with immediate hostility. The surrounding terrain, however, is perilous. Aggressive silithid from the neighboring subterranean hives swarm the nearby digsite, threatening to overwhelm anyone who ventures out unprepared.",al={"is ironstone camp safe","ironstone camp dangers","threats at ironstone camp"},it="danger",add=true}},ang={["faction:Horde"]="The camp offers a strategic stopping point before heading out onto the open salt flats, though the local commanders are hard-pressed to eliminate the silithid swarm threatening their position.",["faction:Alliance"]="Alliance explorers heading toward the Shimmering Flats should keep their distance from the camp, which was originally established specifically to harass and purge the Bael'dun dwarven diggers."},kw={"horde outpost","ironstone camp","moktar krin","rustmaul digsite","shimmering flats","silithid","thousand needles"},rel={"subzone:shimmering-flats","zone:thousandneedles","topic:horde"},src={"Ironstone Camp"}}
E["subzone:mirage-raceway"] = {t="subzone",n="Mirage Raceway",z="thousandneedles",s="The Mirage Raceway is an impromptu engineering proving ground situated in the shimmering salt flats of Thousand Needles. Founded on the heated rivalry between goblin tinkerer Pozzik and gnome engineer Fizzle Brassbolts, it pits high-speed rocket cars against one another across the baked earth. The track serves as a neutral gathering place where members of both the Alliance and Horde come to wager, tinker, and cheer on their favored machines.",h="The Mirage Raceway is an impromptu engineering proving ground situated in the shimmering salt flats of...",sec={{t="Speed, Salt, and Rivalry",b="Sprawled across the vast white desert floor of the Shimmering Flats, the Mirage Raceway was born out of an unrelenting grudge match between two master tinkerers: the goblin Pozzik and the gnome Fizzle Brassbolts. Determined to settle once and for all whose race possesses superior technical ingenuity, the two constructed custom rocket-powered drag cars and recruited rival crews to pit them against each other in daily high-velocity showdowns. The relentless competition has turned the barren flats into a bustling hub of invention, sabotage, and testing as each crew desperately looks for any mechanical advantage.",sp=0},{t="A Neutral Crossroads",b="The raceway draws supporters from both the Horde and Alliance. Spectators gather from across Kalimdor to cheer on either gnome precision or goblin firepower, while gamblers and shady opportunists thrive on the constant wagers placed on the results. Beyond the roar of rocket thrusters, the camps serve as a busy trading depot for travelers journeying between Thousand Needles and the blazing sands of Tanaris.",sp=0}},faq={{q="What is the Mirage Raceway?",a="The Mirage Raceway is an open-air rocket-car drag strip laid across the salt flats of Thousand Needles. It was built by rival engineers seeking to prove whether goblin or gnome mechanics are superior.",al={"what is mirage raceway","raceway purpose","shimmering flats track"},it="place"},{q="Who runs the races here?",a="The track is maintained jointly by the gnome engineer Fizzle Brassbolts and the goblin tinkerer Pozzik. Each operates a dedicated crew and workshop along the raceway to field competing rocket cars.",al={"who leads raceway","fizzle and pozzik","who built this track"},it="residents"},{q="Can Horde and Alliance both use this area?",a="Yes. Supporters from both factions gather at the raceway to cheer for their favorites, wager on races, and aid the rival engineering crews.",al={"is mirage raceway neutral","can alliance visit","can horde visit"}},{q="Why race out in the salt flats?",a="The flat, wide expanse of the Shimmering Flats provides a smooth, unobstructed surface ideal for rocket-propelled vehicles that require miles of room to reach top speeds and safely slow down.",al={"why thousand needles","why race on salt","why in shimmering flats"},it="why_here"},{q="What is the history of the Mirage Raceway?",a="The raceway was born from the fierce technological rivalry between the goblin Pozzik and the gnome Fizzle Brassbolts. Determined to prove which race possessed superior engineering, the two built high-speed rocket cars and assembled dedicated racing crews. Over time, their personal contest evolved into an organized spectacle, drawing daily competitions, seedy gamblers, and spectators from across both the Alliance and the Horde to watch the rival machines clash across the salt.",al={"mirage raceway history","how did mirage raceway start","origin of mirage raceway"},it="history",add=true},{q="Is the Mirage Raceway dangerous?",a="The raceway draws Alliance and Horde supporters to wager and watch the competitions. However, the machines themselves are volatile, experimental contraptions prone to catastrophic failure. Furthermore, stepping beyond the perimeter of the racing camp puts you right into the untamed Shimmering Flats, which are crawling with aggressive scorpids, basilisks, and hostile scavengers.",al={"is mirage raceway safe","mirage raceway danger","dangers at mirage raceway"},it="danger",add=true}},ang={["profession:Engineering"]="For tinkerers of any faction, the Raceway represents the ultimate clash between goblin risk-taking and gnomish meticulous design, offering field tests of raw speed, volatile fuel, and experimental vehicle parts.",["race:Gnome"]="Fizzle Brassbolts flies the banner of Gnomeregan here, relying on fellow gnomes and allies to prove that disciplined innovation easily outperforms reckless goblin combustion."},kw={"fizzle brassbolts","mirage raceway","pozzik","rocket car","shimmering flats","thousand needles"},rel={"npc:pozzik","npc:fizzle-brassbolts","zone:thousandneedles","topic:gnome","topic:goblin","subzone:gadgetzan"},src={"Mirage Raceway"}}
E["subzone:razorfen-downs"] = {t="subzone",n="Razorfen Downs",z="thousandneedles",s="Razorfen Downs is the ancestral capital and sacred burial labyrinth of the quilboar, carved deep into the colossal brambles bordering the southern Barrens and Thousand Needles. Once their holiest sanctuary, it has fallen under the sway of the undead Scourge, transforming into a festering bastion of necromancy.",h="Razorfen Downs is the ancestral capital and sacred burial labyrinth of the quilboar, carved deep into the...",sec={{t="A Sacred City Corrupted",b="Long revered as the ancestral capital city and burial grounds of the quilboar race, Razorfen Downs rests within the colossal petrified briars sprung from the fallen demigod Agamaggan. Legend holds that its arched entryway was carved directly from the Great Boar's very maw. For centuries, the high priests of the Death's Head tribe tended these deep, winding burrows and honored their revered dead. Yet despite its sacred standing among the boar-folk, the maze of bone and bramble has recently suffered a catastrophe far darker than any squabble over Barrens water.",sp=0},{t="The Scourge Reaches Kalimdor",b="Following the devastation of the Third War, the tendrils of the undead Scourge reached silently into southern Kalimdor. Led by the frost-wielding lich Amnennar the Coldbringer, agents of death infiltrated the thorn maze and subverted the Death's Head priesthood. Instead of honoring their ancestors, the quilboar now harbor rotting ghouls, skeletons, and necromancers within their sacred pens. The corruption here threatens to fester outward across the Barrens, turning the quilboar's holiest ground into a launchpad for the Scourge's ambitions in the west.",sp=1}},faq={{q="What is Razorfen Downs?",a="Razorfen Downs is the ancestral capital city and burial grounds of the quilboar race. Grown from the enormous thorn brambles formed by the fallen Ancient Agamaggan, it serves as the spiritual heart of quilboar culture and the headquarters of their high priesthood, the Death's Head tribe.",al={"what is the downs","razorfen downs lore","who lives in razorfen downs"},it="place"},{q="Why is the Scourge inside Razorfen Downs?",a="The lich Amnennar the Coldbringer arrived following the Third War to establish a Kalimdor stronghold for the Lich King. By corrupting the Death's Head priesthood and raising quilboar dead, Amnennar turned the labyrinthine thorn city into a hidden nest of necromantic power.",al={"why are there undead in razorfen downs","amnennar razorfen downs","scourge in razorfen"},it="threat"},{q="How does Razorfen Downs differ from Razorfen Kraul?",a="Razorfen Kraul is the primary military redoubt and living warren of the quilboar, ruled directly by the crone Charlga Razorflank. In contrast, the Downs is their traditional capital and sacred burial ground, deeper south, which has fallen under the sway of necromancy and Scourge control.",al={"difference between kraul and downs","downs vs kraul","kraul or downs"}},{q="Where is the entrance located?",a="The Downs is situated at the very southern border of the Barrens, overlooking the great drop into Thousand Needles. Its entrance is a natural arched fissure nestled into the towering, tangled brambles, reputed in myth to be carved from Agamaggan's gaping maw.",al={"downs entrance","where is razorfen downs","how to get into razorfen downs"},it="place",gp=true},{q="What happened at Razorfen Downs?",a="Razorfen Downs was once the proud capital and ancestral burial grounds of the quilboar, shaped from the colossal thorny vines said to have sprouted from the blood of the demigod Agamaggan. Following the Third War, however, tragedy struck the city. Agents of the Scourge infiltrated the thorn maze and spread their deadly plague. Led by the lich Amnennar the Coldbringer, the undead subjugated many of the Death's Head tribe, turning a sacred homeland into a festering bastion of undeath.",al={"razorfen downs history","what happened to razorfen downs","downs history lore"},it="history",add=true},{q="Who rules Razorfen Downs?",a="The stronghold has fallen under the iron grip of Amnennar the Coldbringer, a powerful Scourge lich sent to establish a foothold in southern Kalimdor. Beneath him serve the Death's Head quilboar, led by Death Speaker Blackthorn and corrupted high priests who have turned to necromancy, alongside hordes of mindless ghouls, skeletons, and other undead horrors.",al={"who runs razorfen downs","who leads razorfen downs","razorfen downs boss"},it="residents",add=true},{q="Is Razorfen Downs dangerous?",a="It is exceptionally dangerous. Unlike the feral tribes of Razorfen Kraul, the defenders here are bolstered by the chilling magic of the Scourge. Plagued quilboar, necromancers, and swarms of risen dead wander the tangled tunnels. Deep within waits Amnennar the Coldbringer, whose presence threatens to unleash the undead plague across all of the Barrens and Thousand Needles.",al={"how dangerous is razorfen downs","razorfen downs threats","is the downs safe"},it="danger",add=true}},ang={["faction:Horde"]="The quilboar are a constant thorn in the side of the Crossroads, but an outpost of the Lich King right on the edge of the Barrens is an existential menace that the Horde cannot afford to ignore.",["race:Undead"]="For the Forsaken, discovering a Scourge lich operating covertly on Kalimdor is a chilling reminder of the master they rebelled against, demanding swift and decisive eradication."},kw={"agamaggan","amnennar","coldbringer","death speaker blackthorn","death's head","downs","quilboar","razorfen downs","scourge"},rel={"zone:razorfenkraul","topic:quilboar","topic:scourge","topic:agamaggan","zone:thousandneedles","zone:barrens","topic:horde","quest:5052"},src={"Razorfen Downs"}}
E["subzone:roguefeather-den"] = {t="subzone",n="Roguefeather Den",z="thousandneedles",s="Roguefeather Den is a cavern nestled in the south-central reaches of Thousand Needles. Infested with ferocious screeching harpies, the cave serves as a fortified roost where the flock hoards scavenged provisions deep within its shadowed recesses.",h="Roguefeather Den is a cavern nestled in the south-central reaches of Thousand Needles.",sec={{t="A Roost in the Canyons",b="Carved into the sheer sandstone bluffs of southern Thousand Needles, Roguefeather Den is the foul nesting ground of local harpies. Known for their feral screeching and aggressive territorialism, the harpies treat the cavern as both a secure haven and a storehouse, vigilantly guarding the gathered food and stolen supplies they pile in the dark recesses at the back of the cave.",sp=0}},faq={{q="What is Roguefeather Den?",a="It is a small cavern located along the southern cliffs of Thousand Needles, serving as a roost and supply stockpile for the territorial Roguefeather harpies.",al={"what is this cave","roguefeather den info","where is roguefeather"},it="place"},{q="What creatures inhabit the cave?",a="The cavern is infested with hostile, screeching harpies who fiercely defend their nesting grounds and gathered food against any intruders.",al={"who lives in roguefeather den","mobs in roguefeather den"},it="residents"},{q="What is kept deep inside Roguefeather Den?",a="Deep in the back of the cavern, the harpies hoard stores of scavenged and stolen food, which they protect with relentless aggression.",al={"what is in the back of the cave","roguefeather food"},it="purpose"},{q="Is Roguefeather Den dangerous?",a="Yes, entering the den is exceptionally perilous. The cavern is cramped and overrun by aggressive, screeching harpies who fiercely protect their territory. Anyone venturing inside risks being swarmed in the dark tunnels, especially near the back of the cave where the flock zealously defends its hoarded supplies.",al={"is roguefeather den dangerous","roguefeather den dangers","how dangerous is roguefeather den"},it="danger",add=true}},ang={["faction:Horde"]="For Horde travelers making the long trek toward the Shimmering Flats, the aggressive flock inhabiting Roguefeather Den represents a persistent aerial and ambush threat along the southern canyon floor."},kw={"cavern","harpies","roguefeather","roguefeather den","roost","thousand needles"},rel={"zone:thousandneedles","quest:1089"},src={"Roguefeather Den"}}
E["subzone:rustmaul-dig-site"] = {t="subzone",n="Rustmaul Dig Site",z="thousandneedles",s="The Rustmaul Dig Site is a ruined excavation in the southern reaches of the Shimmering Flats. Originally established by the dwarven Explorers' League to unearth ancient ruins, the camp fell into tragedy when a Horde war party slaughtered the miners, after which a subterranean silithid swarm emerged. Now abandoned by mortals, the site crawls with hostile insectoids emerging from the caverns below.",h="The Rustmaul Dig Site is a ruined excavation in the southern reaches of the Shimmering Flats.",sec={{t="A Slaughter in the Salt",b="Prospectors from the Ironforge Explorers' League set up the Rustmaul Dig Site hoping to uncover forgotten artifacts buried beneath the salt flats. Their efforts were brutally cut short when an aggressive Horde war party, led by Moktar Krin, fell upon the camp and wiped out the dwarven excavators. However, the conquerors enjoyed no triumph. The violent clash apparently disturbed a dormant cave network beneath the site, releasing an endless horde of silithid insects that quickly overwhelmed and drove off the battered survivors.",sp=0},{t="The Awakening Swarm",b="Today, Rustmaul stands entirely lost to the surface races. What remains of the mining equipment and scaffolds is buried under skittering mandibles and alien carapaces. The surviving members of Moktar Krin's war party retreated north to Ironstone Camp, terrified by the unrelenting tide of insectoids that emerged after their attack.",sp=0}},faq={{q="What is the Rustmaul Dig Site?",a="It is an excavation camp in the Shimmering Flats within Thousand Needles. Dwarven explorers originally founded it to unearth ancient ruins, but it has since been overrun by deadly silithid swarms.",al={"what is rustmaul","rustmaul lore","shimmering flats dig site"},it="place"},{q="Who used to live and work here?",a="Prospectors and excavators from the dwarven Explorers' League originally operated the dig, uncovering artifacts and ruins buried beneath the salt flats.",al={"who dug rustmaul","who owned rustmaul","dwarves at rustmaul"},it="residents"},{q="Why is the dig site abandoned and full of bugs?",a="A Horde war party led by Moktar Krin assaulted the camp and slaughtered the dwarves. The commotion apparently disturbed a subterranean nest of silithid insects within the mine cave, unleashing a swarm that drove the surviving attackers away.",al={"what happened at rustmaul","why are there bugs at rustmaul","who attacked rustmaul"},it="ruin"},{q="Where did the surviving attackers go?",a="The battered remnants of Moktar Krin's Horde war party fled north across the flats to recuperate at Ironstone Camp, with messengers carrying warnings as far as Orgrimmar.",al={"where is moktar krin","survivors of rustmaul","ironstone camp connection"}},{q="What happened at the Rustmaul Dig Site?",a="Dwarven archaeologists from the Explorers' League were unearthing ancient ruins here when a Horde war party led by Moktar Krin ambushed them, slaughtering every dwarf at the site. The violent clash apparently disturbed a subterranean hive of silithid deep within the cave. A relentless swarm erupted from the depths, overwhelming and driving out the bloodied Horde raiders and claiming the entire excavation.",al={"rustmaul dig site history","what happened at rustmaul","rustmaul massacre"},it="history",add=true},{q="Is the Rustmaul Dig Site dangerous?",a="It is extremely hazardous. Ravenous silithid insects crawl throughout the trenches and infest the central cave in endless swarms. Any traveler who enters risks being swarmed and devoured by the hive, just as the battered surviving raiders were driven off by their sheer numbers.",al={"is rustmaul dangerous","rustmaul dig site threats","rustmaul danger"},it="danger",add=true}},ang={["race:Dwarf"]="For dwarves of Ironforge, Rustmaul is a tragic reminder of the hazards facing the Explorers' League, whose scholars were slaughtered here before the earth itself gave way to monstrous insects.",["faction:Horde"]="Though Moktar Krin's war party claimed victory over the dwarven excavators, an ancient, creeping silithid menace emerged after the battle that now threatens the entire region."},kw={"explorers' league","ironstone camp","moktar krin","rustmaul dig site","shimmering flats","silithid","thousand needles"},rel={"subzone:shimmering-flats","zone:thousandneedles","subzone:ironstone-camp","topic:explorers-league","topic:horde","zone:orgrimmar"},src={"Rustmaul Dig Site"}}
E["subzone:shimmering-flats"] = {t="subzone",n="Shimmering Flats",z="thousandneedles",s="The Shimmering Flats is an expansive salt flat lying at the southeastern tip of Thousand Needles, bordering the desert of Tanaris. Once the bed of an ancient lake, this sun-baked expanse is now famous for the high-speed mechanical rivalries of the Mirage Raceway and a harsh population of desert beasts.",h="The Shimmering Flats is an expansive salt flat lying at the southeastern tip of Thousand Needles, bordering...",sec={{t="A Bed of Salt and Speed",b="Stretching out under the blinding southern sun, the Shimmering Flats is a vast dried lakebed devoid of vegetation, dotted with the sun-bleached bones of turtles and even the wooden wreck of an ancient sailing vessel. Its sheer, unbroken level surface makes it the premier testing ground on Kalimdor for experimental vehicles. At the center of the flats lies the Mirage Raceway, where gnome and goblin tinkerers constantly clash to see whose rocket cars, gyrocopters, and engines can achieve the highest speeds—often resulting in fiery crashes and smoking craters across the white crust.",sp=0},{t="Hazards of the Salt",b="Beyond the roaring engines of the raceway, the basin is far from peaceful. Hardened basilisks, aggressive scorpids, and circling vultures prey upon anything that slows down on the open expanse. Further south, the ground grows treacherous around the Rustmaul Dig Site. Originally excavated by dwarven prospectors before being contested by the Horde, the quarry was entirely abandoned when picks cracked into subterranean tunnels, unleashing a swarm of vicious silithid into the southern edge of the flats.",sp=0}},faq={{q="Why is there a ruined ship out in the middle of the desert?",a="The Shimmering Flats was once a massive inland lake that dried up long ago. The wrecked vessel resting in the northern stretch of the flats is a remnant of that ancient body of water, left behind when the lake evaporated into the vast salt pan seen today.",al={"ship in shimmering flats","boat in salt flats","wrecked boat thousand needles"},it="history"},{q="Why are gnomes and goblins here together?",a="The unbroken, flat salt crust provides the perfect terrain for testing rocket cars and cutting-edge mechanical contraptions. Rather than fighting over territory, local gnomes and goblins established the Mirage Raceway to fuel their technological rivalry, endlessly trying to outdo each other in speed, engineering, and reckless bravado.",al={"raceway lore","why are they racing","gnomes and goblins salt flats"},it="residents"},{q="What happened to the dwarven dig site in the south?",a="The Rustmaul Dig Site was established by dwarven archaeologists, who were soon attacked by a Horde raiding party led by Moktar Krin. Then the diggers inadvertently broke into a subterranean silithid hive, releasing swarms of insectoid horrors that drove everyone out and overran the southern flats.",al={"rustmaul dig site lore","what happened to rustmaul","bugs in salt flats"}},{q="Where does the road through the Shimmering Flats lead?",a="Following the tracks southeast across the salt pan leads directly to the mountain pass that opens into the vast desert of Tanaris and the neutral port of Gadgetzan.",al={"where does shimmering flats go","how to get to tanaris","exit to tanaris"}},{q="What are the Shimmering Flats?",a="The Shimmering Flats is a vast, blinding white salt flat situated at the southeastern end of Thousand Needles, bordering the desert of Tanaris. It is a completely dried-out lakebed entirely devoid of plant life, offering an immense, flat expanse where inventors test their wildest creations and aggressive desert beasts roam the cracked earth.",al={"what is shimmering flats","shimmering flats lore","about shimmering flats"},it="place",add=true},{q="Is the Shimmering Flats dangerous?",a="Despite its barren appearance, the flats are quite perilous. Deadly native predators like salt basilisks, scorpids, and vultures prowl the open basin, while the volatile rocket cars and testing accidents of goblin and gnome racers leave fiery debris everywhere. Furthermore, a subterranean silithid hive has recently erupted in the southern reaches, overrunning an ancient dwarven excavation.",al={"is shimmering flats dangerous","shimmering flats hazards","how dangerous is shimmering flats"},it="danger",add=true},{q="Why is it called the Shimmering Flats?",a="The name comes from the blinding visual effect of the sun beating down across the ancient, crystallized salt bed. The harsh glare off the white, arid mineral crust creates a dazzling, shimmering mirage across the horizon, visible for miles across the dried basin.",al={"why shimmering flats","shimmering flats name origin","why is it called shimmering flats"},it="name",add=true}},ang={["profession:Engineering"]="The salt flats are a pilgrimage site for engineers, littered with scrap, fuel experiments, and high-speed vehicular trial runs fueled by the endless rivalry between goblin and gnomish machinists.",["race:Gnome"]="Out on the Mirage Raceway, gnomish pilots and mechanostriders boldly defend gnomish engineering pride against the volatile, explosive designs of their goblin rivals."},kw={"mirage raceway","pozzik","rustmaul","salt flats","shimmering flats","silithid","tanaris","thousand needles"},rel={"subzone:mirage-raceway","zone:thousandneedles","zone:tanaris","subzone:rustmaul-dig-site","npc:pozzik","quest:1179","quest:5762"},src={"Shimmering Flats"}}
E["subzone:splithoof-crag"] = {t="subzone",n="Splithoof Crag",z="thousandneedles",s="Splithoof Crag is a fortified settlement of the Galak centaur, tucked along the northern cliffs of Thousand Needles. It serves as one of the tribe's major enclaves alongside the high mesas, guarding the entrance to Splithoof Hold. Travelers traversing the canyon floor must contend with aggressive Galak patrols roaming near the bluffs.",h="Splithoof Crag is a fortified settlement of the Galak centaur, tucked along the northern cliffs of Thousand...",sec={{t="A Galak Stronghold",b="Nestled against the sheer northern rock face of Thousand Needles, Splithoof Crag sits just east of the towering Darkcloud Pinnacle. It is an established enclave of the Galak centaur, complete with crude tent encampments and dirt pathways cutting through the crags. At the heart of the village against the cliffside lies Splithoof Hold, a subterranean cavern holding the Cloven Hoof, an ancient relic of the centaur safeguarded by a sacred brazier.",sp=0},{t="Defending the Caverns",b="The Galak fiercely contest this corner of the canyon, clashing with any travelers, Horde expeditions, or tauren scouting parties wandering beneath their bluffs. While the Grimtotem occupy the soaring pinnacles nearby, the centaur hold firm control of this canyon ravine and the caverns burrowed deep beneath the stone.",sp=0}},faq={{q="Who lives in Splithoof Crag?",a="The settlement belongs to the Galak centaur tribe, one of the prominent clans inhabiting Thousand Needles alongside the hostile Grimtotem tauren.",al={"who is at splithoof crag","splithoof crag mobs","centaur in splithoof crag"},it="residents"},{q="Where is Splithoof Crag located?",a="It lies along the northern canyon wall of Thousand Needles, situated directly east of Darkcloud Pinnacle.",al={"where is splithoof crag","splithoof crag location"},it="place",gp=true},{q="What is inside Splithoof Hold?",a="Splithoof Hold is the central cavern of the village. Deep within its chambers, the Galak guard the Cloven Hoof, an ancient tribal artifact shielded by a sacred flame burning in an ancient brazier.",al={"what is splithoof hold","cave in splithoof crag"}},{q="Are the centaur here allied with the nearby Grimtotem?",a="No. The Galak centaur and the Grimtotem tauren on Darkcloud Pinnacle are bitter territorial rivals, fighting for dominance over this stretch of the canyon.",al={"grimtotem and galak","centaur and tauren relation"},it="allies"},{q="What is Splithoof Crag?",a="Splithoof Crag is a fortified settlement carved into the northern rock walls of Thousand Needles, situated just east of Darkcloud Pinnacle. It serves as a major stronghold for the local Galak centaur, featuring clustered encampments along the canyon floor and an inner cavern known as Splithoof Hold.",al={"what is this place","splithoof crag info","about splithoof crag"},it="place",add=true},{q="Is Splithoof Crag dangerous?",a="It is extremely hazardous for outsiders. The Galak centaur are fiercely aggressive, territorial, and attack intruders on sight. Furthermore, the settlement's inner sanctum, Splithoof Hold, is heavily defended to protect their sacred relics.",al={"is it safe here","danger splithoof crag","splithoof crag threats"},it="danger",add=true}},ang={["race:Tauren"]="The long-standing hostility between tauren and centaur makes Splithoof Crag an immediate concern for Horde scouts monitoring hostile activity throughout Thousand Needles.",["faction:Horde"]="Controlling the passage beneath the crags is vital for ensuring secure travel between the southern Barrens, Freewind Post, and the Shimmering Flats."},kw={"centaur","cloven hoof","darkcloud pinnacle","galak","splithoof crag","splithoof hold","thousand needles"},rel={"subzone:splithoof-hold","zone:thousandneedles","topic:centaur","subzone:darkcloud-pinnacle"},src={"Splithoof Crag"}}
E["subzone:splithoof-hold"] = {t="subzone",n="Splithoof Hold",z="thousandneedles",s="Splithoof Hold is a deep cavern stronghold carved into the stone of Splithoof Crag in Thousand Needles. Held by the Galak centaur tribe, the cavern serves as a fortified den and houses the Ancient Brazier, a site holding an eternally burning sacred flame.",h="Splithoof Hold is a deep cavern stronghold carved into the stone of Splithoof Crag in Thousand Needles.",sec={{t="A Centaur Bastion",b="Tucked away inside Splithoof Crag, Splithoof Hold serves as a fortified redoubt for the Galak centaur. Unlike the windswept canyon floor, this enclosed cave offers them shelter, defensible chokepoints, and a secure sanctuary from rival tribes and travelers passing through the Needles.",sp=0},{t="The Sacred Flame",b="Deep within the shadowed recesses of the hold lies an ancient brazier cradling the Sacred Flame. This mystic fire burns incessantly, serving as a focal point of power and ritual reverence for the centaur and an object of deep curiosity for spiritual wanderers across the canyon.",sp=0}},faq={{q="Where is Splithoof Hold located?",a="Splithoof Hold is situated within the crags and ramparts of Splithoof Crag, along the northern cliffs of Thousand Needles. It is entered through a cave opening nestled inside the main centaur settlement.",al={"splithoof hold location","where is splithoof hold","how to find splithoof hold"},it="place",gp=true},{q="Who controls Splithoof Hold?",a="The cavern is held by the Galak centaur tribe, who aggressively defend the cave against outsiders, beast incursions, and the nearby tauren of Freewind Post.",al={"who lives in splithoof hold","splithoof hold mobs","who owns splithoof hold"},it="residents"},{q="What is inside the hold?",a="Beyond hostile Galak centaur defenders, the cave houses the Ancient Brazier, an artifact that keeps the mystical Sacred Flame burning eternally within the depths of the rock.",al={"what is in splithoof hold","ancient brazier location","sacred flame splithoof"},it="place"},{q="What is Splithoof Hold?",a="Splithoof Hold is a cavern stronghold carved into the rock of Splithoof Crag in Thousand Needles. The fierce Galak centaur tribe claimed the natural cave and adapted it into a fortified base within the canyon, keeping their sacred relics and clan hearth sheltered inside.",al={"what is splithoof hold","splithoof hold lore","about splithoof hold"},it="place",add=true},{q="Is Splithoof Hold dangerous?",a="Splithoof Hold is extremely perilous to outsiders. It serves as a major redoubt for the aggressive Galak centaur, who fiercely guard their cavern, warbands, and the eternal Sacred Flame kept within its depths from any trespassers.",al={"is splithoof hold dangerous","splithoof hold danger","threat splithoof hold"},it="danger",add=true}},ang={["race:Tauren"]="The Galak centaur remain sworn blood enemies of the tauren, making any stronghold they maintain in Thousand Needles an immediate threat to the peace of Freewind Post.",["class:Shaman"]="The existence of an eternal flame burning deep within a dark stone cavern draws the attention of any spiritualist attuned to the primal mysteries of elemental fire."},kw={"ancient brazier","galak centaur","sacred flame","splithoof crag","splithoof hold","thousand needles"},rel={"subzone:splithoof-crag","zone:thousandneedles","topic:centaur","quest:1195"},src={"Splithoof Hold"}}
E["subzone:tahonda-ruins"] = {t="subzone",n="Tahonda Ruins",z="thousandneedles",s="The Tahonda Ruins are the sun-bleached remnants of an ancient tauren settlement swallowed by the salt and sand of the Shimmering Flats. Little is remembered of the villagers who once lived here, and dangerous Saltstone basilisks now stalk among the decaying tent poles and shredded leather.",h="The Tahonda Ruins are the sun-bleached remnants of an ancient tauren settlement swallowed by the salt and...",sec={{t="Sunken beneath the Salt",b="Situated in the southern reaches of the Shimmering Flats near the pass into Tanaris, the Tahonda Ruins stand as a somber monument to an abandoned tauren past. The village fell long ago, its weathered structures gradually engulfed by shifting white salt crusts. While some suspect the local Saltstone basilisks drove the inhabitants away, odd clues linger on the surviving structures. Two distinct sets of three parallel tears cut through the leather of a ruined lodge, suggesting the village met a violent end at the claws of powerful predators or hostile invaders before the desert claimed what remained.",sp=0}},faq={{q="What were the Tahonda Ruins originally?",a="Tahonda was once a tauren village built upon the dry expanse of the Shimmering Flats. Over time, the village fell into ruin and was gradually swallowed by shifting sands and salt crusts.",al={"what is tahonda ruins","who built tahonda","tahonda ruins history"},it="place"},{q="Why was the village abandoned?",a="No written history preserves the exact fate of the village. The ruins are currently overrun by vicious Saltstone basilisks, which may have driven the settlers out. However, deep three-clawed tears raked across the surviving leather lodges suggest a sudden, violent attack.",al={"why is tahonda ruined","what destroyed tahonda","what happened to tahonda"},it="ruin"},{q="What creatures live in the ruins now?",a="The remnants of the village are thoroughly infested with hostile Saltstone basilisks that sun themselves among the rotting wooden poles and tattered hide shelters.",al={"tahonda mobs","what is at tahonda ruins","tahonda beasts"},it="residents"},{q="What happened to the Tahonda Ruins?",a="Very little is recorded of Tahonda's past. It was once an ancient tauren settlement that eventually collapsed and was gradually buried by the shifting sands of the Shimmering Flats. While the encroaching Saltstone basilisks may have forced the villagers out, claw marks torn across the weathered leather dwellings suggest the settlement met a violent end at the hands of savage beasts or hostile raiders before it was lost to time.",al={"tahonda ruins history","what happened at tahonda ruins","tahonda ruins story"},it="history",add=true},{q="Are the Tahonda Ruins dangerous?",a="Yes. The sunken remnants of the village have become a breeding ground for aggressive Saltstone basilisks. Wandering through the half-buried leather tents and collapsed poles leaves you exposed to these stone-gazing predators, who make the desolate corner of the salt flats perilous for unwary travelers passing toward Tanaris.",al={"is tahonda ruins dangerous","tahonda ruins threats","dangers in tahonda ruins"},it="danger",add=true}},ang={["race:Tauren"]="Finding a forgotten tauren settlement sinking beneath the salt of Thousand Needles is a poignant reminder of the dangers your nomadic ancestors faced wandering Kalimdor."},kw={"saltstone basilisks","shimmering flats","tahonda","tahonda ruins","tauren village","thousand needles"},rel={"subzone:shimmering-flats","zone:thousandneedles","topic:tauren","zone:tanaris"},src={"Tahonda Ruins"}}
E["subzone:weathered-nook"] = {t="subzone",n="Weathered Nook",z="thousandneedles",s="Tucked away along the northern cliffside of Thousand Needles, the Weathered Nook is a secluded cleft and shelter perched high above the canyon floor. Overlooking the vast sea of stone spires, it serves as a modest home and retreat for solitary tauren dwellers seeking quiet contemplation away from bustling settlements.",h="Tucked away along the northern cliffside of Thousand Needles, the Weathered Nook is a secluded cleft and...",sec={{t="Haven on the Cliffs",b="Carved into the sheer sandstone wall north of Freewind Post, the Weathered Nook is easily missed by travelers passing along the canyon basin below. A natural ramp winds up the cliff face, leading to a sheltered ledge and cave out of the prevailing winds. Rather than housing a military outpost or large settlement, the nook serves as a humble homestead for solitary wanderers like Dorn Plainstalker and Prate Cloudseer, offering safety, seclusion, and a sweeping view across the windswept needle plateaus.",sp=0}},faq={{q="Where is the Weathered Nook located?",a="The nook is nestled along the northern cliff wall of Thousand Needles. From Freewind Post, travel north until you reach the towering rock face, then follow the cliffs east until you find a winding ramp leading up the mesa wall.",al={"how to find weathered nook","weathered nook location","where is nook"},gp=true},{q="Who lives in the Weathered Nook?",a="The shelter is home to Dorn Plainstalker and Prate Cloudseer, solitary tauren who have chosen this remote ledge above the canyon rather than dwelling atop the crowded towers of Freewind Post.",al={"who is here","weathered nook residents","npcs in nook"},it="residents"},{q="Is the Weathered Nook affiliated with the Horde?",a="While the residents are tauren and align naturally with their kindred, the nook is not a formal Horde garrison. It is a humble personal camp and dwelling tucked quietly into the wilderness.",al={"is this a horde camp","horde weathered nook"},it="side"},{q="What is the Weathered Nook?",a="The Weathered Nook is a small, secluded shelter carved into the northern cliff walls overlooking the canyons of Thousand Needles. Far from the bustling pathways of Freewind Post and the Shimmering Flats, this quiet crevice serves as a humble encampment for travelers seeking respite from the harsh elements and wandering beasts of the canyon floor.",al={"weathered nook what is","what is weathered nook","weathered nook info"},it="place",add=true},{q="Is the Weathered Nook dangerous?",a="The nook itself is relatively tranquil compared to the surrounding canyon floor, serving as a sanctuary for its inhabitants. However, the path along the towering bluffs can be treacherous, and aggressive beasts such as prowling cougars, wyverns, and centaur raiders roam the rocky heights and passes nearby.",al={"weathered nook dangerous","is weathered nook safe","threats at weathered nook"},it="danger",add=true}},ang={["race:Tauren"]="For tauren travelers, the Weathered Nook represents the quiet spirit of self-reliance, offering a peaceful vantage point across the canyon to commune with the elements away from the busy bridges of Freewind Post.",["faction:Horde"]="Horde wanderers exploring the heights of the canyon walls will find friendly kindred sheltering here along the northern cliffs."},kw={"cave","cliff","dorn plainstalker","freewind post","prate cloudseer","thousand needles","weathered nook"},rel={"npc:dorn-plainstalker","zone:thousandneedles","subzone:freewind-post"},src={"Weathered Nook"}}
E["subzone:weazel-s-crater"] = {t="subzone",n="Weazel's Crater",z="thousandneedles",s="Weazel's Crater is a deep gouge carved into the hard salt of the northern Shimmering Flats. Its origins are mysterious, and Saltstone basilisks inhabit the hollow.",h="Weazel's Crater is a deep gouge carved into the hard salt of the northern Shimmering Flats.",sec={{t="A Volatile Legacy",b="Across the blinding white expanse of the Shimmering Flats, experimental goblin and gnome rocket-cars constantly push the boundaries of mechanical sanity. Debris, scorched earth, and impact hollows litter the plains, but Weazel's Crater stands out for its sheer size and depth. The crater's origins are unknown. Today, the mechanical wreckage has largely settled, and the hollow has been claimed as a sunning pit by aggressive Saltstone basilisks.",sp=0}},faq={{q="What caused Weazel's Crater?",a="The crater's origins are unknown. No cause is established.",al={"how was weazel's crater formed","weazels crater origin","why is there a crater here"},it="history"},{q="What lives in the crater now?",a="The depression is currently inhabited by dangerous Saltstone basilisks, which lurk along the rocky edges and bottom of the pit.",al={"weazels crater mobs","what is inside the crater"},it="residents"},{q="What is Weazel's Crater?",a="Weazel's Crater is a large, deep depression gouged into the northern expanse of the Shimmering Flats in Thousand Needles. While it resembles an impact site, it sits right along the paths where goblins and gnomes test their volatile, rocket-powered racing machines, making it a prominent and hazardous landmark amid the salt desert.",al={"weazels crater","what is this crater","weazel crater shimmering flats"},it="place",add=true},{q="Is Weazel's Crater dangerous?",a="Yes. Beyond the risk of reckless rocket racers careening across the flats, the crater itself has become an infested den for aggressive Saltstone basilisks. Anyone stepping down into the hollow risks being turned to stone or mauled by the territorial beasts lurking within.",al={"is weazels crater dangerous","weazel crater threats","danger weazels crater"},it="danger",add=true}},ang={["profession:Engineering"]="The deep hollow lies amid the experimental racing machines and debris of the Shimmering Flats. Engineers visiting the speedway have good reason to study the hazardous terrain."},kw={"gnome engineering","goblin raceway","saltstone basilisks","shimmering flats","thousand needles","weazel's crater"},rel={"subzone:shimmering-flats","zone:thousandneedles","topic:goblin","topic:gnome"},src={"Weazel's Crater"}}
E["subzone:whitereach-post"] = {t="subzone",n="Whitereach Post",z="thousandneedles",s="Whitereach Post is a small Horde encampment nestled along the dusty canyon path in Thousand Needles. Serving as a minor waystation near Camp E'thok, it offers respite and watchful eyes over the harsh desert highway. For travelers moving between Feralas and the salt flats, it stands as an outpost of Horde safety beneath the looming sandstone pillars.",h="Whitereach Post is a small Horde encampment nestled along the dusty canyon path in Thousand Needles.",sec={{t="A Waystation in the Canyons",b="Perched along the beaten path winding through the depths of Thousand Needles, Whitereach Post is one of several modest Horde footholds carved out of the rugged landscape. Stationed in close proximity to Camp E'thok, the post helps maintain a reliable presence along the canyon floor, monitoring travel between the windswept mesas. While not as fortified as the great lift or major tribal settlements, it serves as an indispensable stop for couriers, scouts, and adventurers traversing the contested wastes.",sp=0}},faq={{q="What is Whitereach Post?",a="Whitereach Post is a minor Horde outpost located along the primary canyon path in Thousand Needles, situated not far from Camp E'thok.",al={"whitereach","whitereach camp","where is whitereach post"},it="place"},{q="Which faction controls Whitereach Post?",a="It is controlled by the Horde, primarily maintained by tauren scouts keeping watch over the gorge trails.",al={"is whitereach horde","whitereach faction"},it="side"},{q="Who can be found stationed here?",a="The post is manned by local Horde scouts and wanderers, including the tauren Kanati Greycloud, who watches over the canyon passage.",al={"whitereach npcs","who lives at whitereach post"},it="residents"}},ang={["faction:Horde"]="Whitereach Post represents a vital resting point and scouting presence for Horde travelers journeying through the perilous canyons of Thousand Needles.",["race:Tauren"]="Tauren scouts help secure this roadside camp, ensuring that tribesfolk moving between Mulgore, Feralas, and the Shimmering Flats have a safe place to rest."},kw={"camp e'thok","horde outpost","kanati greycloud","tauren","thousand needles","whitereach post"},rel={"zone:thousandneedles","topic:horde","subzone:camp-e-thok","npc:kanati-greycloud"},src={"Whitereach Post"}}
E["subzone:windbreak-canyon"] = {t="subzone",n="Windbreak Canyon",z="thousandneedles",s="Windbreak Canyon is a winding gorge along the northern side of Thousand Needles, situated between Freewind Post and the Shimmering Flats. Famous for its harsh drafts and jagged stone, it is heavily infested with nesting wind serpents. Travelers passing along the main road must tread carefully near its mouth to avoid being hunted from above.",h="Windbreak Canyon is a winding gorge along the northern side of Thousand Needles, situated between Freewind...",sec={{t="A Serpent Nest in the Needles",b="Carved into the sheer northern walls of the canyon floor, Windbreak Canyon spans a large stretch of territory east of Freewind Post. Rather than offering shelter, the ravine channels whistling winds between the rock spires, creating ideal perches for feral wind serpents. The predators lay their clutches along the stone ledges and strike at unwary travelers drifting off the main road. Those braving the canyon interior will also find the winding trails that climb upward toward the Weathered Nook.",sp=0}},faq={{q="Where is Windbreak Canyon?",a="Windbreak Canyon lies on the northern side of Thousand Needles, roughly between Freewind Post and the eastern approach to the Shimmering Flats.",al={"windbreak canyon location","where is windbreak canyon","windbreak map"},it="place",gp=true},{q="What creatures live in Windbreak Canyon?",a="The canyon is dominated by aggressive wild wind serpents that nest among the crags and defend their clutches from intruders.",al={"windbreak monsters","what is in windbreak canyon","windbreak mobs"},it="residents"},{q="Where does the trail inside the canyon lead?",a="Following the canyon's rising interior trails leads travelers toward the Weathered Nook nestled in the cliffs above.",al={"windbreak path","trail in windbreak canyon","where does windbreak go"},gp=true},{q="What is Windbreak Canyon?",a="Windbreak Canyon is a sprawling, rugged gorge nestled in Thousand Needles. Stretching across much of the northern expanse between Freewind Post and the Shimmering Flats, the canyon is best known for its dense population of nesting wind serpents and the winding trail leading up to the Weathered Nook.",al={"what is windbreak canyon","windbreak canyon overview","tell me about windbreak canyon"},it="place",add=true},{q="Is Windbreak Canyon dangerous?",a="Yes. The gorge is teeming with wild wind serpents guarding their nests along the rocky floor and canyon walls. Anyone traversing the canyon toward the Weathered Nook must stay alert, as these territorial beasts strike quickly against any intruders who stray too close to their brood.",al={"is windbreak canyon dangerous","dangers of windbreak canyon","windbreak canyon threats"},it="danger",add=true}},ang={["class:Hunter"]="The wind serpents nesting throughout the canyon provide wilderness hunters an ideal opportunity to study and tame agile, lightning-spitting beasts."},kw={"freewind post","thousand needles","weathered nook","wind serpents","windbreak canyon"},rel={"zone:thousandneedles","subzone:freewind-post","subzone:weathered-nook","subzone:shimmering-flats"},src={"Windbreak Canyon"}}
E["zone:thousandneedles"] = {t="zone",n="Thousand Needles",z="thousandneedles",s="Thousand Needles is a sprawling canyon of sheer sandstone pillars and sunbaked salt pans in southern Kalimdor. Tauren tribes cling to settlements atop towering mesas to escape aggressive centaur packs, while gnomish and goblin tinkerers run high-speed rocket cars across the dried-up seabed of the Shimmering Flats.",h="Thousand Needles is a sprawling canyon of sheer sandstone pillars and sunbaked salt pans in southern Kalimdor.",sec={{t="A Forest of Stone",b="Before the Great Sundering shattered ancient Kalimdor, this territory was a lush river canyon fed by inland waterways flowing out toward the sea. The cataclysm tore the continent apart, thrusting the riverbed above the water table and altering the river's path until only dry stone and sandstone spires remained. Today, dozens of slender cylindrical columns rise from the canyon floor like a petrified forest. Tauren settled on the summits, stringing precarious rope bridges between peaks to establish villages out of reach of the hostile centaur marauders patrolling the shadow-draped canyon floor below.",sp=0},{t="Peril on the Mesas",b="Atop the needle-like spires, life is far from peaceful. At Freewind Post, tauren loyal to the Horde contend not only with predatory wind serpents and wyverns from Highperch, but also with their treacherous kin: the militant Grimtotem clan entrenched at Darkcloud Pinnacle. Cliffwatcher Longhorn oversees the defense of the plateau, seeking bold fighters to strike at Grimtotem agitators and secure the fragile bridges linking the peaks. To the north, the enormous mechanical winches of the Great Lift carry travelers down from the southern Barrens, though crossing the canyon floor remains a deadly gambit.",sp=0},{t="The Mirage Raceway",b="To the southeast, the canyon walls peel back into the Shimmering Flats, an enormous, desiccated salt pan sitting below sea level. In this harsh, blinding white expanse, gnomes and goblins maintain an uneasy neutrality around the Mirage Raceway. Rival engineers Pozzik and Fizzle Brassbolts race experimental rocket cars across the hard salt to settle which race possesses technological superiority. The pit stop attracts scoundrels, swindlers like Kravel Koalbeard, and hunters hunting the hardy scorpions, turtles, and basilisks that roam the searing basin.",sp=0}},faq={{q="How did Thousand Needles get its name?",a="The zone is named after the dozens of massive, cylindrical sandstone spires that erupt from the canyon bottom. Originally carved by rushing river currents before the Great Sundering, these geological towers now resemble a forest of giant needles.",al={"why is it called thousand needles","needle pillars origin","spires lore"},it="name"},{q="How do you get down into Thousand Needles from the Barrens?",a="Travelers take the Great Lift, an immense double-car elevator operated by Horde guards on the southern border of the Barrens. Stepping off the edge is fatal, so waiting for the platform is essential. Alliance travelers can also hike in from the west via Thalanaar in Feralas.",al={"how to get to thousand needles","great lift entrance","elevator to needles"},it="arrival",gp=true},{q="Why do the tauren live on top of the mesas?",a="Centaur warbands once pushed the nomadic tauren nearly to extinction. Building outposts like Freewind Post atop inaccessible stone pillars kept them safe from ground charges. They connected the mesas using wooden suspension bridges, allowing high-altitude travel above the predators and raiders below.",al={"why are tauren on pillars","freewind post history","tauren high ground"},it="residents"},{q="What is the Mirage Raceway?",a="The Mirage Raceway is an engineering proving ground on the Shimmering Flats salt pan. Gnomish and goblin tinkerers run experimental rocket-propelled racecars across the flat salt bed to settle their ongoing rivalry over which race builds the finest machinery.",al={"salt flats track","gnome goblin race","rocket car track"}},{q="What is the Grimtotem presence in the canyon?",a="The Grimtotem clan occupies Darkcloud Pinnacle, a fortified cluster of spires directly opposing Freewind Post. Unlike the rest of the tauren tribes who pledged to the Horde, the Grimtotem actively attack other tauren and conspire to seize dominance over the mesas.",al={"grimtotem thousand needles","darkcloud pinnacle tauren","evil tauren needles"},it="threat"},{q="What are the Shimmering Flats?",a="The Shimmering Flats are a vast, dried lakebed east of the canyon mesas. The salt crust formed when the ancient inland sea evaporated after the Sundering. The searing heat, blinding white salt, and harsh predators make it an inhospitable desert used mainly for high-speed vehicular testing.",al={"salt pan","white desert needles","eastern desert"},it="place"},{q="What is Thousand Needles?",a="Thousand Needles is a vast, arid canyon dividing central and southern Kalimdor. Its canyon floor is thick with towering sandstone spires that stretch toward the sky like a petrified forest, linked above by delicate rope and wood bridges. In the east, the canyon gives way to the Shimmering Flats, a blinding white salt pan.",al={"what is this place","about thousand needles","tell me about thousand needles"},it="place",add=true,nx={8}},{q="Why is it all canyons and pillars?",a="Ages ago, before the Great Sundering, this region was a verdant river canyon carved out by rushing waters flowing eastward from Feralas into an inland sea. When the world shattered, the cataclysm thrust the riverbed upward and altered the river's course. Deprived of water, the land dried out, leaving behind towering sandstone pillars and a parched salt bed.",al={"why are there spires","how did the needles form","why sandstone pillars"},it="origin",add=true},{q="Is Thousand Needles dangerous?",a="It is quite dangerous. Barbaric Galak centaur patrol the canyon floor in raiding bands, while predatory vultures, scorpids, and rogue harpies haunt the cliffs. Even the rope bridges between high pinnacles carry peril, as birds of prey frequently swoop down upon unwary travelers or damage the spans.",al={"how dangerous is thousand needles","dangers here","is it safe"},it="danger",add=true},{q="Why did the Horde send me to Thousand Needles?",a="The Horde maintains a vital presence here to aid the local tauren tribes who are under relentless assault. Freewind Post stands as a critical bastion connecting the Barrens with the southern deserts, and the Horde needs brave champions to drive back marauding centaur and quell internal threats.",al={"horde mission thousand needles","why am i here horde","what does horde want here"},it="arrival",add=true,nx={11}},{q="Is this tauren land?",a="Yes. The barren canyons and high mesas of Thousand Needles have traditionally been the ancestral territory of several tauren tribes for countless generations, though vicious centaur clans pushed them to the brink of survival before the Horde arrived.",al={"do tauren own thousand needles","tauren territory","is this shu'halo land"},it="ties",add=true},{q="What is Freewind Post?",a="Freewind Post is the primary Horde outpost in Thousand Needles. Built atop a massive mesa high above the valley floor, it features wooden elevators, a flight tower, and a network of suspension bridges reaching adjacent pinnacles.",al={"freewind post","what is freewind","freewind village"},it="place",add=true},{q="Who are the Galak centaur and why are they attacking us?",a="The Galak tribe are the local centaur who claim the canyon floor. Like all centaur, they are fiercely territorial, nomadic, and violent. They hunt down any travelers passing through the gorges and seek to eradicate the tauren settlements completely.",al={"galak centaur","why centaur attack","galak tribe"},it="threat",add=true,nx={14}},{q="Why do they hate the tauren?",a="The enmity between tauren and centaur is ancient and unrelenting. For generations across the plains of Kalimdor, roving centaur hunted tauren for sport and launched brutal, unprovoked wars that kept the peaceful tribes constantly on the run.",al={"why do centaur hate tauren","centaur tauren feud","centaur grudge"},it="conflict",add=true},{q="Why are goblins and gnomes racing rocket cars in the desert?",a="The flat, open salt of the Shimmering Flats provides the perfect proving ground for testing high-speed engines. Gnomes and goblins established the Mirage Raceway to permanently settle the long-standing dispute over which race possesses superior engineering.",al={"why racing cars","goblin gnome race","rocket car rivalry"},it="other",add=true},{q="What's the deal with Darkcloud Pinnacle and those secret notes?",a="Darkcloud Pinnacle is the Grimtotem tribe's heavily guarded stronghold on the mesas east of the Great Lift. Secret correspondence discovered there reveals covert contact between Grimtotem leaders like Arnak Grimtotem and an unknown dark power, suggesting treacherous ambitions far beyond simple tribal feuds.",al={"darkcloud pinnacle notes","grimtotem notes","darkcloud pinnacle mystery"},sp=1,it="purpose",add=true,nx={17}},{q="What are the Grimtotem planning?",a="The Grimtotem fundamentally reject Cairne Bloodhoof's leadership and the cultural shifts brought by joining the Horde. They seek to depose Cairne, undermine Horde authority, and even consort with sinister powers and summon entities of vengeance to assert their dominance.",al={"grimtotem plan","what do grimtotem want","grimtotem conspiracy"},sp=1,it="motive",add=true},{q="What is Highperch and why do we want wyvern eggs?",a="Highperch is the ancestral nesting ground of wild wyverns in Thousand Needles. Tauren from Freewind Post climb to these high perches to gather fertile wyvern eggs so they can be carefully raised and trained as loyal flying mounts for the Horde.",al={"highperch wyverns","why collect wyvern eggs","highperch eggs"},it="purpose",add=true},{q="How did I end up in Thousand Needles?",a="Most travelers arrive from the north by riding south through the Barrens past Camp Taurajo, eventually reaching the sheer cliff edge where the massive tauren-engineered Great Lift lowers you straight down into the canyon floor. Alternatively, adventurers trekking eastward through the dense forests of Feralas enter the western gorge by foot, while daring explorers braving the perils of Dustwallow Marsh or sailing into Theramore slip through the contested gaps. A long overland march north from the deserts of Tanaris also brings you directly into the sprawling salt expanse of the Shimmering Flats.",al={"how did i get here","how do i reach thousand needles","getting to thousand needles"},it="arrival",add=true},{q="What am I supposed to be doing in Thousand Needles?",a="Your presence here depends on your allegiances and ambitions. Horde champions are tasked with aiding Freewind Post: pushing back the Galak centaur bands that roam the canyon floor, monitoring harpy roosts, collecting wyvern eggs from Highperch, and combating the treacherous Grimtotem tribe entrenched atop Darkcloud Pinnacle. For unaligned wanderers and Alliance travelers, the dramatic expanse serves as a hazardous overland crossroads between central and southern Kalimdor, leading toward the Shimmering Flats where goblin and gnome daredevils pay good coin for parts, fuel, and assistance with their perpetual rocket-car rivalry.",al={"why am i here","what is my purpose here","what do i do in thousand needles"},it="purpose",add=true}},ang={["race:Tauren"]="Freewind Post stands as a reminder of how high your people had to climb to escape centaur slaughter, and a staging ground against the treacherous Grimtotem at Darkcloud Pinnacle.",["race:Gnome"]="The Mirage Raceway in the Shimmering Flats is your faction's premier chance to demonstrate the precision and elegance of gnomish engineering over shoddy goblin contraptions.",["profession:Engineering"]="The salt flats are a pilgrimage site for tinkerers looking to study rocket fuel, vehicle parts, and high-speed propulsion at the Mirage Raceway.",["faction:Horde"]="The Great Lift links the Barrens to your stronghold at Freewind Post, serving as a strategic southern boundary against centaur clans and rebel tauren."},kw={"cliffwatcher longhorn","darkcloud pinnacle","fizzle brassbolts","freewind post","great lift","grimtotem","kravel koalbeard","mirage raceway","pozzik","shimmering flats","thousand needles"},rel={"subzone:freewind-post","subzone:shimmering-flats","subzone:mirage-raceway","subzone:great-lift","subzone:darkcloud-pinnacle","zone:barrens","zone:feralas","zone:tanaris"},m={levels="25-35"},src={"Thousand Needles (Classic)","Thousand Needles"}}
